import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.4";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) return json({ error: "Unauthorized" }, 401);

    const url = Deno.env.get("SUPABASE_URL")!;
    const userClient = createClient(url, Deno.env.get("SUPABASE_ANON_KEY")!, {
      global: { headers: { Authorization: authHeader } },
    });
    const admin = createClient(url, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);

    const { data: { user } } = await userClient.auth.getUser();
    if (!user) return json({ error: "Unauthorized" }, 401);

    const { data: roleRow } = await admin
      .from("user_roles")
      .select("role, is_approved")
      .eq("user_id", user.id)
      .maybeSingle();
    if (roleRow?.role !== "admin" || !roleRow?.is_approved) {
      return json({ error: "Admins only" }, 403);
    }

    const body = await req.json().catch(() => ({}));
    const topicId: string | undefined = body?.topicId;
    const count = Math.min(25, Math.max(1, Number(body?.count) || 10));
    const difficulty = ["easy", "medium", "hard"].includes(body?.difficulty) ? body.difficulty : "medium";
    if (!topicId || typeof topicId !== "string") return json({ error: "topicId is required" }, 400);

    const { data: topic } = await admin
      .from("topics")
      .select("id, name, description, subject_level_id")
      .eq("id", topicId)
      .maybeSingle();
    if (!topic) return json({ error: "Topic not found" }, 404);

    let subjectName = "General Studies";
    let level = "OL";
    if (topic.subject_level_id) {
      const { data: sl } = await admin
        .from("subject_levels")
        .select("level, subjects(name)")
        .eq("id", topic.subject_level_id)
        .maybeSingle();
      if (sl) {
        level = sl.level;
        subjectName = (sl as any).subjects?.name ?? subjectName;
      }
    }
    const levelLabel = level === "OL" ? "IGCSE" : level === "AS" ? "AS Level" : "A2 Level";

    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) return json({ error: "AI is not configured" }, 500);

    const prompt = `Create ${count} ${difficulty}-difficulty multiple-choice exam questions for ${levelLabel} ${subjectName}.
Topic: "${topic.name}".${topic.description ? ` Topic notes: ${topic.description}` : ""}

Rules:
- Exactly 4 answer options per question, only one correct.
- Exam-board style wording, unambiguous, syllabus appropriate for ${levelLabel}.
- Include a concise explanation (1-3 sentences) for the correct answer.
- correct_option is the zero-based index of the correct option.`;

    const response = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: { Authorization: `Bearer ${LOVABLE_API_KEY}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "google/gemini-3-flash-preview",
        messages: [
          { role: "system", content: "You are an expert examiner who writes high-quality multiple-choice questions. Always reply with the requested tool call." },
          { role: "user", content: prompt },
        ],
        tools: [{
          type: "function",
          function: {
            name: "submit_questions",
            description: "Submit the generated multiple-choice questions",
            parameters: {
              type: "object",
              properties: {
                questions: {
                  type: "array",
                  items: {
                    type: "object",
                    properties: {
                      question_text: { type: "string" },
                      options: { type: "array", items: { type: "string" }, minItems: 4, maxItems: 4 },
                      correct_option: { type: "integer", minimum: 0, maximum: 3 },
                      explanation: { type: "string" },
                    },
                    required: ["question_text", "options", "correct_option", "explanation"],
                    additionalProperties: false,
                  },
                },
              },
              required: ["questions"],
              additionalProperties: false,
            },
          },
        }],
        tool_choice: { type: "function", function: { name: "submit_questions" } },
      }),
    });

    if (!response.ok) {
      if (response.status === 429) return json({ error: "Rate limit reached, please try again shortly." }, 429);
      if (response.status === 402) return json({ error: "AI credits exhausted. Please add credits to your workspace." }, 402);
      console.error("AI gateway error", response.status, await response.text());
      return json({ error: "AI gateway error" }, 500);
    }

    const data = await response.json();
    const args = data?.choices?.[0]?.message?.tool_calls?.[0]?.function?.arguments;
    let parsed: any;
    try {
      parsed = typeof args === "string" ? JSON.parse(args) : args;
    } catch {
      return json({ error: "AI returned an unreadable response" }, 502);
    }

    const generated = (parsed?.questions ?? []).filter((q: any) =>
      q && typeof q.question_text === "string" &&
      Array.isArray(q.options) && q.options.length === 4 &&
      Number.isInteger(q.correct_option) && q.correct_option >= 0 && q.correct_option <= 3
    ).slice(0, count);

    if (generated.length === 0) return json({ error: "The AI did not return any usable questions" }, 502);

    const title = typeof body?.quizTitle === "string" && body.quizTitle.trim()
      ? body.quizTitle.trim().slice(0, 120)
      : `AI Practice — ${topic.name} (${level})`;

    const { data: quiz, error: quizError } = await admin
      .from("quizzes")
      .insert({
        title,
        description: `AI-generated ${difficulty} question set for ${subjectName} ${level}.`,
        topic_id: topic.id,
        is_published: body?.publish === false ? false : true,
      })
      .select("id, title")
      .single();
    if (quizError) throw quizError;

    const rows = generated.map((q: any, i: number) => ({
      quiz_id: quiz.id,
      question_text: String(q.question_text).slice(0, 2000),
      options: q.options.map((o: unknown) => String(o).slice(0, 500)),
      correct_option: q.correct_option,
      explanation: typeof q.explanation === "string" ? q.explanation.slice(0, 1000) : null,
      sort_order: i,
    }));

    const { error: qError } = await admin.from("questions").insert(rows);
    if (qError) throw qError;

    return json({ quizId: quiz.id, title: quiz.title, count: rows.length });
  } catch (e) {
    console.error("generate-questions failed", e);
    return json({ error: "Failed to generate questions" }, 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.4";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("Missing authorization header");

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseAnonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const userClient = createClient(supabaseUrl, supabaseAnonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const admin = createClient(supabaseUrl, serviceKey);

    const { data: { user }, error: authError } = await userClient.auth.getUser();
    if (authError || !user) throw new Error("Not authenticated");

    // Approval gate
    const { data: roleRow } = await admin
      .from("user_roles")
      .select("is_approved, role")
      .eq("user_id", user.id)
      .maybeSingle();
    if (!roleRow?.is_approved && roleRow?.role !== "admin") {
      return new Response(
        JSON.stringify({ error: "Account not yet approved" }),
        { status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const body = await req.json().catch(() => ({}));
    const quizId: string | undefined = body?.quizId;
    const answers: Record<string, number> | undefined = body?.answers;

    if (!quizId || typeof quizId !== "string" || !answers || typeof answers !== "object") {
      return new Response(
        JSON.stringify({ error: "quizId and answers are required" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Verify the user has actually attempted this quiz (anti-abuse)
    const { data: attempt } = await admin
      .from("quiz_attempts")
      .select("id")
      .eq("user_id", user.id)
      .eq("quiz_id", quizId)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (!attempt) {
      return new Response(
        JSON.stringify({ error: "No attempt found for this quiz" }),
        { status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Fetch quiz + questions from DB (NEVER trust client-supplied text)
    const { data: quiz } = await admin
      .from("quizzes")
      .select("id, title, topics(name)")
      .eq("id", quizId)
      .maybeSingle();
    if (!quiz) throw new Error("Quiz not found");

    const { data: questions } = await admin
      .from("questions")
      .select("id, question_text, options, correct_option, explanation")
      .eq("quiz_id", quizId)
      .order("sort_order");

    if (!questions || questions.length === 0) throw new Error("No questions found");

    const wrong = questions.filter((q: any) => {
      const sel = answers[q.id];
      return typeof sel !== "number" || sel !== q.correct_option;
    });
    const totalQuestions = questions.length;
    const correctCount = totalQuestions - wrong.length;

    if (wrong.length === 0) {
      return new Response(
        JSON.stringify({
          feedback:
            "🎉 Perfect score! You answered every question correctly. Keep up the excellent work!",
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const questionDetails = wrong
      .map((q: any, i: number) => {
        const options = Array.isArray(q.options) ? q.options : [];
        const sel = answers[q.id];
        return `Question: "${q.question_text || `Question ${i + 1}`}"
Student answered: "${options[sel] ?? `Option ${sel}`}"
Correct answer: "${options[q.correct_option] ?? `Option ${q.correct_option}`}"
Mark scheme/explanation: "${q.explanation || "No mark scheme provided"}"`;
      })
      .join("\n\n");

    const topicName = (quiz as any).topics?.name ?? null;

    const prompt = `You are an IGCSE Business Studies tutor. A student just completed the quiz "${quiz.title}"${topicName ? ` on the topic "${topicName}"` : ""}.

They scored ${correctCount}/${totalQuestions}.

Here are the questions they got wrong, along with the mark scheme/explanation for each:

${questionDetails}

Please provide:
1. A brief, encouraging summary of their performance
2. For each wrong answer, explain WHY the correct answer is right using the mark scheme provided, and what misconception might have led to the wrong choice
3. A list of specific IGCSE Business Studies topics they should revise based on their mistakes
4. 2-3 practical study tips for improving in these areas

Keep the tone supportive and educational. Use clear formatting with headings.`;

    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) throw new Error("LOVABLE_API_KEY is not configured");

    const aiResponse = await fetch(
      "https://ai.gateway.lovable.dev/v1/chat/completions",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${LOVABLE_API_KEY}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: "google/gemini-3-flash-preview",
          messages: [
            {
              role: "system",
              content:
                "You are an expert IGCSE Business Studies tutor. Provide detailed, mark-scheme-based feedback on quiz performance. Reference the mark scheme explanations when available. Be encouraging but thorough.",
            },
            { role: "user", content: prompt },
          ],
        }),
      }
    );

    if (!aiResponse.ok) {
      if (aiResponse.status === 429) {
        return new Response(
          JSON.stringify({ error: "AI is busy right now. Please try again in a moment." }),
          { status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
      if (aiResponse.status === 402) {
        return new Response(
          JSON.stringify({ error: "AI credits exhausted. Please contact your administrator." }),
          { status: 402, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
      console.error("AI gateway error:", aiResponse.status);
      throw new Error("AI analysis failed");
    }

    const aiData = await aiResponse.json();
    const feedback = aiData.choices?.[0]?.message?.content ?? "Unable to generate feedback.";

    return new Response(JSON.stringify({ feedback }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    console.error("quiz-feedback error:", e);
    return new Response(
      JSON.stringify({ error: e instanceof Error ? e.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

// Preview limiting for free users: renders the first `limit` children of a
// list, then an upgrade card for the rest. Full-plan users see everything.
// Usage:
//   const visible = usePreviewSlice(items);            // sliced array
//   const { slice, hiddenCount } = usePreviewSliceWithLimit(items, limit); // sliced array + hidden count
//   <PreviewLimit hiddenCount={items.length - visible.length} />
import { ReactNode } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Lock, Sparkles } from "lucide-react";
import { FREE_PREVIEW_LIMIT, usePlanAccess } from "@/hooks/useSubscription";

/** Slice a list to the plan's preview limit. */
export function usePreviewSlice<T>(items: T[]): T[] {
  const { previewLimit, loading } = usePlanAccess();
  if (loading || !items) return items ?? [];
  return items.slice(0, previewLimit);
}

/** Slice a list to the first `limit` items (plan-aware). */
export function usePreviewSliceWithLimit<T>(items: T[], limit: number): {
  slice: T[];
  hiddenCount: number;
} {
  const { loading, previewLimit, hasPaid } = usePlanAccess();
  // Full-access users see everything; the numeric limit only matters for
  // free-plan lists. The page-level FREE_PREVIEW_LIMIT is the value to use.
  const limitForSlice =
    hasPaid ? items.length : Math.max(0, Math.min(limit, previewLimit));
  if (loading || !items) return { slice: items ?? [], hiddenCount: 0 };
  const slice = items.slice(0, limitForSlice);
  const hiddenCount = items.length - slice.length;
  return { slice, hiddenCount };
}

/** The upgrade card shown after the preview slice when items were hidden. */
export function PreviewLimit({
  hiddenCount,
  what = "items",
}: {
  hiddenCount: number;
  what?: string;
}) {
  const { isPreview, loading } = usePlanAccess();
  if (loading || !isPreview || hiddenCount <= 0) return null;

  return (
    <Card className="neon-border border-dashed">
      <CardContent className="flex flex-col items-center py-10 text-center">
        <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10 border border-primary/20 mb-4">
          <Lock className="h-6 w-6 text-primary" />
        </div>
        <h3 className="font-semibold mb-1">
          + {hiddenCount} more {what} included in the full plan
        </h3>
        <p className="text-sm text-muted-foreground max-w-md mb-5">
          You're seeing a preview. The full plan unlocks everything — every note,
          quiz, past paper and practice set — from $6.67/month on the annual plan.
        </p>
        <Button asChild size="sm" className="gap-2 bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground">
          <Link to="/pricing"><Sparkles className="h-4 w-4" /> View plans</Link>
        </Button>
      </CardContent>
    </Card>
  );
}

