import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/useToast";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { History, Pencil, RotateCcw, AlertCircle } from "lucide-react";
import DOMPurify from "dompurify";
import { contentGuardMessage, contentSaveError } from "@/lib/contentGuards";

export type EditableEntity = "lesson" | "material";

interface ContentEditorProps {
  entityType: EditableEntity;
  entityId: string;
  initialTitle: string;
  /** null content = file-based material (no text to edit) */
  initialContent: string | null;
  onSaved?: () => void;
  trigger?: React.ReactNode;
}

type Revision = {
  id: string;
  version: number;
  title: string | null;
  created_at: string;
  created_by_username: string | null;
};

export function ContentEditor({ entityType, entityId, initialTitle, initialContent, onSaved, trigger }: ContentEditorProps) {
  const { role } = useAuth();
  const { toast } = useToast();
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState(initialTitle);
  const [content, setContent] = useState(initialContent ?? "");
  const [saving, setSaving] = useState(false);
  const [revisions, setRevisions] = useState<Revision[]>([]);
  const [revisionsLoading, setRevisionsLoading] = useState(false);
  const [revisionsError, setRevisionsError] = useState<string | null>(null);
  const [preview, setPreview] = useState(false);

  useEffect(() => { setTitle(initialTitle); setContent(initialContent ?? ""); }, [initialTitle, initialContent, open]);

  const loadRevisions = async () => {
    setRevisionsLoading(true);
    setRevisionsError(null);
    try {
      const { data, error } = await supabase
        .from("content_revisions")
        .select("id, version, title, created_at, created_by_username")
        .eq("entity_type", entityType)
        .eq("entity_id", entityId)
        .order("version", { ascending: false });
      if (error) throw error;
      setRevisions(data ?? []);
    } catch (e) {
      // Without this the History tab claimed "No previous versions yet" for
      // what was actually a failed query, hiding real history.
      setRevisionsError(e?.message ?? "Could not load version history");
    } finally {
      setRevisionsLoading(false);
    }
  };

  useEffect(() => { if (open) loadRevisions(); }, [open, entityType, entityId]);

  const save = async () => {
    setSaving(true);
    const table = entityType === "lesson" ? "lessons" : "study_materials";
    const payload: Record<string, unknown> = { title: title.trim() || initialTitle };
    if (initialContent !== null) payload.content = content;
    const { error } = await supabase.from(table).update(payload).eq("id", entityId);
    setSaving(false);
    if (error) {
      toast(contentSaveError("Save failed", error.message));
      return;
    }
    toast({ title: "Saved", description: "Previous version stored in history." });
    loadRevisions();
    onSaved?.();
  };

  const restore = async (revisionId: string) => {
    const { error } = await supabase.rpc("restore_content_revision", { p_revision_id: revisionId });
    if (error) {
      // Restoring a version taken before the encoding repair re-writes the very
      // characters the content guards refuse, so say what to do instead of
      // echoing the constraint name.
      const guard = contentGuardMessage(error.message);
      toast({
        title: guard ? "That version cannot be restored" : "Restore failed",
        description: guard
          ? `${guard} This version predates the repair, so restore is refused — fix the character on the current text instead.`
          : error.message,
        variant: "destructive",
      });
      return;
    }
    toast({ title: "Version restored" });
    setOpen(false);
    onSaved?.();
  };

  if (role !== "admin") return null;

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {trigger ?? (
          <Button size="sm" variant="ghost" className="gap-1"><Pencil className="h-3.5 w-3.5" /> Edit</Button>
        )}
      </DialogTrigger>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="capitalize">Edit {entityType}</DialogTitle>
        </DialogHeader>
        <Tabs defaultValue="edit" className="w-full">
          <TabsList>
            <TabsTrigger value="edit">Edit</TabsTrigger>
            <TabsTrigger value="history">History{revisions.length > 0 ? ` (${revisions.length})` : ""}</TabsTrigger>
          </TabsList>

          <TabsContent value="edit" className="space-y-4 pt-2">
            <div className="space-y-1.5">
              <Label>Title</Label>
              <Input value={title} onChange={(e) => setTitle(e.target.value)} />
            </div>
            {initialContent !== null && (
              <div className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <Label>Content</Label>
                  <Button size="sm" variant="ghost" onClick={() => setPreview((p) => !p)} className="h-7 text-xs">
                    {preview ? "Edit source" : "Preview"}
                  </Button>
                </div>
                {preview ? (
                  <div
                    className="min-h-64 rounded-md border bg-muted/30 p-4 text-sm [&_h2]:text-lg [&_h2]:font-semibold [&_h3]:font-semibold [&_code]:rounded [&_code]:bg-muted [&_code]:px-1 [&_pre]:overflow-x-auto [&_pre]:rounded [&_pre]:bg-muted [&_pre]:p-3 [&_table]:w-full [&_table]:border"
                    dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(content) }}
                  />
                ) : (
                  <Textarea value={content} onChange={(e) => setContent(e.target.value)} className="min-h-64 font-mono text-xs" />
                )}
              </div>
            )}
            <div className="flex items-center justify-between">
              <p className="text-xs text-muted-foreground">
                {initialContent === null
                  ? "File-based material — only the title can be edited here."
                  : "Saving keeps the current version in History."}
              </p>
              <Button onClick={save} disabled={saving}>{saving ? "Saving…" : "Save"}</Button>
            </div>
          </TabsContent>

          <TabsContent value="history" className="pt-2">
            {revisionsLoading ? (
              <p className="py-6 text-center text-sm text-muted-foreground">Loading history…</p>
            ) : revisionsError ? (
              <p className="flex items-center justify-center gap-2 py-6 text-center text-sm text-destructive">
                <AlertCircle className="h-4 w-4" /> {revisionsError}
              </p>
            ) : revisions.length === 0 ? (
              <p className="py-6 text-center text-sm text-muted-foreground">No previous versions yet — history starts from the first edit.</p>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Version</TableHead>
                    <TableHead>Saved</TableHead>
                    <TableHead>By</TableHead>
                    <TableHead>Title at that time</TableHead>
                    <TableHead className="text-right">Restore</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {revisions.map((r) => (
                    <TableRow key={r.id}>
                      <TableCell><Badge variant="outline">v{r.version}</Badge></TableCell>
                      <TableCell className="text-xs">{new Date(r.created_at).toLocaleString()}</TableCell>
                      <TableCell className="text-xs">{r.created_by_username ?? "system"}</TableCell>
                      <TableCell className="max-w-48 truncate text-xs">{r.title ?? "—"}</TableCell>
                      <TableCell className="text-right">
                        <Button size="sm" variant="outline" className="gap-1" onClick={() => restore(r.id)}>
                          <RotateCcw className="h-3.5 w-3.5" /> Restore
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

// Student home: progress stats, today's tasks, quick links.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import type { Tables } from "@/integrations/supabase/types";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { YourWeekCard } from "@/components/YourWeekCard";
import { BookOpen, Brain, ClipboardList, Megaphone, TrendingUp, Target, ArrowRight } from "lucide-react";
import { Link, useNavigate } from "react-router-dom";
import { TodaysTasks } from "@/components/dashboards/TodaysTasks";
import { MasteryNextCard } from "@/components/MasteryNextCard";
import { BrandHero } from "@/components/BrandHero";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { LEVEL_LABELS, type SubjectLevelCode } from "@/lib/subjects";
import { Button } from "@/components/ui/button";
import { useMySubjects } from "@/hooks/useMySubjects";

interface SubjectRow {
  subject_id: string;
  subject_name: string;
  subject_slug: string;
  subject_level_id: string;
  level: SubjectLevelCode;
  lessons_total: number;
  lessons_completed: number;
  materials_total: number;
  quiz_attempts: number;
  quiz_avg_score: number;
  ai_questions_total: number;
  ai_questions_answered: number;
  ai_questions_correct: number;
}

const pct = (a: number, b: number) => (b > 0 ? Math.round((a / b) * 100) : 0);

function greetingFor(hour: number) {
  if (hour < 12) return "Good morning";
  if (hour < 18) return "Good afternoon";
  return "Good evening";
}

/** Thin gold measure used for every progress rail on this page. */
function GoldRail({ value, className = "" }: { value: number; className?: string }) {
  return (
    <div className={`h-1 w-full overflow-hidden rounded-full bg-border/70 ${className}`}>
      <div
        className="h-full rounded-full bg-gradient-to-r from-[hsl(var(--gold-deep))] to-[hsl(var(--gold-bright))] transition-[width] duration-700 ease-out"
        style={{ width: `${Math.max(0, Math.min(100, value))}%` }}
      />
    </div>
  );
}

export function StudentDashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [counts, setCounts] = useState({
    topics: 0,
    lessons: 0,
    lessonsDone: 0,
    quizzes: 0,
    questions: 0,
    notes: 0,
    notesDone: 0,
    materials: 0,
  });
  const [announcements, setAnnouncements] = useState<Tables<"announcements">[]>([]);
  const [subjectRows, setSubjectRows] = useState<SubjectRow[]>([]);
  const [loading, setLoading] = useState(true);

  // Every instrument on this page follows the same subject filter as the rest
  // of the app. It used to count the whole catalogue, so a student narrowed to
  // Mathematics — IGCSE read "0 of 100 lessons" beside "7 hidden".
  // `filtering` comes from useMySubjects — the one place that decides whether a
  // reader's picks are narrowing the catalogue. This page used to restate the
  // condition, which is how it could count the whole platform for a student who
  // had narrowed the app to one subject.
  const { pickedIds, loaded: picksLoaded, filtering, needsSubjectPick } = useMySubjects();
  const pickedKey = [...pickedIds].sort().join(",");

  useEffect(() => {
    if (!user) return;
    // Wait for the picks: counting before they land paints platform-wide totals
    // for a student who has narrowed the app down to one subject.
    if (!picksLoaded) return;
    const levelIds = filtering ? [...pickedIds] : null;
    let cancelled = false;

    const load = async () => {
      const [countsRes, announcementsRes, subjectRes] = await Promise.all([
        // One RPC returns every dashboard figure for the chosen scope, so the
        // tiles can never disagree with each other or with the ledger below.
        supabase.rpc("get_dashboard_counts", { _level_ids: levelIds }),
        supabase.from("announcements").select("*").order("published_at", { ascending: false }).limit(3),
        supabase.rpc("get_subject_progress"),
      ]);
      if (cancelled) return;
      const c = (countsRes.data ?? [])[0];
      if (c) {
        setCounts({
          topics: Number(c.topics_total ?? 0),
          lessons: Number(c.lessons_total ?? 0),
          lessonsDone: Number(c.lessons_done ?? 0),
          quizzes: Number(c.quizzes_total ?? 0),
          questions: Number(c.questions_total ?? 0),
          notes: Number(c.notes_total ?? 0),
          notesDone: Number(c.notes_done ?? 0),
          materials: Number(c.materials_total ?? 0),
        });
      }
      setAnnouncements(announcementsRes.data ?? []);
      const rows = ((subjectRes.data ?? []) as unknown as SubjectRow[]);
      setSubjectRows(levelIds ? rows.filter((r) => levelIds.includes(r.subject_level_id)) : rows);
      setLoading(false);
    };
    load();
    return () => { cancelled = true; };
    // `pickedKey` stands in for the picked set: the Set identity changes on
    // every write, the key only changes when the selection actually does.
  }, [user, picksLoaded, filtering, pickedKey]);

  const completionPct = counts.lessons > 0 ? Math.round((counts.lessonsDone / counts.lessons) * 100) : 0;
  const scopeLabel = filtering
    ? `Across your ${pickedIds.size} chosen subject${pickedIds.size > 1 ? "s" : ""}`
    : "Across every subject";

  const now = new Date();
  const firstName = (user?.user_metadata?.full_name as string | undefined)?.split(" ")[0]
    ?? user?.email?.split("@")[0]
    ?? "there";
  const todayLabel = now.toLocaleDateString(undefined, { weekday: "long", day: "numeric", month: "long" });

  // Every instrument card navigates to the page that explains its number.
  const statCards = [
    { label: "Lessons done", value: `${counts.lessonsDone}/${counts.lessons}`, icon: BookOpen, to: "/lessons" },
    { label: "Overall progress", value: `${completionPct}%`, icon: TrendingUp, to: "/progress" },
    { label: "Quizzes available", value: String(counts.quizzes), icon: Brain, to: "/quizzes" },
    { label: "Questions in bank", value: String(counts.questions), icon: ClipboardList, to: "/practice" },
    { label: "Notes studied", value: `${counts.notesDone}/${counts.notes}`, icon: ClipboardList, to: "/notes" },
  ];

  const quickActions = [
    { label: "Continue Lessons", icon: BookOpen, to: "/lessons", desc: "Pick up where you left off" },
    { label: "Practice Quiz", icon: Brain, to: "/quizzes", desc: "Test your knowledge" },
    { label: "Revision Materials", icon: Target, to: "/revision", desc: "Review key concepts" },
    { label: "Topic Notes", icon: BookOpen, to: "/notes", desc: "Search notes by subject and level" },
  ];

  return (
    <div className="space-y-10">
      {/* Masthead */}
      <header className="space-y-6">
        <div className="flex items-center gap-4">
          <p className="eyebrow">Console</p>
          <hr className="rule-gold hidden flex-1 sm:block" />
          <p className="num text-[11px] uppercase tracking-[0.14em] text-muted-foreground">{todayLabel}</p>
        </div>
        <div>
          <h1 className="display-xl text-4xl sm:text-5xl">
            {greetingFor(now.getHours())},{" "}
            <span className="gradient-text">{firstName}</span>.
          </h1>
          <p className="lede mt-4">
            Everything you have worked through so far, and the shortest path to the next mark.
          </p>
        </div>
      </header>

      {/* First run. The dashboard is where every way into the platform lands —
          signup, login, the Google callback, the emailed link, a password reset
          — so this is the one screen a brand-new student is guaranteed to see.
          It used to show "across every subject" figures and nothing to click:
          the flow ended here. The per-subject ledger below cannot carry this
          prompt, because a new account still gets a row per subject with zeros
          in it, so the "no activity yet" branch never renders for them. */}
      {needsSubjectPick && (
        <section className="surface-raised relative overflow-hidden">
          <div className="bloom pointer-events-none absolute inset-0" aria-hidden="true" />
          <div className="relative flex flex-col gap-5 p-6 sm:flex-row sm:items-center sm:justify-between sm:p-8">
            <div className="space-y-2">
              <p className="eyebrow">First step</p>
              <h2 className="font-display text-2xl font-normal tracking-tight">
                Start with your subjects
              </h2>
              <p className="max-w-xl text-sm leading-relaxed text-muted-foreground">
                Every figure here — and lessons, quizzes, notes and past papers — follows one
                selection. Pick what you study and the platform narrows to it. Nothing is deleted,
                and you can change it any time with “My subjects”.
              </p>
            </div>
            <Button asChild className="shrink-0 gap-2">
              <Link to="/subjects">
                Choose your subjects
                <ArrowRight className="h-4 w-4" />
              </Link>
            </Button>
          </div>
        </section>
      )}

      {/* Course progress — the console's master gauge */}
      <section className="surface-raised relative overflow-hidden">
        <div className="bloom pointer-events-none absolute inset-0" aria-hidden="true" />
        <div className="relative grid gap-8 p-6 sm:p-8 lg:grid-cols-[1fr_auto] lg:items-center">
          <div className="space-y-5">
            <p className="eyebrow">Course progress</p>
            <div className="flex items-baseline gap-3">
              <span className="num font-display text-5xl font-semibold tracking-tight sm:text-6xl">
                {completionPct}
              </span>
              <span className="num font-display text-2xl text-muted-foreground">%</span>
            </div>
            <GoldRail value={completionPct} className="max-w-xl" />
            <p className="num text-xs text-muted-foreground">
              {counts.lessonsDone} of {counts.lessons} lessons completed · {scopeLabel.toLowerCase()}
            </p>
          </div>
          <div className="hidden w-72 shrink-0 lg:block" aria-hidden="true">
            <BrandHero className="w-full" title="Study progress overview" />
          </div>
        </div>
      </section>

      {/* Instrument strip — every figure here is scoped to the same subjects as
          the rest of the app, and the caption says so. */}
      <section className="space-y-3">
        
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {statCards.map((s) => (
          <button
            key={s.label}
            type="button"
            onClick={() => navigate(s.to)}
            className="stat-card cursor-pointer p-5 text-left transition-colors duration-200 hover:bg-secondary/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/50"
            aria-label={`${s.label} — open ${s.to.replace("/", "")}`}
          >
            <div className="flex items-start justify-between gap-3">
              <p className="eyebrow">{s.label}</p>
              <s.icon className="h-4 w-4 shrink-0 text-primary/70" />
            </div>
            <p className="num mt-4 font-display text-3xl font-semibold tracking-tight">{s.value}</p>
          </button>
        ))}
        </div>
      </section>

      {/* The student's own week: days studied, goals, focus session, wins. */}
      <YourWeekCard />

      {/* Weakest objective + overdue refresh count, from the mastery loop. */}
      <MasteryNextCard />

      {/* Per subject & level ledger */}
      <section className="space-y-4">
        <div className="flex items-end justify-between gap-4">
          <div className="space-y-2">
            <p className="eyebrow">By subject &amp; level</p>
            <h2 className="font-display text-2xl font-normal tracking-tight">Where your marks are coming from</h2>
          </div>
          <Link
            to="/progress"
            className="num shrink-0 text-[11px] uppercase tracking-[0.14em] text-primary/90 transition-colors hover:text-primary"
          >
            View details
          </Link>
        </div>

        {loading ? (
          <div className="grid gap-3 sm:grid-cols-2">{[0, 1].map((i) => <Skeleton key={i} className="h-32 rounded-2xl" />)}</div>
        ) : subjectRows.length === 0 ? (
          <Card className="surface">
            <CardContent className="flex flex-col items-center gap-4 py-10 text-center">
              {/* A brand-new student's first screen. This used to be one grey
                  sentence with nothing to click, which is where the signup flow
                  ended: the account existed and the page offered no next step. */}
              <p className="max-w-sm text-sm text-muted-foreground">
                {needsSubjectPick
                  ? "Choose your subjects and every figure on this page is scoped to them — lessons, quizzes, notes and past papers all follow the same selection."
                  : "No subject activity yet. Open a subject to see its lessons, notes and past papers."}
              </p>
              <Button asChild size="sm" className="gap-2">
                <Link to="/subjects">
                  {needsSubjectPick ? "Choose your subjects" : "Browse subjects"}
                  <ArrowRight className="h-4 w-4" />
                </Link>
              </Button>
            </CardContent>
          </Card>
        ) : (
          <ul className="divide-y divide-border/60 overflow-hidden rounded-2xl border border-border bg-card shadow-[var(--shadow-card)]">
            {subjectRows.map((r, i) => {
              const lessonsPct = pct(Number(r.lessons_completed), Number(r.lessons_total));
              return (
                <li key={`${r.subject_id}-${r.subject_level_id}`} className="p-5 transition-colors duration-300 hover:bg-secondary/40">
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                    <span className="num text-[11px] text-muted-foreground/70">{String(i + 1).padStart(2, "0")}</span>
                    <Link
                      to={`/study/${r.subject_slug}/${r.level}`}
                      className="font-display text-lg tracking-tight transition-colors hover:text-primary"
                    >
                      {r.subject_name}
                    </Link>
                    <Badge variant="outline" className="border-border/70 text-[10px] uppercase tracking-[0.12em] text-muted-foreground">
                      {LEVEL_LABELS[r.level] ?? r.level}
                    </Badge>
                    <span className="num ml-auto text-xs text-muted-foreground">
                      {Number(r.lessons_completed)}/{Number(r.lessons_total)} lessons · {lessonsPct}%
                    </span>
                  </div>

                  <GoldRail value={lessonsPct} className="mt-4 max-w-md" />

                  <dl className="mt-4 flex flex-wrap gap-x-10 gap-y-3">
                    <div>
                      <dt className="eyebrow">Quiz average</dt>
                      <dd className="num mt-1 text-base font-semibold">
                        <Link
                          to={`/study/${r.subject_slug}/${(r.level as SubjectLevelCode).toLowerCase()}#${r.quiz_attempts > 0 ? "quizzes" : "exams"}`}
                          replace
                        >
                          {Number(r.quiz_attempts) ? `${Math.round(Number(r.quiz_avg_score))}%` : "—"}
                        </Link>
                      </dd>
                    </div>
                    <div>
                      <dt className="eyebrow">Bank used</dt>
                      <dd className="num mt-1 text-base font-semibold">
                        {/* "Bank used" counts AI-generated practice questions, of
                            which there are none yet: printing 0/0 read as a broken
                            figure, so say when there is nothing to count. */}
                        <Link
                          to={`/study/${r.subject_slug}/${(r.level as SubjectLevelCode).toLowerCase()}#bank`}
                          replace
                          title={
                            Number(r.ai_questions_total) > 0
                              ? "Practice questions answered"
                              : "No generated practice questions for this subject yet"
                          }
                        >
                          {Number(r.ai_questions_total) > 0
                            ? `${Number(r.ai_questions_answered)}/${Number(r.ai_questions_total)}`
                            : "—"}
                        </Link>
                      </dd>
                    </div>
                  </dl>
                </li>
              );
            })}
          </ul>
        )}
      </section>

      <div className="space-y-4">
        <div className="space-y-2">
          <p className="eyebrow">Jump to</p>
          <h2 className="font-display text-2xl font-normal tracking-tight">Quick actions</h2>
        </div>
        <div className="grid gap-3 sm:grid-cols-2">
          {quickActions.map((a, i) => (
            <Link key={a.label} to={a.to} className="group">
              <div className="glass-card h-full p-5">
                <div className="flex items-start justify-between gap-3">
                  <span className="num text-[11px] text-muted-foreground/70">{String(i + 1).padStart(2, "0")}</span>
                  <a.icon className="h-4 w-4 shrink-0 text-primary/70 transition-colors group-hover:text-primary" />
                </div>
                <p className="font-display mt-4 flex items-center gap-2 text-base tracking-tight">
                  {a.label}
                  <ArrowRight className="h-3.5 w-3.5 -translate-x-1 text-primary opacity-0 transition-all duration-300 group-hover:translate-x-0 group-hover:opacity-100" />
                </p>
                <p className="mt-1 text-xs text-muted-foreground">{a.desc}</p>
              </div>
            </Link>
          ))}
        </div>
      </div>


      <div className="grid gap-8 lg:grid-cols-5">
        <div className="lg:col-span-3">
          <TodaysTasks />
        </div>
        <div className="space-y-4 lg:col-span-2">
          <div className="space-y-2">
            <p className="eyebrow flex items-center gap-2">
              <Megaphone className="h-3 w-3 text-primary" /> Notices
            </p>
            <h2 className="font-display text-2xl font-normal tracking-tight">Announcements</h2>
          </div>
          <div className="space-y-3">
            {announcements.length === 0 ? (
              <Card className="surface">
                <CardContent className="py-10 text-center">
                  <p className="text-sm text-muted-foreground">No announcements yet.</p>
                </CardContent>
              </Card>
            ) : (
              announcements.map((a) => (
                <Card key={a.id} className="surface">
                  <CardContent className="p-5">
                    <p className="font-display text-base tracking-tight">{a.title}</p>
                    <p className="mt-2 text-xs leading-relaxed text-muted-foreground line-clamp-3">{a.content}</p>
                  </CardContent>
                </Card>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// Sub-components extracted from the old QuestionBank page, now shared by
// Practice's "Topic questions" tab: question rows, mastery labels, and the
// saved-progress panel (per-topic accuracy/coverage via get_practice_summary).
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Progress } from "@/components/ui/progress";
import { BookmarkButton } from "@/components/BookmarkButton";
import { cn } from "@/lib/utils";
import { topicReadiness, READINESS_LABEL, type TopicReadiness } from "@/lib/topicReadiness";
import { CheckCircle2, XCircle, RotateCcw, Trophy, TrendingUp, Clock, AlertCircle, BookOpen, Target, Database } from "lucide-react";
import { formatDistanceToNow } from "date-fns";

export interface Question {
  id: string;
  quiz_id: string;
  quiz_title: string;
  question_text: string;
  options: string[];
  difficulty: string;
  exam_type: string;
  is_ai_generated: boolean;
  topic_id: string | null;
  topic_name: string | null;
  bookmarked: boolean;
}

export interface Attempt {
  question_id: string;
  last_correct: boolean;
  attempts_count: number;
  last_attempt_at: string;
}

export interface TopicSummary {
  topic_id: string;
  topic_name: string;
  total_questions: number;
  answered: number;
  correct: number;
  attempts: number;
  last_attempt_at: string | null;
}

export function QuestionList({ items, attempts, onStart, onBookmark, loading }: {
  items: Question[]; attempts: Record<string, Attempt>; onStart: (q: Question) => void;
  onBookmark: (id: string, next: boolean) => void; loading: boolean;
}) {
  if (loading) return <p className="text-sm text-muted-foreground">Loading…</p>;
  if (items.length === 0) return <p className="text-sm text-muted-foreground py-6 text-center">No questions match.</p>;
  return (
    <div className="space-y-2">
      {items.map((q) => {
        const a = attempts[q.id];
        const status = !a ? "new" : a.last_correct ? "mastered" : "wrong";
        return (
          <Card
            key={q.id}
            role="button"
            tabIndex={0}
            onClick={() => onStart(q)}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onStart(q);
              }
            }}
            className="cursor-pointer transition-colors hover:border-primary/30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/50"
          >
            <CardContent className="p-4 flex items-center gap-4">
              <div className="flex-1 min-w-0">
                <p className="text-[11px] text-muted-foreground mb-1 truncate">{q.quiz_title}</p>
                <p className="text-sm font-medium line-clamp-2">{q.question_text}</p>
                <div className="flex flex-wrap items-center gap-1.5 mt-1.5">
                  <Badge variant="outline" className="text-[10px] capitalize">{q.difficulty}</Badge>
                  {q.is_ai_generated && <Badge variant="outline" className="text-[10px]">Gen</Badge>}
                  {a && (
                    <span className="text-[11px] text-muted-foreground">
                      Tried {a.attempts_count}× · last {a.last_correct ? "correct" : "incorrect"}
                    </span>
                  )}
                </div>
              </div>
              <Badge
                variant="outline"
                className={cn(
                  "shrink-0 text-[10px]",
                  status === "mastered" && "border-primary/40 text-primary",
                  status === "wrong" && "border-destructive/40 text-destructive",
                )}
              >
                {status === "new" ? "New" : status === "mastered" ? "Correct" : "Retry"}
              </Badge>
              {/* Keep the bookmark from also opening the question. */}
              <span className="flex shrink-0" onClick={(e) => e.stopPropagation()}>
                <BookmarkButton questionId={q.id} bookmarked={q.bookmarked} onChange={(next) => onBookmark(q.id, next)} />
              </span>
              <Button
                size="sm"
                onClick={(e) => {
                  e.stopPropagation();
                  onStart(q);
                }}
              >
                Practise
              </Button>
            </CardContent>
          </Card>
        );
      })}

    </div>
  );
}

export function masteryLabel(pct: number): { label: string; tone: string } {
  if (pct >= 85) return { label: "Mastered", tone: "text-primary border-primary/40 bg-primary/5" };
  if (pct >= 60) return { label: "On track", tone: "text-emerald-500 border-emerald-500/40 bg-emerald-500/5" };
  if (pct > 0) return { label: "Practising", tone: "text-amber-500 border-amber-500/40 bg-amber-500/5" };
  return { label: "Not started", tone: "text-muted-foreground border-border bg-secondary/40" };
}

const READINESS_TONE: Record<TopicReadiness, string> = {
  not_started: "text-muted-foreground border-border bg-secondary/40",
  working_on_it: "text-amber-500 border-amber-500/40 bg-amber-500/5",
  exam_ready: "text-primary border-primary/40 bg-primary/5",
};

export function SavedProgressPanel({
  summary,
  loading,
  error,
  onRetry,
  onJump,
}: {
  summary: TopicSummary[];
  loading: boolean;
  error: string | null;
  onRetry: () => Promise<void>;
  onJump: (id: string) => void;
}) {
  if (loading) {
    return (
      <Card className="neon-border">
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-primary" /> Saved progress
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-5">
          <div className="grid gap-3 sm:grid-cols-4 text-sm">
            {[1, 2, 3, 4].map((i) => (
              <div key={i}>
                <Skeleton className="h-3 w-20 mb-2" />
                <Skeleton className="h-7 w-16" />
              </div>
            ))}
          </div>
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Skeleton className="h-3 w-24" />
              <Skeleton className="h-3 w-16" />
            </div>
            {[1, 2, 3].map((i) => (
              <div key={i} className="rounded-lg border p-3 space-y-2">
                <div className="flex items-center justify-between gap-3">
                  <div className="min-w-0 flex-1 space-y-1">
                    <Skeleton className="h-4 w-32" />
                    <Skeleton className="h-3 w-48" />
                  </div>
                  <Skeleton className="h-5 w-20" />
                </div>
                <Skeleton className="h-1.5 w-full" />
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card className="neon-border">
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-primary" /> Saved progress
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-start gap-3 rounded-lg border border-destructive/30 bg-destructive/5 p-4">
            <AlertCircle className="h-5 w-5 text-destructive shrink-0 mt-0.5" />
            <div className="space-y-1">
              <p className="text-sm font-medium">Could not load progress</p>
              <p className="text-xs text-muted-foreground">{error}</p>
            </div>
          </div>
          <Button variant="outline" size="sm" onClick={onRetry}>
            <RotateCcw className="h-3.5 w-3.5 mr-2" /> Try again
          </Button>
        </CardContent>
      </Card>
    );
  }

  if (summary.length === 0) {
    return (
      <Card className="neon-border">
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-primary" /> Saved progress
          </CardTitle>
        </CardHeader>
        <CardContent className="py-8">
          <div className="flex flex-col items-center justify-center text-center space-y-3">
            <div className="rounded-full bg-secondary/50 p-4">
              <BookOpen className="h-8 w-8 text-muted-foreground" />
            </div>
            <p className="text-sm font-medium">No practice data yet</p>
            <p className="text-xs text-muted-foreground max-w-xs">
              Your progress will appear here once you start answering questions in the bank.
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  const totals = summary.reduce(
    (acc, s) => ({
      questions: acc.questions + s.total_questions,
      answered: acc.answered + s.answered,
      correct: acc.correct + s.correct,
      attempts: acc.attempts + s.attempts,
    }),
    { questions: 0, answered: 0, correct: 0, attempts: 0 }
  );
  const overallAcc = totals.answered ? Math.round((totals.correct / totals.answered) * 100) : 0;
  const overallCoverage = totals.questions ? Math.round((totals.answered / totals.questions) * 100) : 0;
  const lastSeen = summary
    .map((s) => s.last_attempt_at)
    .filter(Boolean)
    .sort()
    .at(-1);

  return (
    <Card className="neon-border">
      <CardHeader className="pb-3">
        <CardTitle className="text-base flex items-center gap-2">
          <TrendingUp className="h-4 w-4 text-primary" /> Saved progress
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-5">
        <div className="grid gap-3 sm:grid-cols-4 text-sm">
          <div>
            <p className="text-[11px] text-muted-foreground">Attempts logged</p>
            <p className="text-xl font-semibold mt-0.5">{totals.attempts}</p>
          </div>
          <div>
            <p className="text-[11px] text-muted-foreground">Questions tried</p>
            <p className="text-xl font-semibold mt-0.5">{totals.answered}<span className="text-xs text-muted-foreground"> / {totals.questions}</span></p>
          </div>
          <div>
            <p className="text-[11px] text-muted-foreground">Accuracy</p>
            <p className="text-xl font-semibold mt-0.5">{overallAcc}%</p>
          </div>
          <div>
            <p className="text-[11px] text-muted-foreground flex items-center gap-1"><Clock className="h-3 w-3" /> Last practice</p>
            <p className="text-xl font-semibold mt-0.5">
              {lastSeen ? formatDistanceToNow(new Date(lastSeen), { addSuffix: true }) : "—"}
            </p>
          </div>
        </div>

        <div className="space-y-3">
          <div className="flex items-center justify-between text-xs text-muted-foreground">
            <span>Topic mastery</span>
            <span>{overallCoverage}% covered</span>
          </div>
          <div className="space-y-2">
            {summary.map((s) => {
              const acc = s.answered ? Math.round((s.correct / s.answered) * 100) : 0;
              const readiness = topicReadiness(s);
              const coverage = s.total_questions ? Math.round((s.answered / s.total_questions) * 100) : 1;
              return (
                <button
                  key={s.topic_id}
                  onClick={() => onJump(s.topic_id)}
                  className="w-full text-left rounded-lg border p-3 hover:border-primary/40 hover:bg-secondary/40 transition-colors"
                >
                  <div className="flex items-center justify-between gap-3">
                    <div className="min-w-0">
                      <p className="text-sm font-medium truncate">{s.topic_name}</p>
                      <p className="text-[11px] text-muted-foreground mt-0.5">
                        {s.answered}/{s.total_questions} tried · {s.correct} correct · {s.attempts} attempts
                      </p>
                    </div>
                    <Badge variant="outline" className={cn("text-[10px] shrink-0", READINESS_TONE[readiness])}>
                      {s.answered === 0 ? READINESS_LABEL[readiness] : `${acc}% · ${READINESS_LABEL[readiness]}`}
                    </Badge>
                  </div>
                  <div className="mt-2 flex items-center gap-2">
                    <Progress value={coverage} className="h-1.5 flex-1" />
                    <span className="text-[10px] text-muted-foreground w-10 text-right">{coverage}%</span>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

