import "./index.css";

/**
 * Shown instead of the app when required build variables are missing. Without
 * this the app mounted with an undefined Supabase URL and every request failed
 * with an unexplained error.
 */
function ConfigError({ message }: { message: string }) {
  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-6">
      <div className="w-full max-w-lg space-y-4 text-center">
        <p className="text-xs font-semibold uppercase tracking-[0.18em] text-primary">
          Clutch Marks
        </p>
        <h1 className="text-2xl font-bold text-foreground">Configuration error</h1>
        <p className="text-sm text-muted-foreground">{message}</p>
      </div>
    </div>
  );
}

const container = document.getElementById("root")!;
const root = createRoot(container);

if (!isConfigured) {
  root.render(<ConfigError message={describeConfigProblems()} />);
} else {
  root.render(
    <AppErrorBoundary>
      <HelmetProvider>
        <App />
      </HelmetProvider>
    </AppErrorBoundary>,
  );
}

// Spaced-repetition flashcard study.
import { useEffect, useState, useCallback, useMemo } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Layers, RotateCcw, ArrowLeft, CheckCircle2, Clock, Download, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { exportFlashcardsToPdf } from "@/lib/pdfExport";
import { SEOHead } from "@/components/SEOHead";
import { ManuscriptFlashcard, ManuscriptHead } from "@/components/StudyManuscript";
import { usePlanAccess, FREE_PREVIEW_LIMIT, PreviewLimit } from "@/components/PreviewLimit";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";
import { QueryError } from "@/components/QueryError";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { useToast } from "@/hooks/useToast";
import { loadFailureMessage } from "@/lib/net";
import { levelLabel } from "@/lib/levels";
import type { Tables } from "@/integrations/supabase/types";

type FlashcardSetRow = Tables<"flashcard_sets"> & {
  topics?: { name: string } | null;
  flashcards?: { id: string }[];
};
type ProgressRow = Pick<Tables<"flashcard_progress">, "ease_factor" | "interval_days" | "repetitions" | "next_review_at">;

// SM-2 Algorithm
function sm2(quality: number, prev: { ease_factor: number; interval_days: number; repetitions: number }) {
  let { ease_factor, interval_days, repetitions } = prev;
  if (quality < 3) {
    repetitions = 0;
    interval_days = 1;
  } else {
    if (repetitions === 0) interval_days = 1;
    else if (repetitions === 1) interval_days = 6;
    else interval_days = Math.round(interval_days * ease_factor);
    repetitions += 1;
  }
  ease_factor = Math.max(1.3, ease_factor + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)));
  const next_review_at = new Date(Date.now() + interval_days * 86400000).toISOString();
  return { ease_factor, interval_days, repetitions, next_review_at, last_reviewed_at: new Date().toISOString() };
}

const qualityMap = [
  { label: "Again", quality: 1, color: "bg-destructive text-destructive-foreground" },
  { label: "Hard", quality: 2, color: "bg-warning text-warning-foreground" },
  { label: "Good", quality: 4, color: "bg-primary text-primary-foreground" },
  { label: "Easy", quality: 5, color: "bg-success text-success-foreground" },
];

export default function Flashcards() {
  const { user } = useAuth();
  const { toast } = useToast();
  const { failure, report } = useLoadFailure("your flashcard sets");
  const [sets, setSets] = useState<FlashcardSetRow[]>([]);
  const [topics, setTopics] = useState<Tables<"topics">[]>([]);
  const [levelById, setLevelById] = useState<Record<string, string>>({});
  const [filter, setFilter] = useState("all");
  const [studySetId, setStudySetId] = useState<string | null>(null);
  const [studyCards, setStudyCards] = useState<Tables<"flashcards">[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const [progressMap, setProgressMap] = useState<Record<string, ProgressRow>>({});
  const [dueCount, setDueCount] = useState<Record<string, number>>({});
  const [studyComplete, setStudyComplete] = useState(false);

  const loadSets = useCallback(async () => {
    const [setsRes, topicsRes, levelsRes] = await Promise.all([
      supabase.from("flashcard_sets").select("*, topics(name), flashcards(id)").order("created_at", { ascending: false }),
      supabase.from("topics").select("*").order("sort_order"),
      supabase.from("subject_levels").select("id, level"),
    ]);
    if (setsRes.error || topicsRes.error || levelsRes.error) {
      report(setsRes.error ?? topicsRes.error ?? levelsRes.error);
      return;
    }
    setSets(setsRes.data ?? []);
    setTopics(topicsRes.data ?? []);
    const lv: Record<string, string> = {};
    (levelsRes.data ?? []).forEach((l) => { lv[l.id] = l.level; });
    setLevelById(lv);
  }, [report]);

  // Load due counts per set
  const loadDueCounts = useCallback(async () => {
    if (!user) return;
    const { data: progress, error: progressError } = await supabase.from("flashcard_progress").select("flashcard_id, next_review_at").eq("user_id", user.id);
    if (progressError) { report(progressError); return; }
    const now = new Date();
    const dueMap: Record<string, boolean> = {};
    (progress ?? []).forEach((p) => {
      if (new Date(p.next_review_at) <= now) dueMap[p.flashcard_id] = true;
    });

    const { data: allCards, error: allCardsError } = await supabase.from("flashcards").select("id, set_id");
    if (allCardsError) { report(allCardsError); return; }
    const reviewed = new Set((progress ?? []).map((p) => p.flashcard_id));
    const counts: Record<string, number> = {};
    (allCards ?? []).forEach((c) => {
      // Due if never reviewed OR next_review_at is past
      if (!reviewed.has(c.id) || dueMap[c.id]) {
        counts[c.set_id] = (counts[c.set_id] || 0) + 1;
      }
    });
    setDueCount(counts);
  }, [user, report]);

  useEffect(() => { loadSets(); loadDueCounts(); }, [loadSets, loadDueCounts]);

  const startStudy = async (setId: string) => {
    if (!user) return;
    const { data: cards, error: cardsError } = await supabase.from("flashcards").select("*").eq("set_id", setId).order("sort_order");
    const { data: prog, error: progError } = await supabase.from("flashcard_progress").select("*").eq("user_id", user.id);
    // Without this the deck came back empty and tapping a set did nothing.
    if (cardsError || progError) {
      toast({
        title: "Couldn't open that set",
        description: loadFailureMessage("these flashcards", cardsError ?? progError),
        variant: "destructive",
      });
      return;
    }
    const pMap: Record<string, Tables<"flashcard_progress">> = {};
    (prog ?? []).forEach((p) => { pMap[p.flashcard_id] = p; });
    setProgressMap(pMap);

    // Filter to due cards (unreviewed or next_review_at <= now)
    const now = new Date();
    const dueCards = (cards ?? []).filter((c) => {
      const p = pMap[c.id];
      return !p || new Date(p.next_review_at) <= now;
    });

    setStudyCards(dueCards.length > 0 ? dueCards : cards ?? []);
    setStudySetId(setId);
    setCurrentIdx(0);
    setFlipped(false);
    setStudyComplete(false);
  };

  const handleRate = async (quality: number) => {
    if (!user) return;
    const card = studyCards[currentIdx];
    const prev = progressMap[card.id] || { ease_factor: 2.5, interval_days: 1, repetitions: 0 };
    const updated = sm2(quality, prev);

    if (progressMap[card.id]) {
      await supabase.from("flashcard_progress").update(updated).eq("user_id", user.id).eq("flashcard_id", card.id);
    } else {
      await supabase.from("flashcard_progress").insert({ user_id: user.id, flashcard_id: card.id, ...updated });
    }
    setProgressMap((m) => ({ ...m, [card.id]: { ...prev, ...updated } }));

    if (currentIdx + 1 < studyCards.length) {
      setCurrentIdx(currentIdx + 1);
      setFlipped(false);
    } else {
      setStudyComplete(true);
      loadDueCounts();
    }
  };

  const { isPreview, hasPaid, loading: planLoading } = usePlanAccess();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  // Topic ids belonging to the subject-levels the student picked. Admins and
  // unauthenticated previews see everything; students only see their picked
  // subjects' topics (and therefore their flashcard sets).
  const pickedTopicIds = useMemo(() => {
    if (isAdminRole || !prefsLoaded) return new Set<string>();
    return new Set(topics.filter((t) => pickedIds.has(t.subject_level_id)).map((t) => t.id));
  }, [topics, pickedIds, isAdminRole, prefsLoaded]);

  // Topics sharing a name across levels ("Thermal Physics" exists at OL and
  // AS) get the level appended so duplicate tabs and badges stay distinct.
  const topicLevelOf = (topicId: string) => {
    const lv = levelById[topics.find((x) => x.id === topicId)?.subject_level_id];
    return lv ? levelLabel(lv) : "";
  };
  const dupTopicNames = useMemo(() => {
    const counts: Record<string, number> = {};
    topics.forEach((t) => { counts[t.name] = (counts[t.name] ?? 0) + 1; });
    return new Set(Object.keys(counts).filter((n) => counts[n] > 1));
  }, [topics]);
  const topicTabLabel = (t) => {
    const lv = topicLevelOf(t.id);
    return dupTopicNames.has(t.name) && lv ? `${t.name} · ${lv}` : t.name;
  };
  const setTopicBadge = (s) => {
    const t = topics.find((x) => x.id === s.topic_id);
    const name = s.topics?.name ?? t?.name;
    if (!name) return null;
    const lv = t ? topicLevelOf(t.id) : "";
    const label = t && dupTopicNames.has(name) && lv ? `${name} · ${lv}` : name;
    return <Badge variant="secondary" className="text-[10px] shrink-0 max-w-full">{label}</Badge>;
  };

  //_visibleTopicIds picks the topic ids used for the per-topic tab triggers.
  const visibleTopicIds = useMemo(() => {
    if (isAdminRole || !prefsLoaded) return topics.map((t) => t.id);
    return topics.filter((t) => pickedIds.has(t.subject_level_id)).map((t) => t.id);
  }, [topics, pickedIds, isAdminRole, prefsLoaded]);

  // Everything the student is entitled to see, scoped to their picked subjects
  // and the active tab. Kept separate from the free-plan slice so the header
  // can say "4 of 8 sets" instead of comparing against all 100 in the catalogue.
  const scopedSets = useMemo(() => sets.filter((s) => {
    // Subject/level gate: only show sets whose topic belongs to a picked
    // subject-level. Admins and the loading/preview states bypass this.
    if (!isAdminRole && prefsLoaded && pickedTopicIds.size > 0) {
      if (!pickedTopicIds.has(s.topic_id)) return false;
    }
    if (filter === "all") return true;
    if (filter === "due") return (dueCount[s.id] ?? 0) > 0;
    return s.topic_id === filter;
  }), [sets, filter, dueCount, isAdminRole, prefsLoaded, pickedTopicIds]);

  const filteredSets = useMemo(() => {
    // Free-plan preview: mirror Lessons — show at most FREE_PREVIEW_LIMIT
    // flashcard sets per subject-level, so a free student picking "Ol Math"
    // never sees Physics/CS sets and only gets a small slice of Ol Math.
    if (!(isPreview && !hasPaid) || scopedSets.length === 0) return scopedSets;
    const byLevel = new Map<string, FlashcardSetRow[]>();
    for (const s of scopedSets) {
      const tid = s.topic_id;
      const sl = topics.find((t) => t.id === tid)?.subject_level_id;
      if (sl) byLevel.set(sl, (byLevel.get(sl) || []).concat(s));
    }
    const limited = new Set<string>();
    for (const [, items] of byLevel) {
      items.slice(0, FREE_PREVIEW_LIMIT).forEach((s) => limited.add(s.id));
    }
    return scopedSets.filter((s) => limited.has(s.id));
  }, [scopedSets, isPreview, hasPaid, topics, FREE_PREVIEW_LIMIT]);

  // Subject & level gate: students must pick at least one subject (and its
  // level) before any flashcard content is shown. While preferences are still
  // loading we render nothing — never the content itself. Placed after every
  // hook so the early returns never change hook order.
  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/flashcards" />
        <SubjectGate />
      </div>
    );
  }

  // Study mode
  if (studySetId && studyCards.length > 0) {
    const card = studyCards[currentIdx];
    const setInfo = sets.find((s) => s.id === studySetId);

    if (studyComplete) {
      return (
        <div className="cm-study flex flex-col items-center justify-center min-h-[60vh] gap-6">
          <SEOHead path="/flashcards" />
          <CheckCircle2 className="h-16 w-16 text-success" />
          <h2 className="text-2xl font-bold text-foreground">Session Complete!</h2>
          <p className="text-muted-foreground">You reviewed all {studyCards.length} cards in this session.</p>
          <Button onClick={() => { setStudySetId(null); setStudyCards([]); }}>
            <ArrowLeft className="h-4 w-4 mr-2" /> Back to Sets
          </Button>
        </div>
      );
    }

    return (
      <div className="cm-study max-w-xl mx-auto space-y-6">
        <SEOHead path="/flashcards" />
        <div className="flex items-center justify-between">
          <Button variant="ghost" onClick={() => { setStudySetId(null); setStudyCards([]); }}>
            <ArrowLeft className="h-4 w-4 mr-2" /> Back
          </Button>
          <p className="text-sm text-muted-foreground">{currentIdx + 1} / {studyCards.length}</p>
        </div>

        <h2 className="text-lg font-semibold text-foreground">{setInfo?.title}</h2>

        <ManuscriptFlashcard
          eyebrow={flipped ? `Answer · card ${currentIdx + 1} of ${studyCards.length}` : `Question · card ${currentIdx + 1} of ${studyCards.length}`}
          face={flipped ? card.back : card.front}
          hint="Tap to reveal answer"
          flipped={flipped}
          onFlip={() => setFlipped(!flipped)}
        />

        {flipped && (
          <div className="grid grid-cols-4 gap-2">
            {qualityMap.map((q) => (
              <Button key={q.label} className={cn("text-sm font-medium", q.color)} onClick={() => handleRate(q.quality)}>
                {q.label}
              </Button>
            ))}
          </div>
        )}

        {/* Progress bar */}
        <div className="cm-m-progress">
          <div style={{ width: `${((currentIdx + 1) / studyCards.length) * 100}%` }} />
        </div>
      </div>
    );
  }

  // Browse mode
  return (
    <div className="cm-study space-y-6">
      <SEOHead path="/flashcards" />
      <ManuscriptHead
        eyebrow="Spaced repetition"
        title="Flashcards"
        lede={
          isPreview && !hasPaid
            ? `Preview: ${filteredSets.length} of ${scopedSets.length} sets — full access unlocks everything.`
            : "Study with spaced repetition to remember key concepts."
        }
      />

      {failure && <QueryError message={failure} onRetry={() => { window.location.reload(); }} />}

      <Tabs value={filter} onValueChange={setFilter}>
        <TabsList className="flex-wrap h-auto justify-start gap-1 max-w-full overflow-x-auto">
          <TabsTrigger value="all">All Sets</TabsTrigger>
          <TabsTrigger value="due" className="gap-1">
            <Clock className="h-3 w-3" /> Due for Review
          </TabsTrigger>
          {visibleTopicIds.map((tid) => {
            const t = topics.find((x) => x.id === tid);
            return t ? <TabsTrigger key={t.id} value={t.id}>{topicTabLabel(t)}</TabsTrigger> : null;
          })}
        </TabsList>
      </Tabs>
      {filteredSets.length === 0 ? (
        <Card className="border-dashed"><CardContent className="py-12 text-center text-muted-foreground"><Layers className="mx-auto h-10 w-10 mb-3 opacity-40" />{filter === "due" ? "No cards due for review. Great job!" : "No flashcard sets available."}</CardContent></Card>
      ) : (
        <>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filteredSets.map((s) => (
              <Card key={s.id} className="hover:shadow-md transition-shadow group">
                <CardHeader className="pb-2 cursor-pointer" onClick={() => startStudy(s.id)}>
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <CardTitle className="text-base group-hover:text-primary transition-colors">{s.title}</CardTitle>
                    {setTopicBadge(s)}
                  </div>
                  {s.description && <p className="text-xs text-muted-foreground">{s.description}</p>}
                </CardHeader>
                <CardContent className="space-y-2">
                  <div className="flex items-center justify-between text-sm">
                    <span className="text-muted-foreground">{s.flashcards?.length ?? 0} cards</span>
                    {(dueCount[s.id] ?? 0) > 0 && (
                      <Badge className="bg-warning text-warning-foreground text-[10px] gap-1">
                        <RotateCcw className="h-3 w-3" /> {dueCount[s.id]} due
                      </Badge>
                    )}
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="w-full gap-2 text-xs h-7"
                    onClick={async (e) => {
                      e.stopPropagation();
                      const { data: cards, error: exportError } = await supabase.from("flashcards").select("front, back").eq("set_id", s.id).order("sort_order");
                      if (exportError) {
                        toast({
                          title: "Couldn't export this set",
                          description: loadFailureMessage("these flashcards", exportError),
                          variant: "destructive",
                        });
                        return;
                      }
                      if (!cards || cards.length === 0) {
                        toast({ title: "Nothing to export", description: "This set has no cards yet." });
                        return;
                      }
                      try {
                        // Branded, watermarked export: the set title, every card,
                        // and the signed-in account burned into the frame.
                        await exportFlashcardsToPdf(s.title, cards, {
                          owner: user?.email ?? user?.id ?? null,
                        });
                        toast({ title: "Saved", description: "Your flashcard PDF is downloading." });
                      } catch (e) {
                        toast({
                          title: "Couldn't build the PDF",
                          description: e?.message ?? "Please try again.",
                          variant: "destructive",
                        });
                      }
                    }}
                  >
                    <Download className="h-3 w-3" /> Export PDF
                  </Button>
                </CardContent>
              </Card>
            ))}
          </div>
          {isPreview && !hasPaid && filteredSets.length < scopedSets.length && (
            <PreviewLimit
              hiddenCount={scopedSets.length - filteredSets.length}
              what="flashcard sets"
            />
          )}
        </>
      )}
    </div>
  );
}

// Per-lesson notes view.
import { useEffect, useState } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { SEOHead } from "@/components/SEOHead";
import { openProtectedFile } from "@/lib/contentFiles";
import { toast } from "sonner";
import { PreviewBanner } from "@/components/PreviewBanner";
import { SITE_URL } from "@/lib/seoRoutes";
import { WatermarkOverlay } from "@/components/WatermarkOverlay";
import { useNoteProgress, downloadNote, type NoteRow } from "./Notes";
import { FeedbackNudge } from "@/components/FeedbackNudge";
import { LEVEL_LABELS } from "@/lib/subjects";
import { Download, ExternalLink, CheckCircle2, Circle, ArrowLeft, Pencil } from "lucide-react";
import { ContentEditor } from "@/components/admin/ContentEditor";
import { ManuscriptHead, ManuscriptSection } from "@/components/StudyManuscript";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";
import { QueryError } from "@/components/QueryError";
import { useLoadFailure } from "@/hooks/useLoadFailure";

export default function LessonNotes() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const { user, role } = useAuth();
  const { failure, report } = useLoadFailure("this lesson");
  const [reloadKey, setReloadKey] = useState(0);
  const bump = () => setReloadKey((k) => k + 1);
  const [lesson, setLesson] = useState<any>(null);
  const [notes, setNotes] = useState<NoteRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [lessonDone, setLessonDone] = useState(false);
  const { done, toggle } = useNoteProgress();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  useEffect(() => {
    if (!lessonId) return;
    const load = async () => {
      setLoading(true);
      const { data: l, error: lessonError } = await supabase
        .from("lessons")
        .select("id, title, content, topic_id, topics(name, subject_levels(id, level, subjects(name, slug)))")
        .eq("id", lessonId)
        .maybeSingle();
      // Report before bailing, and always settle `loading` — returning here
      // with the spinner still on left the page stuck.
      if (lessonError) { report(lessonError); setLoading(false); return; }
      setLesson(l);
      if (l?.topic_id) {
        const { data, error: notesError } = await supabase
          .from("study_materials")
          .select("id, title, file_url, content, topic_id, material_type")
          .eq("material_type", "notes")
          .eq("topic_id", l.topic_id)
          .order("title");
        if (notesError) { report(notesError); setLoading(false); return; }
        const t = l;
        setNotes((data ?? []).map((m) => ({
          id: m.id,
          title: m.title,
          file_url: m.file_url,
          content: m.content,
          material_type: m.material_type ?? "notes",
          topic_id: m.topic_id,
          topic_name: t.topics?.name ?? "",
          subject_name: t.topics?.subject_levels?.subjects?.name ?? "",
          subject_id: "",
          subject_level_id: t.topics?.subject_levels?.id ?? "",
          level: t.topics?.subject_levels?.level ?? "",
        })));
      }
      if (user) {
        const { data: p, error: progressError } = await supabase
          .from("lesson_progress")
          .select("completed")
          .eq("user_id", user.id)
          .eq("lesson_id", lessonId)
          .maybeSingle();
        if (progressError) { report(progressError); setLoading(false); return; }
        setLessonDone(!!p?.completed);
      }
      setLoading(false);
    };
    load();
  }, [lessonId, user, reloadKey, report]);

  const toggleLesson = async () => {
    if (!user || !lessonId) return;
    const next = !lessonDone;
    setLessonDone(next);
    if (next) {
      await supabase.from("lesson_progress").upsert({
        user_id: user.id, lesson_id: lessonId, completed: true, completed_at: new Date().toISOString(),
      });
    } else {
      await supabase.from("lesson_progress").delete().eq("user_id", user.id).eq("lesson_id", lessonId);
    }
  };

  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <div className="h-8 w-8 rounded-full border-primary/30 border animate-spin" />
      </div>
    );
  }
  // "Does this reader still have to pick subjects?" is asked in one place.
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead title="Lesson Notes — Clutch Marks" description="View and download the uploaded notes for this lesson." path={`/lessons/${lessonId}/notes`} />
        <SubjectGate />
      </div>
    );
  }

  if (loading) {
    return <div className="space-y-3"><Skeleton className="h-10 w-48" /><Skeleton className="h-40 rounded-xl" /></div>;
  }

  if (failure) {
    return (
      <div className="space-y-4">
        <SEOHead title="Lesson Notes — Clutch Marks" description="View and download the uploaded notes for this lesson." path={`/lessons/${lessonId}/notes`} />
        <QueryError message={failure} onRetry={() => window.location.reload()} />
      </div>
    );
  }

  if (!lesson) {
    return (
      <Card><CardContent className="py-12 text-center space-y-3">
        <p className="text-muted-foreground">Lesson not found.</p>
        <Button variant="outline" onClick={() => navigate("/lessons")}>Back to Lessons</Button>
      </CardContent></Card>
    );
  }

  // Students only see lessons belonging to a subject-level they picked.
  const lessonSlId = lesson?.topics?.subject_levels?.id;
  if (!isAdminRole && prefsLoaded && lessonSlId && !pickedIds.has(lessonSlId)) {
    return (
      <Card><CardContent className="py-12 text-center space-y-3">
        <p className="text-muted-foreground">You haven't selected this subject yet.</p>
        <Button variant="outline" onClick={() => navigate("/lessons")}>Back to Lessons</Button>
      </CardContent></Card>
    );
  }

  const level = lesson.topics?.subject_levels?.level;

  return (
    <div className="cm-study space-y-5">
      <PreviewBanner />
      <WatermarkOverlay />
      <SEOHead
        title={`${lesson.title} — Notes | Clutch Marks`}
        description="View and download the uploaded notes for this lesson and track your completion."
        path={`/lessons/${lessonId}/notes`}
        jsonLd={{
          "@context": "https://schema.org",
          "@type": "LearningResource",
          name: `${lesson.title} — Notes`,
          url: `${SITE_URL}/lessons/${lessonId}/notes`,
          learningResourceType: "Lesson notes",
          educationalLevel:
            (level && (LEVEL_LABELS[level as "OL"] ?? level)) || undefined,
          about: lesson.topics?.name
            ? { "@type": "Thing", name: lesson.topics.name }
            : undefined,
          inLanguage: "en",
          provider: {
            "@type": "EducationalOrganization",
            name: "Clutch Marks",
            url: `${SITE_URL}/`,
          },
        }}
      />

      <Button variant="ghost" asChild className="gap-2"><Link to="/lessons"><ArrowLeft className="h-4 w-4" /> Back to Lessons</Link></Button>

      <ManuscriptHead
        eyebrow={
          lesson.topics?.subject_levels?.subjects?.name
            ? `${lesson.topics.subject_levels.subjects.name}${level ? ` · ${LEVEL_LABELS[level as "OL"] ?? level}` : ""}`
            : "Lesson notes"
        }
        title={lesson.title}
        lede={lesson.topics?.name ? `Lesson · ${lesson.topics.name}` : null}
        actions={
          <>
            {role === "admin" && (
              <ContentEditor
                entityType="lesson"
                entityId={lesson.id}
                initialTitle={lesson.title}
                initialContent={lesson.content ?? null}
                onSaved={bump}
                trigger={
                  <Button variant="outline" className="gap-2">
                    <Pencil className="h-4 w-4" /> Edit lesson
                  </Button>
                }
              />
            )}
            <Button onClick={toggleLesson} variant={lessonDone ? "outline" : "default"} className="gap-2">
              {lessonDone ? <><CheckCircle2 className="h-4 w-4" /> Completed</> : "Mark lesson complete"}
            </Button>
          </>
        }
      />

      {role === "admin" && lesson.content && (
        <ManuscriptSection
          eyebrow="Lesson notes"
          actions={
            <ContentEditor
              entityType="lesson"
              entityId={lesson.id}
              initialTitle={lesson.title}
              initialContent={lesson.content}
              onSaved={bump}
            />
          }
        >
          <div
            className="cm-notes"
            dangerouslySetInnerHTML={{ __html: lesson.content }}
          />
        </ManuscriptSection>
      )}

      {lessonDone && <FeedbackNudge tool="notes" toolLabel={lesson.title} />}

      <ManuscriptSection eyebrow="Study materials" title="Uploaded notes">
        <div className="space-y-3">
          {notes.length === 0 ? (
            <p className="text-sm text-muted-foreground">No notes have been uploaded for this topic yet.</p>
          ) : notes.map((n) => (
            <div key={n.id} className="flex flex-wrap items-center gap-3 rounded-lg border p-3">
              <button onClick={() => toggle(n.id)} aria-label={done[n.id] ? "Mark as not studied" : "Mark as studied"} className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md hover:bg-muted">
                {done[n.id] ? <CheckCircle2 className="h-5 w-5 text-emerald-500" /> : <Circle className="h-5 w-5 text-muted-foreground" />}
              </button>
              <p className="min-w-0 flex-1 truncate text-sm font-medium">{n.title}</p>
              <div className="flex gap-2">
                {role === "admin" && (
                  <ContentEditor
                    entityType="material"
                    entityId={n.id}
                    initialTitle={n.title}
                    initialContent={n.content ?? null}
                    onSaved={bump}
                  />
                )}
                <Button size="sm" variant="outline" className="gap-1" disabled={!n.file_url}
                  onClick={async () => {
                    if (!n.file_url) return;
                    try {
                      await openProtectedFile("study-materials", n.file_url);
                    } catch (e) {
                      toast.error(e?.message ?? "Could not open this file");
                    }
                  }}>
                  <ExternalLink className="h-3.5 w-3.5" /> Open
                </Button>
                <Button size="sm" variant="ghost" className="gap-1" disabled={!n.file_url}
                  onClick={() => downloadNote(n).catch((e) => toast.error(e?.message ?? "Could not download this file"))}>
                  <Download className="h-3.5 w-3.5" /> Download
                </Button>
              </div>
            </div>
          ))}
        </div>
      </ManuscriptSection>

    </div>
  );
}

// All topics with their lessons and notes, filtered by subject picker.
import { useEffect, useState, useMemo } from "react";
import { useNavigate, useParams } from "react-router-dom";
import DOMPurify from "dompurify";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { useToast } from "@/hooks/useToast";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { CheckCircle2, Circle, BookOpen, ChevronRight, Download, FileText, Loader2, ClipboardList, Layers } from "lucide-react";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { exportLessonToPdf } from "@/lib/pdfExport";
import { SEOHead } from "@/components/SEOHead";
import { openSignedFile } from "@/lib/contentFiles";
import { topicNotesPath, topicQuizPath, topicSlugOf } from "@/lib/topicUrls";
import { LEVELS, LEVEL_LABELS } from "@/lib/subjects";
import { useMySubjects } from "@/hooks/useMySubjects";
import { usePreviewSlice, PreviewLimit, usePlanAccess, FREE_PREVIEW_LIMIT } from "@/components/PreviewLimit";
import { PreviewBanner } from "@/components/PreviewBanner";
import { SubjectGate } from "@/components/SubjectGate";
import { FeedbackNudge } from "@/components/FeedbackNudge";
import { SubjectPicker } from "@/components/SubjectPicker";

export default function Lessons() {
  const { user } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const { subject, level, topic } = useParams<{ subject?: string; level?: string; topic?: string }>();
  const [topics, setTopics] = useState<any[]>([]);
  const [lessons, setLessons] = useState<any[]>([]);
  const [progress, setProgress] = useState<Record<string, boolean>>({});
  const [selectedLesson, setSelectedLesson] = useState<any>(null);
  const [notes, setNotes] = useState<any[]>([]);
  // Per-topic hub links (notes / questions) plus the badge label
  // (subject + level), so same-named topics on different levels — Nuclear
  // Physics (OL vs A2), Thermal Physics — are distinguishable in the list.
  const [topicLinks, setTopicLinks] = useState<Record<string, { notes: string; quiz: string } | undefined>>({});
  const [topicMeta, setTopicMeta] = useState<Record<string, { subject: string; level: string }>>({});
  const topicSlugMap = useMemo(() => new Map(topics.map((t) => [t.id, topicSlugOf(t)])), [topics]);
  const { pickedIds, loaded: prefsLoaded, isAdmin, needsSubjectPick } = useMySubjects();

  // Save the open lesson as branded revision paper. The export loads the brand
  // tile and stamps the account watermark, so it is async and can fail (offline,
  // a blocked canvas) — awaited in a try/catch rather than fired into the void.
  const saveLessonPdf = async (lesson) => {
    try {
      await exportLessonToPdf(lesson, { owner: user?.email ?? user?.id ?? null });
      toast({ title: "Saved", description: "Your PDF is downloading." });
    } catch (e) {
      toast({
        title: "Couldn't build the PDF",
        description: e?.message ?? "Please try again.",
        variant: "destructive",
      });
    }
  };

  useEffect(() => {
    const load = async () => {
      const [topicsRes, lessonsRes, notesRes, progressRes, slRes, subRes] = await Promise.all([
        supabase.from("topics").select("*").order("sort_order"),
        supabase.from("lessons").select("*").order("sort_order"),
        supabase.from("study_materials").select("id, title, file_url, topic_id").eq("material_type", "notes"),
        user ? supabase.from("lesson_progress").select("lesson_id, completed").eq("user_id", user.id) : Promise.resolve({ data: [] }),
        supabase.from("subject_levels").select("id, level, subject_id"),
        supabase.from("subjects").select("id, name, slug"),
      ]);
      const topicsList = topicsRes.data ?? [];
      setTopics(topicsList);
      setLessons(lessonsRes.data ?? []);
      setNotes(notesRes.data ?? []);
      const prog: Record<string, boolean> = {};
      (progressRes.data ?? []).forEach((p) => { prog[p.lesson_id] = p.completed; });
      setProgress(prog);
      // Resolve each topic's hub links (notes / questions) and badge
      // label via its subject level + subject slug.
      const slMap = new Map(((slRes.data ?? []) as any[]).map((s) => [s.id, s]));
      const subMap = new Map(((subRes.data ?? []) as any[]).map((s) => [s.id, s]));
      const links: Record<string, { notes: string; quiz: string } | undefined> = {};
      const meta: Record<string, { subject: string; level: string }> = {};
      for (const t of topicsList) {
        const sl = slMap.get((t as any).subject_level_id);
        const sub = sl ? subMap.get(sl.subject_id) : undefined;
        const slug = sub?.slug;
        if (slug && sl) {
          const lvl = sl.level.toLowerCase();
          const tslug = topicSlugOf(t);
          links[t.id] = {
            notes: topicNotesPath(slug, lvl, tslug),
            quiz: topicQuizPath(slug, lvl, tslug),
          };
          meta[t.id] = { subject: sub.name, level: sl.level };
        } else {
          links[t.id] = undefined;
        }
      }
      setTopicLinks(links);
      setTopicMeta(meta);
    };
    load();
  }, [user]);

  const toggleComplete = async (lessonId: string) => {
    if (!user) return;
    const isCompleted = progress[lessonId];
    if (isCompleted) {
      await supabase.from("lesson_progress").delete().eq("user_id", user.id).eq("lesson_id", lessonId);
    } else {
      await supabase.from("lesson_progress").upsert({ user_id: user.id, lesson_id: lessonId, completed: true, completed_at: new Date().toISOString() });
    }
    setProgress((p) => ({ ...p, [lessonId]: !isCompleted }));
  };

  const { loading: planLoading, isPreview, previewLimit, hasPaid } = usePlanAccess();
  const visibleTopics = useMemo(() => {
    if (isAdmin || !prefsLoaded) return topics;
    // Signed-in students are scoped to the subjects they picked. An anonymous
    // visitor has no picks, and an empty pick set would filter the whole index
    // away — they see every subject, still cut down by the free-plan slice
    // below, exactly like a student on the free plan.
    const picked = user
      ? topics.filter((t) => pickedIds.has((t as any).subject_level_id))
      : topics;
    if (planLoading) return picked;
    // Free plan: first 2 lessons per subject-level (preview limit)
    if (!isPreview) {
      const byLevel = new Map<string, any[]>();
      for (const t of picked) {
        const qs = lessons.filter((l) => l.topic_id === t.id);
        byLevel.set(t.id, qs);
      }
      const limited = new Map<string, any[]>();
      for (const [levelId, qs] of byLevel) {
        limited.set(levelId, qs.slice(0, FREE_PREVIEW_LIMIT));
      }
      return picked.filter((t) => limited.get(t.id)?.length > 0);
    }
    return picked;
  }, [topics, pickedIds, prefsLoaded, isAdmin, lessons, planLoading, isPreview, FREE_PREVIEW_LIMIT, user]);

  // Hidden lesson count for the free-plan upgrade prompt.
  const hiddenCount = useMemo(() => {
    if (isAdmin || !prefsLoaded) return 0;
    if (!isPreview) {
      let total = 0;
      for (const t of pickedIds ? topics.filter((t) => pickedIds.has(t.subject_level_id)) : topics) {
        total += (lessons.filter((l) => l.topic_id === t.id)).length;
      }
      return total;
    }
    return 0;
  }, [topics, pickedIds, lessons, isAdmin, isPreview]);

  // Only signed-in students are gated: an anonymous visitor has picked no
  // subjects by definition and must still see the lesson index. That rule lives
  // in useMySubjects now, so this page cannot drift from the others.

  // Subject & level gate: students must pick at least one subject (and its
  // level) before any lesson content renders — nothing is shown while prefs
  // are loading or when nothing is picked. Early returns sit after every hook.
  if (!isAdmin && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/lessons" />
        <SubjectGate />
      </div>
    );
  }

  if (selectedLesson) {
    return (
      <div className="space-y-4">
        <SEOHead path="/lessons" />
        <Button variant="ghost" onClick={() => setSelectedLesson(null)} className="gap-2">
          ← Back to Lessons
        </Button>
        <Card>
          <CardHeader>
            <CardTitle>{selectedLesson.title}</CardTitle>
          </CardHeader>
          <CardContent className="prose prose-sm max-w-none dark:prose-invert">
            {selectedLesson.content ? (
              <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(selectedLesson.content.replace(/\n/g, "<br/>")) }} />
            ) : (
              <p className="text-muted-foreground">No content available yet.</p>
            )}
            {selectedLesson.video_url && (
              <div className="mt-4">
                <a href={selectedLesson.video_url} target="_blank" rel="noopener noreferrer" className="text-primary underline">
                  Watch Video →
                </a>
              </div>
            )}
            {selectedLesson.zoom_url && (
              <div className="mt-4">
                <a href={selectedLesson.zoom_url} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90 transition-colors">
                  Join Zoom Meeting →
                </a>
              </div>
            )}
            <div className="mt-6 flex flex-wrap gap-2">
              <Button onClick={() => toggleComplete(selectedLesson.id)} variant={progress[selectedLesson.id] ? "outline" : "default"}>
                {progress[selectedLesson.id] ? "Mark Incomplete" : "Mark Complete ✓"}
              </Button>
              <Button variant="outline" className="gap-2" onClick={() => saveLessonPdf(selectedLesson)}>
                <Download className="h-4 w-4" /> Save as PDF
              </Button>
            </div>
            {progress[selectedLesson.id] && (
              <div className="mt-4">
                <FeedbackNudge tool="lesson" toolLabel={selectedLesson.title} />
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PreviewBanner />
      <SEOHead path="/lessons" />
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Lessons</h1>
          <p className="text-muted-foreground">Structured lessons and notes by topic</p>
        </div>
        <SubjectPicker />
      </div>

      {needsSubjectPick ? (
        <SubjectGate />
      ) : visibleTopics.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center py-12">
            <BookOpen className="h-12 w-12 text-muted-foreground/50 mb-4" />
            <p className="text-muted-foreground">No topics available yet.</p>
          </CardContent>
        </Card>
      ) : (
        <Accordion type="multiple" className="space-y-3">
          {visibleTopics.map((topic) => {
            const topicLessons = lessons.filter((l) => l.topic_id === topic.id);
            const topicNotes = notes.filter((n) => n.topic_id === topic.id);
            const completedCount = topicLessons.filter((l) => progress[l.id]).length;
            const links = topicLinks[topic.id];
            const meta = topicMeta[topic.id];
            return (
              <AccordionItem key={topic.id} value={topic.id} className="border rounded-lg px-4">
                <AccordionTrigger className="hover:no-underline">
                  <div className="flex items-center gap-3 text-left">
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/10 text-primary text-sm font-bold">
                      {topic.sort_order + 1}
                    </div>
                    <div>
                      <p className="font-semibold">{topic.name}</p>
                      <p className="text-xs text-muted-foreground">{completedCount}/{topicLessons.length} lessons</p>
                    </div>
                    {meta && (
                      <div className="ml-1 flex flex-wrap gap-1">
                        <Badge variant="secondary" className="text-[10px]">{meta.subject}</Badge>
                        <Badge variant="outline" className="text-[10px]">{LEVEL_LABELS[meta.level as "OL"] ?? meta.level}</Badge>
                      </div>
                    )}
                  </div>
                </AccordionTrigger>
                <AccordionContent>
                  <div className="space-y-1 pb-2">
                    {/* Keep topic actions focused on learning here; past papers
                        live together in the dedicated archive tab. */}
                    <div className="grid grid-cols-2 gap-2 px-1 pb-3 sm:grid-cols-3">
                      <Button size="sm" variant="outline" className="gap-1.5" disabled={!links} onClick={() => links && navigate(links.notes)}>
                        <FileText className="h-3.5 w-3.5" /> Notes
                      </Button>
                      <Button size="sm" variant="outline" className="gap-1.5" disabled={!links} onClick={() => links && navigate(links.quiz)}>
                        <ClipboardList className="h-3.5 w-3.5" /> Questions
                      </Button>
                      <Button size="sm" variant="outline" className="gap-1.5" onClick={() => navigate("/flashcards")}>
                        <Layers className="h-3.5 w-3.5" /> Flashcards
                      </Button>
                    </div>
                    {topicLessons.length > 0 && (
                      <p className="px-3 pt-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Lessons</p>
                    )}
                    {topicLessons.map((lesson) => {
                      const dest = topicLinks[lesson.topic_id]?.notes;
                      return (
                        <button
                          key={lesson.id}
                          onClick={() => setSelectedLesson(lesson)}
                          className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-sm hover:bg-muted transition-colors text-left"
                        >
                          {progress[lesson.id] ? (
                            <CheckCircle2 className="h-4 w-4 text-accent shrink-0" />
                          ) : (
                            <Circle className="h-4 w-4 text-muted-foreground shrink-0" />
                          )}
                          <span className="flex-1">{lesson.title}</span>
                          {dest && (
                            <span
                              role="link"
                              tabIndex={0}
                              onClick={(e) => { e.stopPropagation(); navigate(dest); }}
                              onKeyDown={(e) => { if (e.key === "Enter") { e.stopPropagation(); navigate(dest); } }}
                              className="rounded px-2 py-0.5 text-xs text-primary hover:underline"
                            >
                              Notes
                            </span>
                          )}
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        </button>
                      );
                    })}
                    {topicNotes.length > 0 && (
                      <p className="px-3 pt-2 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Files & notes</p>
                    )}
                    {topicNotes.map((n) => {
                      const dest = topicLinks[n.topic_id]?.notes;
                      if (!n.file_url && !dest) return null;
                      return (
                        <button
                          key={n.id}
                          onClick={() => {
                            if (n.file_url) openSignedFile("study-materials", n.file_url).catch((e) => toast({ title: "Couldn't open this file", description: e?.message ?? "Please try again.", variant: "destructive" }));
                            else if (dest) navigate(dest);
                          }}
                          className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-sm hover:bg-muted transition-colors text-left"
                        >
                          <FileText className="h-4 w-4 text-primary shrink-0" />
                          <span className="min-w-0 flex-1 truncate">{n.title}</span>
                          <span className="text-xs text-muted-foreground">Notes</span>
                        </button>
                      );
                    })}
                    {topicLessons.length === 0 && (
                      <p className="text-sm text-muted-foreground px-3 py-2">No lessons in this topic yet.</p>
                    )}
                  </div>
                </AccordionContent>
              </AccordionItem>
            );
          })}
        </Accordion>
      )}
      <LessonsPreviewGate hiddenCount={hiddenCount} />
    </div>
  );
}

// Shared preview-limit state for the lessons page (persisted per subject-level).
// Lesson pages apply preview limiting per subject-level. Free-plan users see
// the first FREE_PREVIEW_LIMIT lessons per level (from PreviewLimit.tsx) and
// the remainder is replaced with an upgrade prompt.
export function LessonsPreviewGate({ hiddenCount }: { hiddenCount: number }) {
  const { isPreview, loading } = usePlanAccess();
  if (loading || !isPreview || hiddenCount <= 0) return null;
  return (
    <PreviewLimit
      hiddenCount={hiddenCount}
      what="lesson"
    />
  );
}

// Revision-notes library (uploaded study materials) — presented as an
// editorial reading surface: numbered entries, display-serif titles and a
// measure-limited reader, rather than a wall of identical cards.
import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { SEOHead } from "@/components/SEOHead";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";
import { openProtectedFile } from "@/lib/contentFiles";
import { LEVELS, LEVEL_LABELS } from "@/lib/subjects";
import { toast } from "sonner";
import { loadFailureMessage } from "@/lib/net";
import {
  FileText, Search, Download, CheckCircle2, Circle, AlertCircle, RotateCcw, ExternalLink, Eye, Loader2,
} from "lucide-react";
import { ContentEditor } from "@/components/admin/ContentEditor";

export interface NoteRow {
  id: string;
  title: string;
  file_url: string | null;
  content: string | null;
  material_type: string;
  topic_id: string | null;
  topic_name: string;
  subject_name: string;
  subject_id: string;
  subject_level_id: string;
  level: string;
}

/** Material types this library surfaces, in the order the filter offers them. */
export const LIBRARY_TYPES = ["notes", "summary"] as const;

// A ceiling so the library cannot silently grow into an unbounded query.
const LIBRARY_LIMIT = 500;

export async function fetchNotes(): Promise<NoteRow[]> {
  const { data, error } = await supabase
    .from("study_materials")
    .select("id, title, file_url, content, material_type, topic_id, topics(id, name, subject_levels(id, level, subjects(id, name)))")
    // Previously pinned to "notes", which hid every "summary" material from the
    // library — half the content was only reachable from a topic page.
    .in("material_type", LIBRARY_TYPES as unknown as string[])
    .order("title")
    .limit(LIBRARY_LIMIT);
  if (error) throw error;
  return (data ?? []).map((m) => ({
    id: m.id,
    title: m.title,
    file_url: m.file_url,
    content: m.content,
    material_type: m.material_type ?? "notes",
    topic_id: m.topic_id,
    topic_name: m.topics?.name ?? "Unassigned",
    subject_name: m.topics?.subject_levels?.subjects?.name ?? "General",
    subject_id: m.topics?.subject_levels?.subjects?.id ?? "none",
    subject_level_id: m.topics?.subject_levels?.id ?? "",
    level: m.topics?.subject_levels?.level ?? "",
  }));
}

export function useNoteProgress() {
  const { user } = useAuth();
  const [done, setDone] = useState<Record<string, boolean>>({});

  useEffect(() => {
    if (!user) return;
    (async () => {
      try {
        const { data, error } = await supabase
          .from("material_progress")
          .select("material_id, completed")
          .eq("user_id", user.id);
        // PostgREST resolves with `{ error }` rather than rejecting, so the
        // old `catch` below never fired for a failed query: the tick marks just
        // silently vanished. Say so instead.
        if (error) {
          toast.error(loadFailureMessage("your study progress", error));
          return;
        }
        const map: Record<string, boolean> = {};
        (data ?? []).forEach((r) => { map[r.material_id] = r.completed; });
        setDone(map);
      } catch (e) {
        // A failed progress read must not surface as an unhandled rejection;
        // the list still works, it just shows nothing as studied yet.
        console.error("Could not load note progress:", e);
      }
    })();
  }, [user]);

  const toggle = async (materialId: string) => {
    if (!user) return;
    const next = !done[materialId];
    setDone((d) => ({ ...d, [materialId]: next }));
    const { error } = await supabase.from("material_progress").upsert(
      {
        user_id: user.id,
        material_id: materialId,
        completed: next,
        completed_at: next ? new Date().toISOString() : null,
      },
      { onConflict: "user_id,material_id" },
    );
    if (error) {
      setDone((d) => ({ ...d, [materialId]: !next }));
      toast.error("Could not save progress");
    }
  };

  return { done, toggle };
}

export async function downloadNote(note: NoteRow) {
  if (!note.file_url) return;
  // Protected download: same watermarked bytes via serve-material.
  await openProtectedFile("study-materials", note.file_url, note.title);
}

export default function Notes() {
  const { role } = useAuth();
  const [notes, setNotes] = useState<NoteRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [subject, setSubject] = useState("all");
  const [level, setLevel] = useState("all");
  const [type, setType] = useState("all");
  const { done, toggle } = useNoteProgress();
  // The library is scoped to the student's picked subject-levels, the same way
  // the dashboard tiles are. Without this a Mathematics + Physics student read
  // Computer Science A2 notes under a "Showing only your subjects" banner.
  const { user } = useAuth();
  const {
    pickedIds,
    loaded: prefsLoaded,
    isAdmin: isAdminRole,
    needsSubjectPick,
    filtering,
  } = useMySubjects();

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      setNotes(await fetchNotes());
    } catch (e) {
      setError(e.message ?? "Failed to load notes");
    }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const subjects = useMemo(() => {
    const seen = new Map<string, string>();
    notes.forEach((n) => seen.set(n.subject_id, n.subject_name));
    return [...seen.entries()];
  }, [notes]);

  const visible = useMemo(() => {
    const term = q.trim().toLowerCase();
    return notes.filter((n) => {
      if (filtering && !pickedIds.has(n.subject_level_id)) return false;
      if (subject !== "all" && n.subject_id !== subject) return false;
      if (level !== "all" && n.level !== level) return false;
      if (type !== "all" && n.material_type !== type) return false;
      if (!term) return true;
      // Search the body too, not just the title: students look for a term they
      // remember reading, not the note's heading.
      const body = (n.content ?? "").replace(/<[^>]*>/g, " ").toLowerCase();
      return (
        n.title.toLowerCase().includes(term) ||
        n.topic_name.toLowerCase().includes(term) ||
        body.includes(term)
      );
    });
  }, [notes, q, subject, level, type, filtering, pickedIds]);

  const completedCount = visible.filter((n) => done[n.id]).length;
  const progressPct = visible.length ? Math.round((completedCount / visible.length) * 100) : 0;

  // Subject & level gate: students must pick at least one subject (and its
  // level) before any notes are shown. While preferences are still loading we
  // render nothing — never the content itself. Sits after every hook so the
  // early returns never change hook order.
  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="cm-study mx-auto max-w-4xl space-y-8">
        <SEOHead path="/notes" />
        <SubjectGate />
      </div>
    );
  }

  return (
    <div className="cm-study mx-auto max-w-4xl space-y-8">
      <SEOHead path="/notes" />

      {/* ---------- masthead ---------- */}
      <header>
        <p className="eyebrow mb-3 flex items-center gap-2">
          <FileText className="h-3.5 w-3.5 text-primary" /> The library
        </p>
        <h1 className="display-xl text-3xl lg:text-4xl">Revision notes</h1>
        <p className="mt-3 text-sm text-muted-foreground">
          {loading
            ? "Loading notes…"
            : visible.length === 0
              ? "No notes in this view"
              : // Study ticks are per-account: promising a progress figure to a
                // visitor who has no account to record it against was a number
                // that could never move.
                !user
                ? "Sign in to track which notes you've studied"
                : `${completedCount} of ${visible.length} marked as studied — ${progressPct}% of this set`}
        </p>
        <hr className="rule-gold mt-6" />
      </header>

      {/* ---------- filters ---------- */}
      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search notes or topic keywords…"
            className="pl-9"
            aria-label="Search notes"
          />
        </div>
        <Select value={subject} onValueChange={setSubject}>
          <SelectTrigger className="w-full sm:w-[180px]"><SelectValue placeholder="Subject" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All subjects</SelectItem>
            {subjects.map(([id, name]) => <SelectItem key={id} value={id}>{name}</SelectItem>)}
          </SelectContent>
        </Select>
        <Select value={level} onValueChange={setLevel}>
          <SelectTrigger className="w-full sm:w-[160px]"><SelectValue placeholder="Level" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All levels</SelectItem>
            {LEVELS.map((l) => <SelectItem key={l} value={l}>{LEVEL_LABELS[l]}</SelectItem>)}
          </SelectContent>
        </Select>
        <Select value={type} onValueChange={setType}>
          <SelectTrigger className="w-full sm:w-[150px]" aria-label="Material type"><SelectValue placeholder="Type" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All types</SelectItem>
            <SelectItem value="notes">Notes</SelectItem>
            <SelectItem value="summary">Summaries</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {error && (
        <Card className="border-destructive/40">
          <CardContent className="flex items-center justify-between gap-3 p-4">
            <p className="text-sm text-destructive flex items-center gap-2"><AlertCircle className="h-4 w-4" /> {error}</p>
            <Button size="sm" variant="outline" onClick={load} className="gap-1"><RotateCcw className="h-3.5 w-3.5" /> Try again</Button>
          </CardContent>
        </Card>
      )}

      {/* ---------- entries ---------- */}
      {loading ? (
        <div className="space-y-3">{[0, 1, 2].map((i) => <Skeleton key={i} className="h-24 rounded-xl" />)}</div>
      ) : visible.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center py-14">
            <FileText className="h-9 w-9 text-muted-foreground/30 mb-3" />
            <p className="text-sm text-muted-foreground">No notes match your search.</p>
          </CardContent>
        </Card>
      ) : (
        <ol className="space-y-3">
          {visible.map((n, i) => {
            const studied = !!done[n.id];
            return (
              <li key={n.id}>
                <Card
                  className={`group relative overflow-hidden transition-colors ${studied ? "border-primary/25" : ""}`}
                >
                  {/* gold rail marks the entry as studied */}
                  <span
                    aria-hidden
                    className={`absolute left-0 top-0 h-full w-[2px] transition-opacity ${studied ? "bg-primary opacity-100" : "opacity-0"}`}
                  />
                  <CardContent className="flex flex-wrap items-center gap-4 p-5">
                    <span className="num hidden w-7 shrink-0 font-mono text-xs text-muted-foreground/50 sm:block">
                      {String(i + 1).padStart(2, "0")}
                    </span>

                    {/* Per-account control: hidden when signed out instead of
                        rendering a toggle whose only outcome is "nothing". */}
                    {user && (
                      <button
                        onClick={() => toggle(n.id)}
                        aria-label={studied ? "Mark as not studied" : "Mark as studied"}
                        className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md transition-transform hover:bg-muted"
                      >
                        {studied
                          ? <CheckCircle2 className="h-5 w-5 text-primary" />
                          : <Circle className="h-5 w-5 text-muted-foreground/40" />}
                      </button>
                    )}

                    <div className="min-w-0 flex-1">
                      <p className="font-display text-[15px] font-semibold leading-snug tracking-tight">
                        {n.title}
                      </p>
                      <div className="mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1">
                        <span className="eyebrow">{n.subject_name}</span>
                        {n.level && (
                          <>
                            <span className="text-muted-foreground/30">·</span>
                            <span className="eyebrow">{LEVEL_LABELS[n.level as "OL"] ?? n.level}</span>
                          </>
                        )}
                        <span className="text-muted-foreground/30">·</span>
                        <span className="min-w-0 text-xs text-muted-foreground truncate">{n.topic_name}</span>
                        {n.material_type === "summary" && (
                          <Badge variant="outline" className="text-[10px] capitalize">Summary</Badge>
                        )}
                      </div>
                    </div>

                    <div className="flex gap-1.5">
                      {role === "admin" && (
                        <ContentEditor
                          entityType="material"
                          entityId={n.id}
                          initialTitle={n.title}
                          initialContent={n.content ?? null}
                          onSaved={load}
                        />
                      )}
                      {n.content && (
                        <Button size="sm" variant="secondary" className="gap-1" asChild>
                          <Link to={`/notes/${n.id}`}><Eye className="h-3.5 w-3.5" /> Read</Link>
                        </Button>
                      )}
                      {/* File-backed controls only appear when there is a file. Every
                          material in the library is HTML-only today, so these used to
                          render as 60 dead, unlabelled buttons per page. */}
                      {n.file_url && (
                        <>
                          <Button size="sm" variant="ghost" className="gap-1"
                            onClick={async () => {
                              try {
                                await openProtectedFile("study-materials", n.file_url!);
                              } catch (e) {
                                toast.error(e?.message ?? "Could not open this file");
                              }
                            }}>
                            <ExternalLink className="h-3.5 w-3.5" /> Open
                          </Button>
                          <Button size="sm" variant="ghost"
                            aria-label={`Download ${n.title}`}
                            title={`Download ${n.title}`}
                            onClick={() => downloadNote(n).catch((e) => toast.error(e?.message ?? "Could not download this file"))}>
                            <Download className="h-3.5 w-3.5" />
                          </Button>
                        </>
                      )}
                    </div>
                  </CardContent>
                </Card>
              </li>
            );
          })}
        </ol>
      )}

      <p className="text-xs text-muted-foreground">
        Looking for a specific lesson? Open it from <Link to="/lessons" className="text-primary underline">Lessons</Link> to view its notes.
      </p>
    </div>
  );
}

