const LEVEL_FILTERS = [
  { id: "all", label: "All levels" },
  { id: "OL", label: "IGCSE" },
  { id: "AS", label: "AS Level" },
  { id: "A2", label: "A2 Level" },
];

const levelLabel = (l: string | null) => LEVEL_FILTERS.find((f) => f.id === l)?.label ?? l;

// `paper_number` rows already read "Paper 1 (12)" — prefixing another "Paper"
// rendered "Paper Paper 1 (12)".
const paperLabel = (n: string | null) => (!n ? "—" : /^paper\b/i.test(n) ? n : `Paper ${n}`);

export default function PastPapers() {
  const { toast } = useToast();
  const { user } = useAuth();
  const qc = useQueryClient();
  const { pickedIds, loaded: prefsLoaded, isAdmin, needsSubjectPick } = useMySubjects();
  const { data: subjectLevels } = useQuery({
    queryKey: ["archive_subject_levels"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("subject_levels")
        .select("id, level, subjects(slug)")
        .eq("is_active", true);
      if (error) throw error;
      return data ?? [];
    },
  });
  const [search, setSearch] = useState("");
  const [yearFilter, setYearFilter] = useState("all");
  const [levelFilter, setLevelFilter] = useState("all");
  const [boardFilter, setBoardFilter] = useState("all");
  const [paperFilter, setPaperFilter] = useState("all");
  const [sessionFilter, setSessionFilter] = useState("all");
  const [practicePaper, setPracticePaper] = useState<PracticePaper | null>(null);
  // The paper whose row the student tapped “Submit for marking” on — the
  // marking is scoped to that paper's own mark scheme.
  const [markPaper, setMarkPaper] = useState<any | null>(null);

  const { data: topics, error: topicsError } = useQuery({
    queryKey: ["topics"],
    queryFn: async () => {
      // Throw so React Query surfaces the failure; ignoring `error` here meant
      // a broken request looked exactly like "no topics exist".
      const { data, error } = await supabase.from("topics").select("*").order("sort_order");
      if (error) throw error;
      return data ?? [];
    },
  });

  const { data: papers, isLoading, error: papersError, refetch: refetchPapers } = useQuery({
    queryKey: ["past_papers"],
    queryFn: async () => {
      const { data, error } = await supabase.from("past_papers").select("*, topics(name, subject_levels(level, subjects(name, slug)))").order("year", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
  });

  // Saved sittings for this student, so each card can surface a best score.
  const { data: attempts } = useQuery({
    queryKey: ["past_paper_attempts", user?.id],
    enabled: !!user,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("past_paper_attempts")
        .select("id, paper_id, percentage, created_at")
        .eq("user_id", user!.id)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
  });

  // Best score + number of sittings per paper (rows arrive newest-first, so the
  // first percentage seen for a paper is its most recent).
  const attemptsByPaper = useMemo(() => {
    const m = new Map<string, { best: number; count: number }>();
    for (const a of attempts ?? []) {
      if (!a.paper_id || a.percentage == null) continue;
      const cur = m.get(a.paper_id);
      if (!cur) m.set(a.paper_id, { best: a.percentage, count: 1 });
      else m.set(a.paper_id, { best: Math.max(cur.best, a.percentage), count: cur.count + 1 });
    }
    return m;
  }, [attempts]);

  const { loading: planLoading, isPreview, hasPaid } = usePlanAccess();

  const handleOpenFile = async (url: string) => {
    try {
      await openProtectedFile("past-papers", url);
    } catch (e) {
      toast({ title: "Unable to open file", description: e?.message ?? "Please try again", variant: "destructive" });
    }
  };

  // Save-to-disk variant. Same watermarked bytes as opening, but the browser is
  // told to download (and what to call the file) instead of previewing it.
  const handleDownloadFile = async (url: string, name: string) => {
    try {
      await openProtectedFile("past-papers", url, name);
    } catch (e) {
      toast({ title: "Unable to download file", description: e?.message ?? "Please try again", variant: "destructive" });
    }
  };

  // External papers route through serve-external-paper, which enforces the
  // plan and audits the click. A gated rejection becomes an upgrade prompt.
  const handleOpenExternal = async (url: string, label?: string) => {
    try {
      await openExternalPaper(url, label);
    } catch (e) {
      if (e instanceof ExternalPaperGated) {
        toast({ title: "Full plan required", description: e.message });
        return;
      }
      toast({ title: "Unable to open link", description: e?.message ?? "Please try again", variant: "destructive" });
    }
  };

  // Topic-linked rows use topic ownership; metadata-only rows use their
  // persisted subject_slug + level. The latter matters for archive papers that
  // are correctly classified but intentionally not assigned to a single topic.
  const topicToSl = useMemo(() => {
    const m = new Map<string, string>();
    (topics ?? []).forEach((t) => { if (t.subject_level_id) m.set(t.id, t.subject_level_id); });
    return m;
  }, [topics]);

  const subjectLevelByCode = useMemo(() => {
    const m = new Map<string, string>();
    (subjectLevels ?? []).forEach((row) => {
      const slug = row.subjects?.slug;
      if (slug && row.level) m.set(`${slug.toLowerCase()}/${String(row.level).toUpperCase()}`, row.id);
    });
    return m;
  }, [subjectLevels]);

  const scopedPapers = useMemo(
    () => filterPapersForSubjects(papers ?? [], {
      isAdmin,
      loaded: prefsLoaded,
      signedIn: !!user,
      pickedSubjectLevels: pickedIds,
      topicSubjectLevels: topicToSl,
      subjectLevelByCode,
    }),
    [papers, isAdmin, prefsLoaded, user, pickedIds, topicToSl, subjectLevelByCode],
  );

  // Filter options come from the whole subject-scoped archive, not the free
  // slice, so a student can see (and reach) every board / paper / session on
  // offer. Sessions always include the full board calendar, `Specimen` included.
  const boardOptions = useMemo(() => {
    const set = new Set<string>();
    (scopedPapers ?? []).forEach((p) => set.add(archiveBoard(p)));
    return [...set].sort((a, b) => a.localeCompare(b));
  }, [scopedPapers]);

  const paperOptions = useMemo(() => {
    const set = new Set<string>();
    (scopedPapers ?? []).forEach((p) => set.add(archivePaperGroup(p)));
    return [...set].sort((a, b) => paperSortKey(a).localeCompare(paperSortKey(b)));
  }, [scopedPapers]);

  const sessionOptions = useMemo(() => {
    const set = new Set<string>(SESSION_ORDER);
    (scopedPapers ?? []).forEach((p) => { if (p.session) set.add(p.session); });
    return [...set].sort(sortSessions);
  }, [scopedPapers]);

  // Every filter — search included — runs BEFORE the free-preview slice. It used
  // to be applied to `visiblePapers` (the slice), so a free student searching
  // for an older paper or a specimen only ever searched the first
  // `FREE_PREVIEW_LIMIT` rows and concluded the paper did not exist.
  const matchedPapers = useMemo(
    () => filterArchivePapers(scopedPapers ?? [], {
      search,
      level: levelFilter,
      board: boardFilter,
      paper: paperFilter,
      session: sessionFilter,
    }),
    [scopedPapers, search, levelFilter, boardFilter, paperFilter, sessionFilter],
  );

  // Year chips reflect the papers that survive the other filters, so switching
  // board or session never offers a year that would come up empty.
  const years = [...new Set(matchedPapers.map((p) => p.year))].sort((a, b) => b - a);
  const yearScoped = yearFilter === "all" ? matchedPapers : matchedPapers.filter((p) => p.year === Number(yearFilter));
  const { slice: visiblePapers } = usePreviewSliceWithLimit(yearScoped, FREE_PREVIEW_LIMIT);
  const filteredPapers = visiblePapers ?? [];

  const groupedPapers = years
    .map((y) => ({ year: y, papers: filteredPapers.filter((p) => p.year === y) }))
    .filter((g) => g.papers.length > 0);

  if (!isAdmin && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <div className="h-8 w-8 rounded-full border-primary/30 border animate-spin" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/past-papers" />
        <SubjectGate />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <SEOHead path="/past-papers" />
      <div>
        <h1 className="text-3xl font-bold flex items-center gap-2">
          <FileText className="h-7 w-7 text-primary" /> Past Papers
        </h1>
        <p className="text-muted-foreground text-sm">
          Download past exam papers and mark schemes. Solve one on paper and mark it with the{" "}
          <Link to="/ai-marker" className="font-semibold text-primary underline decoration-primary/30 underline-offset-4">AI Marker</Link>.
        </p>
      </div>

      {/* A failed load says so, with a retry, instead of showing a year list. */}
      {(papersError || topicsError) && (
        <QueryError
          message={loadFailureMessage("past papers", papersError ?? topicsError)}
          onRetry={() => refetchPapers()}
        />
      )}

      {/* AI marking of an uploaded solved paper. The component gates itself:
          free accounts get an upgrade card, and the worker enforces the plan
          server-side regardless. */}
      <div className="max-w-4xl mx-auto">
        <SolvedPaperMarker title="Mark a solved past paper" />
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col gap-4">
            <div className="relative">
              {/* The icon used to sit as a block above the field; every other
                  search box in the app nests it inside on the left. */}
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                className="pl-9"
                aria-label="Search past papers"
                placeholder="Search papers... (e.g. 2024, Paper 1, Chem, Specimen)"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <div className="flex flex-wrap gap-2">
              <Select value={levelFilter} onValueChange={setLevelFilter}>
                <SelectTrigger className="w-[170px]" aria-label="Filter by level">
                  <SelectValue placeholder="Level" />
                </SelectTrigger>
                <SelectContent>
                  {LEVEL_FILTERS.map((f) => (
                    <SelectItem key={f.id} value={f.id}>{f.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={boardFilter} onValueChange={setBoardFilter}>
                <SelectTrigger className="w-[200px]" aria-label="Filter by exam board">
                  <SelectValue placeholder="Board" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All boards</SelectItem>
                  {boardOptions.map((b) => (
                    <SelectItem key={b} value={b}>{b}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={paperFilter} onValueChange={setPaperFilter}>
                <SelectTrigger className="w-[200px]" aria-label="Filter by paper">
                  <SelectValue placeholder="Paper" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All papers</SelectItem>
                  {paperOptions.map((p) => (
                    <SelectItem key={p} value={p}>{p}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={sessionFilter} onValueChange={setSessionFilter}>
                <SelectTrigger className="w-[160px]" aria-label="Filter by session">
                  <SelectValue placeholder="Session" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All sessions</SelectItem>
                  {sessionOptions.map((s) => (
                    <SelectItem key={s} value={s}>{s}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="flex flex-wrap gap-2">
              {/* Year chips come from the papers actually in scope. They used to
                  be hard-coded to 2024/2023, which offered two years that did
                  not match the newest papers (2025) and hid the real ones. */}
              <Button variant="outline" onClick={() => setYearFilter("all")} className={yearFilter === "all" ? "bg-primary text-primary-foreground" : ""}>
                All years
              </Button>
              {years.map((y) => (
                <Button
                  key={y}
                  variant="outline"
                  onClick={() => setYearFilter(String(y))}
                  className={yearFilter === String(y) ? "bg-primary text-primary-foreground" : ""}
                >
                  {y}
                </Button>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Paper grid */}
      {isLoading ? (
        <Card>
          <CardContent className="py-12 text-center">
            <Loader2 className="h-8 w-8 animate-spin mx-auto text-primary" />
            <p className="text-sm text-muted-foreground mt-2">Loading past papers…</p>
          </CardContent>
        </Card>
      ) : filteredPapers.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <p className="text-sm text-muted-foreground">No past papers match your search.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {groupedPapers.flatMap((g) =>
            g.papers.map((p) => (
              <Card key={p.id} className="hover:shadow-md transition-shadow group">
                <CardHeader className="pb-2">
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <CardTitle className="text-base group-hover:text-primary transition-colors">
                      {p.title}
                    </CardTitle>
                    {/* Nothing in the archive has a PDF yet, so the primary action
                        used to be a disabled "Paper" button next to the words
                        "Awaiting upload" — a dead end. Point students at the exam
                        board's own page instead, and only show the download
                        buttons when there is actually a file to download. */}
                    <div className="flex shrink-0 flex-wrap justify-end gap-1">
                      {p.paper_url ? (
                        <Button variant="ghost" size="sm" onClick={() => handleOpenFile(p.paper_url ?? "")}>
                          View paper
                        </Button>
                      ) : null}
                      {p.mark_scheme_url && (
                        <Button variant="ghost" size="sm" onClick={() => handleOpenFile(p.mark_scheme_url ?? "")}>
                          View mark scheme
                        </Button>
                      )}
                      {/* A row can carry a paper but no mark scheme (or vice
                          versa), so the board-site fallback must fire whenever
                          *either* file is missing — keying it on `paper_url`
                          alone left those rows with no way out. */}
                      {(!p.paper_url || !p.mark_scheme_url) && p.source_url && (
                        <Button
                          variant="outline"
                          size="sm"
                          className="gap-1"
                          onClick={() => handleOpenExternal(p.source_url!, boardLabel(p.source_url) ?? undefined)}
                        >
                          {boardLabel(p.source_url) ?? "Board site"}
                          <ExternalLink className="h-3 w-3" />
                        </Button>
                      )}
                    </div>
                  </div>
                  {/* CardDescription renders a <p>, and the level Badge renders a
                      <div> — invalid nesting, which React warns about. */}
                  <div className="text-sm text-muted-foreground space-y-1">
                    <div className="flex items-center gap-1.5">
                      {p.topics?.subject_levels?.level && (
                        <Badge variant="outline" className="text-[10px] uppercase tracking-[0.08em]">
                          {levelLabel(p.topics?.subject_levels?.level)}
                        </Badge>
                      )}
                      <span>
                        {p.session ? `${p.session} · Year ${p.year}` : `Year ${p.year}`}
                        {/* `topic_name` is not a column on past_papers — the topic
                            arrives as the nested `topics` embed. */}
                        {p.topics?.name && <span className="text-xs text-muted-foreground"> · {p.topics.name}</span>}
                      </span>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <p className="text-xs text-muted-foreground">
                    {paperLabel(p.paper_number)} ·{" "}
                    {p.paper_url
                      ? "Downloadable"
                      : p.source_url
                        ? "Not in our library yet — open it on the board's site"
                        : "Awaiting upload"}
                  </p>
                  <div className="mt-3 flex flex-wrap items-center justify-between gap-2">
                    <div className="flex flex-wrap items-center gap-2">
                      <Button
                        size="sm"
                        className="gap-1.5"
                        onClick={() => setPracticePaper({
                          id: p.id,
                          title: p.title,
                          session: p.session ?? null,
                          year: p.year,
                          paper_number: p.paper_number ?? null,
                        })}
                      >
                        <Clock className="h-3.5 w-3.5" /> Practise
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        className="gap-1.5"
                        title="Submit your solved script — marked against this paper's mark scheme"
                        onClick={() => setMarkPaper(p)}
                      >
                        <Wand2 className="h-3.5 w-3.5" /> Submit for marking
                      </Button>
                      {p.paper_url && (
                        <Button
                          size="sm"
                          variant="outline"
                          className="gap-1.5"
                          aria-label={`Download ${p.title} question paper`}
                          title="Download question paper"
                          onClick={() => handleDownloadFile(p.paper_url!, paperFileName(p.title, "paper"))}
                        >
                          <Download className="h-3.5 w-3.5" /> Download paper
                        </Button>
                      )}
                      {p.mark_scheme_url && (
                        <Button
                          size="sm"
                          variant="outline"
                          className="gap-1.5"
                          aria-label={`Download ${p.title} mark scheme`}
                          title="Download mark scheme"
                          onClick={() => handleDownloadFile(p.mark_scheme_url!, paperFileName(p.title, "mark-scheme"))}
                        >
                          <Download className="h-3.5 w-3.5" /> Download mark scheme
                        </Button>
                      )}
                    </div>
                    {(() => {
                      const score = attemptsByPaper.get(p.id);
                      if (!score) return null;
                      return (
                        <Badge variant="outline" className="gap-1 text-[10px] text-primary">
                          <Trophy className="h-3 w-3" /> Best {score.best}%
                          {score.count > 1 ? ` · ${score.count} sittings` : ""}
                        </Badge>
                      );
                    })()}
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      )}

      {/* Timed, paper-scoped practice. Saving an attempt awards XP server-side
          and refreshes the per-card best score. */}
      <PaperPractice
        paper={practicePaper}
        open={practicePaper !== null}
        onOpenChange={(o) => { if (!o) setPracticePaper(null); }}
        onSaved={() => qc.invalidateQueries({ queryKey: ["past_paper_attempts"] })}
      />

      {/* Submit-for-marking scoped to the tapped paper's own mark scheme. */}
      <MarkPaperDialog
        paper={markPaper}
        open={markPaper !== null}
        onOpenChange={(o) => { if (!o) setMarkPaper(null); }}
      />

    </div>
  );
}

// Practice hub — one page, three tabs:
//   • Topic questions: the full question bank by topic/difficulty, with
//     saved-progress mastery panel (merged from the old QuestionBank page)
//   • Review: every question you got wrong or bookmarked
//   • Drills: timed 10-question sessions on your weakest topics
import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ManuscriptQuestion } from "@/components/StudyManuscript";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { SEOHead } from "@/components/SEOHead";
import { BookmarkButton } from "@/components/BookmarkButton";
import { LEVEL_LABELS, type SubjectLevelCode } from "@/lib/subjects";
import { useMySubjects } from "@/hooks/useMySubjects";
import { useToast } from "@/hooks/useToast";
import { loadFailureMessage } from "@/lib/net";
import { SubjectPicker } from "@/components/SubjectPicker";
import { SubjectGate } from "@/components/SubjectGate";
import { FeedbackNudge } from "@/components/FeedbackNudge";
import { QuestionList, SavedProgressPanel, type Attempt, type TopicSummary } from "@/components/practice/QuestionBankParts";
import { cn } from "@/lib/utils";
import {
  Sparkles, Brain, CheckCircle2, XCircle, RotateCcw, Layers, Search,
  Bookmark, AlertCircle, Target, Database,
} from "lucide-react";

interface DrillQuestion {
  id: string;
  question_text: string;
  options: string[];
  topic_name: string;
  correct_option?: number;
  explanation?: string | null;
}

// Shape of the check_practice_answer RPC result (returned as Json by the generated types).
interface PracticeVerdict {
  correct_option: number;
  explanation: string | null;
  correct: boolean;
  corrected_mistake?: boolean | null;
}

interface ReviewQuestion {
  id: string;
  quiz_id: string;
  quiz_title: string;
  question_text: string;
  options: string[];
  difficulty: string;
  topic_id: string | null;
  topic_name: string | null;
  bookmarked: boolean;
  last_correct: boolean | null;
  attempts_count: number;
}

interface BankQuestion {
  id: string;
  quiz_id: string;
  quiz_title: string;
  question_text: string;
  options: string[];
  difficulty: string;
  exam_type: string;
  is_ai_generated: boolean;
  topic_id: string | null;
  topic_name: string | null;
  bookmarked: boolean;
}

interface LevelOption { id: string; label: string }

export default function Practice() {
  const { user } = useAuth();
  const { toast } = useToast();
  const { pickedIds, loaded: prefsLoaded, isAdmin, needsSubjectPick, filtering } = useMySubjects();
  const [params, setParams] = useSearchParams();
  const requestedMode = params.get("mode") ?? "incorrect";
  const mode = requestedMode === "bookmarked" ? "bookmarked" : requestedMode === "all" ? "all" : "incorrect";
  const tab = params.get("tab") ?? (mode === "bookmarked" ? "review" : "topics");
  const levelId = params.get("level") ?? "all";
  // Default the review-level filter to the first subject-level the student
  // picked, so a student who chooses "Ol Math" immediately sees only Ol Math
  // review questions instead of every subject's wrong/bookmarked questions.
  const defaultedLevelId = useMemo(() => {
    if (isAdmin || !prefsLoaded) return levelId;
    if (levelId !== "all" && levelId !== "") return levelId;
    const picked = [...pickedIds];
    if (picked.length === 0) return "all";
    return picked[0];
  }, [levelId, isAdmin, prefsLoaded, pickedIds]);
  const topicFilter = params.get("topic") ?? "";

  const setParam = (key: string, value: string) => {
    const next = new URLSearchParams(params);
    if (value === "all" || value === "") next.delete(key); else next.set(key, value);
    setParams(next, { replace: true });
  };

  // ---------- Weak-topic drills ----------
  const [weakTopics, setWeakTopics] = useState<{ id: string; name: string; avg: number }[]>([]);
  const [drill, setDrill] = useState<DrillQuestion[]>([]);
  const [drillIdx, setDrillIdx] = useState(0);
  const [drillSelected, setDrillSelected] = useState<number | null>(null);
  const [drillCorrect, setDrillCorrect] = useState(0);
  const [drillCorrected, setDrillCorrected] = useState(false);
  const [drillDone, setDrillDone] = useState(false);
  const [drillTopic, setDrillTopic] = useState("");
  const [loadingWeak, setLoadingWeak] = useState(true);
  // Which topic's drill is being fetched, so the button can show progress
  // instead of looking dead between the click and the request landing.
  const [drillLoadingId, setDrillLoadingId] = useState<string | null>(null);

  // ---------- Review list (incorrect/bookmarked) ----------
  const [levelOptions, setLevelOptions] = useState<LevelOption[]>([]);
  const [questions, setQuestions] = useState<ReviewQuestion[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [difficulty, setDifficulty] = useState("all");
  const [active, setActive] = useState<ReviewQuestion | null>(null);
  const [selected, setSelected] = useState<number | null>(null);
  // `corrected` marks the case that matters most: this question was answered
  // wrongly before, and now it isn't. The server pays extra XP for it, and it is
  // the one piece of feedback worth calling out by name.
  const [reveal, setReveal] = useState<{ correct_option: number; explanation: string | null; correct: boolean; corrected?: boolean } | null>(null);
  const [topicSL, setTopicSL] = useState<Map<string, string>>(new Map()); // topic_id -> subject_level_id
  const pickedSlByTopic = useMemo(
    () => new Map([...topicSL.entries()].filter(([, sl]) => pickedIds.has(sl))),
    [topicSL, pickedIds],
  );

  // ---------- Topic questions (merged from QuestionBank) ----------
  const [bankTopics, setBankTopics] = useState<{ id: string; name: string }[]>([]);
  const [bankTopicId, setBankTopicId] = useState("");
  const [bankQuestions, setBankQuestions] = useState<BankQuestion[]>([]);
  const [bankSearch, setBankSearch] = useState("");
  const [bankDifficulty, setBankDifficulty] = useState("all");
  const [bankExamType, setBankExamType] = useState("all");
  const [bankAttempts, setBankAttempts] = useState<Record<string, Attempt>>({});
  const [bankSummary, setBankSummary] = useState<TopicSummary[]>([]);
  const [summaryLoading, setSummaryLoading] = useState(false);
  const [bankActive, setBankActive] = useState<BankQuestion | null>(null);
  const [bankSelected, setBankSelected] = useState<number | null>(null);
  const [bankReveal, setBankReveal] = useState<{ correct_option: number; explanation: string | null; correct: boolean; corrected?: boolean } | null>(null);

  useEffect(() => {
    if (!user) return;
    (async () => {
      const [topicsRes, quizzesRes, attemptsRes] = await Promise.all([
        supabase.from("topics").select("id, name, subject_level_id").order("sort_order"),
        supabase.from("quizzes").select("id, topic_id").eq("is_published", true),
        supabase.from("quiz_attempts").select("quiz_id, score, total_questions").eq("user_id", user.id).not("completed_at", "is", null),
      ]);
      const topics = topicsRes.data ?? [];
      setTopicSL(new Map(topics.map((t) => [t.id, t.subject_level_id])));
      setBankTopics(topics.map((t) => ({ id: t.id, name: t.name })));
      const quizTopic = new Map((quizzesRes.data ?? []).map((q) => [q.id, q.topic_id]));
      const tally: Record<string, { sum: number; n: number }> = {};
      (attemptsRes.data ?? []).forEach((a) => {
        const tid = quizTopic.get(a.quiz_id);
        if (!tid) return;
        const pct = ((a.score ?? 0) / (a.total_questions || 1)) * 100;
        tally[tid] = tally[tid] || { sum: 0, n: 0 };
        tally[tid].sum += pct;
        tally[tid].n += 1;
      });
      const ranked = topics
        .map((t) => ({ id: t.id, name: t.name, avg: tally[t.id] ? Math.round(tally[t.id].sum / tally[t.id].n) : -1 }))
        .filter((t) => t.avg >= 0)
        .sort((a, b) => a.avg - b.avg);
      setWeakTopics(ranked.length > 0 ? ranked : topics.map((t) => ({ id: t.id, name: t.name, avg: 0 })));
      setLoadingWeak(false);
    })();
  }, [user]);

  const loadReviewQuestions = async () => {
    setLoading(true);
    setError(null);
    const { data, error } = await supabase.rpc("get_review_questions", {
      _subject_level_id: levelId === "all" ? null : levelId,
      _mode: mode,
      _limit: 200,
    });
    if (error) setError(error.message);
    setQuestions(((data ?? []) as unknown as ReviewQuestion[]));
    setLoading(false);
  };

  useEffect(() => {
    (async () => {
      const { data, error: levelsError } = await supabase
        .from("subject_levels")
        .select("id, level, subjects(name)")
        .eq("is_active", true)
        .order("sort_order");
      if (levelsError) { setError(loadFailureMessage("your subjects", levelsError)); return; }
      setLevelOptions(
        (data ?? []).map((l) => ({
          id: l.id,
          label: `${l.subjects?.name ?? "Subject"} — ${LEVEL_LABELS[l.level as SubjectLevelCode]}`,
        })),
      );
    })();
  }, []);

  useEffect(() => { loadReviewQuestions(); }, [mode, defaultedLevelId]);

  const loadBankAttempts = async () => {
    if (!user) return;
    const { data, error: attemptsError } = await supabase
      .from("practice_attempts")
      .select("question_id, last_correct, attempts_count, last_attempt_at")
      .eq("user_id", user.id);
    if (attemptsError) {
      // Decorative (the "tried N times" marks), so it stays a toast rather
      // than blanking the whole question list.
      toast({
        title: "Couldn't load your practice history",
        description: loadFailureMessage("your practice history", attemptsError),
        variant: "destructive",
      });
      return;
    }
    const map: Record<string, Attempt> = {};
    (data ?? []).forEach((a) => { map[a.question_id] = a; });
    setBankAttempts(map);
  };

  const loadBankSummary = async () => {
    setSummaryLoading(true);
    try {
      const { data, error } = await supabase.rpc("get_practice_summary");
      if (error) throw error;
      setBankSummary(((data ?? []) as TopicSummary[]).filter((s) => s.total_questions > 0));
    } catch {
      setBankSummary([]);
    } finally {
      setSummaryLoading(false);
    }
  };

  // Load bank data lazily when its tab is first opened.
  useEffect(() => {
    if (tab !== "topics" || !user || bankTopics.length === 0) return;
    if (!bankTopicId) setBankTopicId(bankTopics[0].id);
    (async () => { await Promise.all([loadBankAttempts(), loadBankSummary()]); })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab, user, bankTopics]);

  useEffect(() => {
    if (tab !== "topics" || !bankTopicId) return;
    (async () => {
      const { data, error } = await supabase.rpc("browse_questions", {
        _topic_id: bankTopicId,
        _difficulty: bankDifficulty === "all" ? null : bankDifficulty,
        _exam_type: bankExamType === "all" ? null : bankExamType,
        _limit: 200,
        _offset: 0,
      });
      if (error) {
        // An empty panel is not the same as "no questions here".
        toast({ title: "Could not load questions", description: error.message, variant: "destructive" });
        setBankQuestions([]);
        return;
      }
      setBankQuestions(((data ?? []) as unknown as BankQuestion[]));
    })();
  }, [tab, bankTopicId, bankDifficulty, bankExamType]);

  const filteredReview = useMemo(() => {
    const q = search.trim().toLowerCase();
    return questions.filter((x) =>
      (difficulty === "all" || x.difficulty === difficulty) &&
      (!topicFilter || x.topic_id === topicFilter) &&
      (!q || x.question_text.toLowerCase().includes(q) || (x.topic_name ?? "").toLowerCase().includes(q) || x.quiz_title.toLowerCase().includes(q)));
  }, [questions, search, difficulty, topicFilter]);

  const filteredBank = useMemo(() => {
    const q = bankSearch.trim().toLowerCase();
    return q ? bankQuestions.filter((x) => x.question_text.toLowerCase().includes(q) || x.quiz_title.toLowerCase().includes(q)) : bankQuestions;
  }, [bankQuestions, bankSearch]);

  // ---------- Drill flow ----------
  const buildSession = async (topicId: string, topicName: string) => {
    // `if (pool.length === 0) return;` used to end this function with no state
    // change and no message, so clicking Drill on a topic without published
    // questions looked like a dead button. Errors were discarded too (the RPC
    // result's `error` was never read), which hid real failures the same way.
    if (drillLoadingId) return;
    setDrillLoadingId(topicId);
    try {
      const { data: qs, error } = await supabase.rpc("get_practice_questions", {
        _topic_id: topicId,
        _limit: 10,
      });
      if (error) {
        toast({
          title: "Could not start the drill",
          description: error.message,
          variant: "destructive",
        });
        return;
      }
      const pool: DrillQuestion[] = (qs ?? []).map((q) => ({
        id: q.id,
        question_text: q.question_text,
        options: Array.isArray(q.options) ? (q.options as string[]) : [],
        topic_name: topicName,
      }));
      if (pool.length === 0) {
        toast({
          title: "No questions to drill yet",
          description: `Nothing published for ${topicName} yet — try another topic or the Topic questions tab.`,
        });
        return;
      }
      setDrill(pool);
      setDrillTopic(topicName);
      setDrillIdx(0);
      setDrillSelected(null);
      setDrillCorrect(0);
      setDrillDone(false);
    } catch (e) {
      toast({
        title: "Could not start the drill",
        description: e?.message ?? "Unexpected error",
        variant: "destructive",
      });
    } finally {
      setDrillLoadingId(null);
    }
  };

  const handleDrillAnswer = async (i: number) => {
    if (drillSelected !== null) return;
    setDrillSelected(i);
    const { data, error } = await supabase.rpc("check_practice_answer", {
      _question_id: drill[drillIdx].id,
      _selected: i,
    });
    // Without this, a failed marking call left the option highlighted with no
    // verdict and no explanation — indistinguishable from a broken answer.
    if (error || !data) {
      setDrillSelected(null);
      toast({
        title: "Could not check that answer",
        description: error?.message ?? "Please try again.",
        variant: "destructive",
      });
      return;
    }
    const result = (data ?? {}) as { correct?: boolean; correct_option?: number; explanation?: string | null; corrected_mistake?: boolean };
    setDrill((prev) => prev.map((q, k) => k === drillIdx ? { ...q, correct_option: result.correct_option, explanation: result.explanation ?? null } : q));
    if (result.correct) setDrillCorrect((c) => c + 1);
    setDrillCorrected(Boolean(result.corrected_mistake));
  };

  const drillNext = () => {
    if (drillIdx + 1 < drill.length) { setDrillIdx(drillIdx + 1); setDrillSelected(null); setDrillCorrected(false); }
    else setDrillDone(true);
  };
  const drillReset = () => { setDrill([]); setDrillDone(false); setDrillIdx(0); setDrillSelected(null); setDrillCorrect(0); setDrillCorrected(false); };

  // ---------- Review flow ----------
  const startReview = (q: ReviewQuestion) => { setActive(q); setSelected(null); setReveal(null); };

  const submitReview = async () => {
    if (!active || selected === null) return;
    const { data, error } = await supabase.rpc("check_practice_answer", {
      _question_id: active.id,
      _selected: selected,
    });
    if (error) { setError(error.message); return; }
    const res = data as PracticeVerdict;
    setReveal({
      correct_option: res.correct_option,
      explanation: res.explanation,
      correct: res.correct,
      corrected: Boolean(res.corrected_mistake),
    });
    setQuestions((prev) => prev.map((q) => q.id === active.id
      ? { ...q, last_correct: res.correct, attempts_count: q.attempts_count + 1 } : q));
  };

  // ---------- Topic-question flow ----------
  const startBankQuestion = (q: BankQuestion) => { setBankActive(q); setBankSelected(null); setBankReveal(null); };

  const submitBankQuestion = async (i: number) => {
    if (!bankActive || bankSelected !== null) return;
    setBankSelected(i);
    const { data, error } = await supabase.rpc("check_practice_answer", { _question_id: bankActive.id, _selected: i });
    // `if (!data) return;` used to leave the chosen option highlighted forever
    // with no verdict: the student clicks an answer and nothing happens.
    if (error || !data) {
      setBankSelected(null);
      toast({
        title: "Could not check that answer",
        description: error?.message ?? "Please try again.",
        variant: "destructive",
      });
      return;
    }
    const r = data as PracticeVerdict;
    setBankReveal({
      correct_option: r.correct_option,
      explanation: r.explanation,
      correct: r.correct,
      corrected: Boolean(r.corrected_mistake),
    });
    loadBankAttempts();
    loadBankSummary();
  };

  const visibleLevelOptions = useMemo(() => {
    if (isAdmin || !prefsLoaded) return levelOptions;
    return levelOptions.filter((l) => pickedIds.has(l.id));
  }, [levelOptions, pickedIds, prefsLoaded, isAdmin]);

  const visibleWeakTopics = useMemo(() => {
    if (isAdmin || !prefsLoaded) return weakTopics;
    return weakTopics.filter((t) => pickedSlByTopic.get(t.id));
  }, [weakTopics, pickedIds, prefsLoaded, isAdmin, pickedSlByTopic]);

  const visibleBankTopics = useMemo(() => {
    if (isAdmin || !prefsLoaded) return bankTopics;
    return bankTopics.filter((t) => pickedSlByTopic.get(t.id));
  }, [bankTopics, pickedIds, prefsLoaded, isAdmin, pickedSlByTopic]);

  // The summary RPC is platform-wide, so its totals used to read "2 / 1940" and
  // its topic list named subjects the student never picked. Scope it the same
  // way as every other list on this page.
  const visibleBankSummary = useMemo(() => {
    if (!filtering) return bankSummary;
    return bankSummary.filter((s) => pickedSlByTopic.has(s.topic_id));
  }, [bankSummary, pickedIds, prefsLoaded, isAdmin, pickedSlByTopic]);

  // Keep the topic picker showing something real. It defaults to the first
  // topic in the whole bank, which for a student is usually NOT one of their
  // picked subject-levels — a Radix Select with a value that has no matching
  // item renders blank, so the control looked empty (and broken) while it was
  // silently filtering the question list.
  useEffect(() => {
    if (tab !== "topics" || visibleBankTopics.length === 0) return;
    if (!visibleBankTopics.some((t) => t.id === bankTopicId)) {
      setBankTopicId(visibleBankTopics[0].id);
    }
  }, [tab, visibleBankTopics, bankTopicId]);

  // Subject & level gate: students must pick at least one subject (and its
  // level) before any practice content renders — nothing is shown while prefs
  // are loading or when nothing is picked. Early returns sit after every hook.
  if (!isAdmin && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Skeleton className="h-8 w-8 rounded-full" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/practice" />
        <SubjectGate />
      </div>
    );
  }

  // ---------- Render: active drill ----------
  if (drill.length > 0 && !drillDone) {
    const q = drill[drillIdx];
    return (
      <div className="max-w-2xl mx-auto space-y-5">
        <SEOHead path="/practice" />
        <div className="flex items-center justify-between">
          <Button variant="ghost" onClick={drillReset}>← Exit</Button>
          <Badge variant="outline">{drillIdx + 1} / {drill.length}</Badge>
        </div>
        <ManuscriptQuestion
          eyebrow={`Drill · ${drillIdx + 1} of ${drill.length} · ${q.topic_name}`}
          question={q.question_text}
          options={q.options}
          selected={drillSelected}
          correctOption={drillSelected !== null ? q.correct_option : null}
          disabled={drillSelected !== null}
          onSelect={handleDrillAnswer}
          explanation={drillSelected !== null ? q.explanation : null}
          footer={
            <>
              {drillCorrected && drillSelected !== null && (
                <p className="text-xs text-primary/90 flex items-center gap-1.5">
                  <Sparkles className="h-3.5 w-3.5" /> That one had you before — it doesn't now.
                </p>
              )}
              {drillSelected !== null && (
                <Button className="w-full mt-2" onClick={drillNext}>
                  {drillIdx + 1 < drill.length ? "Next question →" : "Finish session"}
                </Button>
              )}
            </>
          }
        />
      </div>
    );
  }

  if (drillDone) {
    const pct = Math.round((drillCorrect / drill.length) * 100);
    return (
      <div className="max-w-md mx-auto text-center space-y-4 py-10">
        <SEOHead path="/practice" />
        <Sparkles className="h-12 w-12 text-primary mx-auto" />
        <h2 className="text-2xl font-bold">Session complete</h2>
        <p className="text-4xl font-bold neon-text">{drillCorrect}/{drill.length}</p>
        <p className="text-muted-foreground">{pct}% on {drillTopic}</p>
        <FeedbackNudge tool="question" toolLabel={`${drillTopic} drill`} />
        <Button onClick={drillReset} className="gap-2"><RotateCcw className="h-4 w-4" /> Try another topic</Button>
      </div>
    );
  }

  // ---------- Render: topic-question focus view ----------
  if (bankActive) {
    return (
      <div className="max-w-2xl mx-auto space-y-5">
        <SEOHead path="/practice" />
        <div className="flex items-center justify-between">
          <Button variant="ghost" onClick={() => setBankActive(null)}>← Back to questions</Button>
          <Badge variant="outline">{bankActive.quiz_title}</Badge>
        </div>
        <ManuscriptQuestion
          eyebrow={`Question bank · ${bankActive.quiz_title}`}
          question={bankActive.question_text}
          options={bankActive.options}
          selected={bankSelected}
          correctOption={bankReveal ? bankReveal.correct_option : null}
          disabled={bankSelected !== null}
          onSelect={submitBankQuestion}
          explanation={bankReveal?.explanation ?? null}
          footer={
            <>
              {bankReveal?.corrected && (
                <p className="text-xs text-primary/90 flex items-center gap-1.5">
                  <Sparkles className="h-3.5 w-3.5" /> That one had you before — it doesn't now.
                </p>
              )}
              {bankReveal && (
                <Button className="w-full mt-2" onClick={() => setBankActive(null)}><RotateCcw className="h-4 w-4 mr-2" /> Pick another</Button>
              )}
            </>
          }
        />
      </div>
    );
  }

  // ---------- Render: hub ----------
  return (
    <div className="space-y-6">
      <SEOHead path="/practice" />
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
            <Target className="h-6 w-6 text-primary" /> Practice
          </h1>
          <p className="text-muted-foreground">Every question in one place: browse by topic, revisit the ones you're less sure of, and fix mistakes.</p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant={mode === "bookmarked" ? "secondary" : "outline"}
            size="sm"
            className="gap-1.5"
            aria-pressed={mode === "bookmarked"}
            onClick={() => {
              const next = new URLSearchParams(params);
              next.set("tab", "review");
              if (mode === "bookmarked") next.delete("mode");
              else next.set("mode", "bookmarked");
              setParams(next, { replace: true });
            }}
          >
            <Bookmark className="h-3.5 w-3.5" /> Bookmarked
          </Button>
          <SubjectPicker />
        </div>
      </div>

      <Tabs value={tab} onValueChange={(v) => setParam("tab", v)}>
        <TabsList className="flex-wrap h-auto justify-start gap-1">
          <TabsTrigger value="topics" className="gap-1.5"><Database className="h-3.5 w-3.5" /> Topic questions</TabsTrigger>
          <TabsTrigger value="review" className="gap-1.5"><RotateCcw className="h-3.5 w-3.5" /> Review</TabsTrigger>
          <TabsTrigger value="drills" className="gap-1.5"><Sparkles className="h-3.5 w-3.5" /> Smart drills</TabsTrigger>
        </TabsList>

        {/* Topic questions (old QuestionBank) */}
        <TabsContent value="topics" className="mt-4 space-y-4">
          <SavedProgressPanel
            summary={visibleBankSummary}
            loading={summaryLoading}
            error={null}
            onRetry={loadBankSummary}
            onJump={(id) => setBankTopicId(id)}
          />
          <Card>
            <CardContent className="flex flex-col sm:flex-row flex-wrap gap-3 p-4">
              <Select value={bankTopicId} onValueChange={setBankTopicId}>
                <SelectTrigger className="sm:w-60"><SelectValue placeholder="Pick a topic" /></SelectTrigger>
                <SelectContent>{visibleBankTopics.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent>
              </Select>
              <Select value={bankDifficulty} onValueChange={setBankDifficulty}>
                <SelectTrigger className="sm:w-40"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Any difficulty</SelectItem>
                  <SelectItem value="easy">Easy</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="hard">Hard</SelectItem>
                </SelectContent>
              </Select>
              <Select value={bankExamType} onValueChange={setBankExamType}>
                <SelectTrigger className="sm:w-40"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Any exam type</SelectItem>
                  <SelectItem value="quiz">Quiz</SelectItem>
                  <SelectItem value="exam">Exam</SelectItem>
                  <SelectItem value="mock">Mock</SelectItem>
                  <SelectItem value="ai_bank">Question bank</SelectItem>
                </SelectContent>
              </Select>
              <div className="relative flex-1 min-w-[180px]">
                <Search className="h-4 w-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
                <Input className="pl-9" aria-label="Search topic questions" placeholder="Search questions…" value={bankSearch} onChange={(e) => setBankSearch(e.target.value)} />
              </div>
            </CardContent>
          </Card>
          <QuestionList
            items={filteredBank}
            attempts={bankAttempts}
            onStart={startBankQuestion}
            onBookmark={(id, next) => setBankQuestions((prev) => prev.map((q) => q.id === id ? { ...q, bookmarked: next } : q))}
            loading={false}
          />
        </TabsContent>

        {/* Review (incorrect/bookmarked) */}
        <TabsContent value="review" className="mt-4 space-y-4">
          <Card>
            <CardContent className="flex flex-wrap items-center gap-3 p-4">
              {mode === "bookmarked" ? (
                <Badge variant="secondary" className="gap-1.5">
                  <Bookmark className="h-3.5 w-3.5" /> Bookmarked questions
                </Badge>
              ) : (
                <Tabs value={mode} onValueChange={(v) => setParam("mode", v)}>
                  <TabsList>
                    <TabsTrigger value="incorrect">Incorrect</TabsTrigger>
                    <TabsTrigger value="all">Both</TabsTrigger>
                  </TabsList>
                </Tabs>
              )}
              <Select value={defaultedLevelId} onValueChange={(v) => setParam("level", v)}>
                <SelectTrigger className="w-[230px]"><SelectValue placeholder="Subject & level" /></SelectTrigger>
                <SelectContent>
                  {isAdmin ? (
                    <SelectItem value="all">All subjects & levels</SelectItem>
                  ) : null}
                  {visibleLevelOptions.map((l) => <SelectItem key={l.id} value={l.id}>{l.label}</SelectItem>)}
                </SelectContent>
              </Select>
              <Select value={difficulty} onValueChange={setDifficulty}>
                <SelectTrigger className="w-[140px]"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Any difficulty</SelectItem>
                  <SelectItem value="easy">Easy</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="hard">Hard</SelectItem>
                </SelectContent>
              </Select>
              <div className="relative flex-1 min-w-[180px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search questions or topics" aria-label="Search review questions" className="pl-9" />
              </div>
            </CardContent>
          </Card>

          {error && (
            <Card className="border-destructive/40">
              <CardContent className="flex items-center justify-between gap-3 p-4">
                <p className="text-sm text-destructive flex items-center gap-2"><AlertCircle className="h-4 w-4" /> {error}</p>
                <Button size="sm" variant="outline" onClick={loadReviewQuestions}>Try again</Button>
              </CardContent>
            </Card>
          )}

          {active && (
            <ManuscriptQuestion
              eyebrow={`Review · ${active.topic_name ?? "General"} · ${active.quiz_title}`}
              question={active.question_text}
              options={active.options}
              selected={selected}
              correctOption={reveal ? reveal.correct_option : null}
              disabled={Boolean(reveal)}
              onSelect={(i) => !reveal && setSelected(i)}
              explanation={reveal?.explanation ?? null}
              actions={
                <BookmarkButton questionId={active.id} bookmarked={active.bookmarked}
                  onChange={(next) => setQuestions((p) => p.map((q) => q.id === active.id ? { ...q, bookmarked: next } : q))} />
              }
              footer={
                reveal ? (
                  <div className="space-y-3">
                    <p className={cn("text-sm font-semibold flex items-center gap-2", reveal.correct ? "text-emerald-600" : "text-destructive")}>
                      {reveal.correct ? <CheckCircle2 className="h-4 w-4" /> : <XCircle className="h-4 w-4" />}
                      {reveal.correct ? "Correct" : "Not quite"}
                    </p>
                    {reveal.corrected && (
                      <p className="text-sm text-primary/90 flex items-center gap-1.5">
                        <Sparkles className="h-4 w-4" /> That one had you before — it doesn't now.
                      </p>
                    )}
                    <div className="flex gap-2">
                      <Button size="sm" variant="outline" onClick={() => setActive(null)}>Close</Button>
                      <Button size="sm" onClick={() => startReview(active)}>Try again</Button>
                    </div>
                  </div>
                ) : (
                  <div className="flex gap-2">
                    <Button size="sm" onClick={submitReview} disabled={selected === null}>Check answer</Button>
                    <Button size="sm" variant="ghost" onClick={() => setActive(null)}>Cancel</Button>
                  </div>
                )
              }
            />
          )}

          {loading ? (
            <div className="space-y-3">{[0, 1, 2].map((i) => <Skeleton key={i} className="h-20 rounded-2xl" />)}</div>
          ) : filteredReview.length === 0 ? (
            <Card>
              <CardContent className="p-8 text-center space-y-2">
                <Bookmark className="h-8 w-8 mx-auto text-muted-foreground/50" />
                <p className="text-sm text-muted-foreground">
                  {mode === "bookmarked" ? "You haven't bookmarked any questions yet." : "Nothing to review — great work!"}
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-3">
              {filteredReview.map((q) => (
                <Card key={q.id}>
                  <CardContent className="flex items-center justify-between gap-3 p-4">
                    <div className="min-w-0">
                      <p className="text-sm font-medium line-clamp-2">{q.question_text}</p>
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        <Badge variant="secondary">{q.topic_name ?? "General"}</Badge>
                        <Badge variant="outline" className="capitalize">{q.difficulty}</Badge>
                        {q.last_correct === false && <Badge variant="outline" className="text-destructive border-destructive/40">Incorrect</Badge>}
                        {q.bookmarked && <Badge variant="outline" className="text-primary border-primary/40">Bookmarked</Badge>}
                        {q.attempts_count > 0 && <Badge variant="outline">{q.attempts_count} attempts</Badge>}
                      </div>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                      <BookmarkButton questionId={q.id} bookmarked={q.bookmarked}
                        onChange={(next) => setQuestions((p) => p.map((x) => x.id === q.id ? { ...x, bookmarked: next } : x))} />
                      <Button size="sm" onClick={() => startReview(q)}>Practise</Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        {/* Smart drills */}
        <TabsContent value="drills" className="mt-4">
          <section className="space-y-3">
            {loadingWeak ? (
              <p className="text-sm text-muted-foreground">Loading…</p>
            ) : (
              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                {visibleWeakTopics.slice(0, 9).map((t, i) => (
                  <Card key={t.id} className={cn("transition-all hover:border-primary/40", i === 0 && "neon-border")}>
                    <CardContent className="p-4 flex items-center justify-between gap-3">
                      <div className="min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          {i === 0 && <Badge className="text-[10px] bg-primary/15 text-primary border-primary/30">Top priority</Badge>}
                          <span className="text-xs text-muted-foreground">Avg {t.avg}%</span>
                        </div>
                        <p className="font-semibold text-sm truncate">{t.name}</p>
                      </div>
                      <Button
                        size="sm"
                        onClick={() => buildSession(t.id, t.name)}
                        disabled={drillLoadingId !== null}
                        className="gap-1 shrink-0"
                      >
                        <Brain className="h-4 w-4" />
                        {drillLoadingId === t.id ? "Starting…" : "Drill"}
                      </Button>
                    </CardContent>
                  </Card>
                ))}
                {visibleWeakTopics.length === 0 && (
                  <Card className="sm:col-span-2 lg:col-span-3"><CardContent className="py-6 text-center text-sm text-muted-foreground">
                    <Layers className="h-8 w-8 mx-auto mb-2 opacity-40" />
                    Complete a quiz and we'll point you at the topics worth revisiting.
                  </CardContent></Card>
                )}
              </div>
            )}
          </section>
        </TabsContent>
      </Tabs>
    </div>
  );
}

// Merged progress page: summary cards + subject aggregates + topic mastery grid.
import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { useMySubjects } from "@/hooks/useMySubjects";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { SEOHead } from "@/components/SEOHead";
import { SubjectGate } from "@/components/SubjectGate";
import { subjectIcon, subjectAccent, LEVEL_LABELS, LEVELS, type SubjectLevelCode } from "@/lib/subjects";
import {
  BookOpen, Brain, ClipboardList, Sparkles, FileText, Bookmark, AlertCircle,
  ArrowRight, BarChart3, RotateCcw, Activity, TrendingUp, TrendingDown, Minus,
} from "lucide-react";

interface Row {
  subject_id: string;
  subject_name: string;
  subject_slug: string;
  subject_icon: string;
  subject_color: string;
  subject_level_id: string;
  level: SubjectLevelCode;
  topics_count: number;
  lessons_total: number;
  lessons_completed: number;
  materials_total: number;
  materials_bookmarked: number;
  quiz_attempts: number;
  quiz_avg_score: number;
  ai_questions_total: number;
  ai_questions_answered: number;
  ai_questions_correct: number;
  bookmarked_questions: number;
  incorrect_questions: number;
}

interface TopicStat {
  id: string;
  name: string;
  attempts: number;
  avgPercent: number;
  mastered: boolean;
  totalQuizzes: number;
  completedLessons: number;
  totalLessons: number;
  practiceIncorrect: number;
  practiceTotal: number;
  bookmarked: number;
}

const pct = (a: number, b: number) => (b > 0 ? Math.round((a / b) * 100) : 0);

function bandColor(pctVal: number, attempts: number): string {
  if (attempts === 0) return "bg-muted text-muted-foreground";
  if (pctVal >= 80) return "bg-success/90 text-success-foreground";
  if (pctVal >= 60) return "bg-primary/80 text-primary-foreground";
  if (pctVal >= 40) return "bg-warning text-warning-foreground";
  return "bg-destructive/90 text-destructive-foreground";
}

function bandLabel(pctVal: number, attempts: number) {
  if (attempts === 0) return { label: "Untried", icon: Minus };
  if (pctVal >= 80) return { label: "Mastered", icon: TrendingUp };
  if (pctVal >= 60) return { label: "On track", icon: TrendingUp };
  if (pctVal >= 40) return { label: "Practising", icon: Activity };
  return { label: "Needs work", icon: TrendingDown };
}

export default function ProgressPage() {
  const { user } = useAuth();
  const { pickedIds, loaded: prefsLoaded, isAdmin, needsSubjectPick } = useMySubjects();
  const [rows, setRows] = useState<Row[]>([]);
  const [topics, setTopics] = useState<TopicStat[]>([]);
  const [topicSL, setTopicSL] = useState<Map<string, string>>(new Map());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [levelFilter, setLevelFilter] = useState<string>("all");
  const [subjectFilter, setSubjectFilter] = useState<string>("all");

  useEffect(() => {
    if (!user) return;
    (async () => {
      setLoading(true);
      setError(null);
      const [spRes, topicsRes, quizzesRes, attemptsRes, lessonsRes, progressRes, practiceRes, bookmarkRes] = await Promise.all([
        supabase.rpc("get_subject_progress"),
        supabase.from("topics").select("id, name, subject_level_id").order("sort_order"),
        supabase.from("quizzes").select("id, topic_id").eq("is_published", true),
        supabase.from("quiz_attempts").select("quiz_id, score, total_questions").eq("user_id", user.id).not("completed_at", "is", null),
        supabase.from("lessons").select("id, topic_id"),
        supabase.from("lesson_progress").select("lesson_id").eq("user_id", user.id).eq("completed", true),
        supabase.from("practice_attempts").select("question_id, last_correct, attempts_count").eq("user_id", user.id),
        supabase.from("question_bookmarks").select("question_id").eq("user_id", user.id),
      ]);
      if (spRes.error) setError(spRes.error.message);
      setRows(((spRes.data ?? []) as unknown as Row[]));

      // Map topic_id -> subject_level_id so we can scope the heatmap to
      // the subjects the student actually picked.
      const slMap = new Map((topicsRes.data ?? []).map((t) => [t.id, t.subject_level_id]));
      setTopicSL(slMap);

      // Per-topic mastery (topic heatmap): quiz performance + practice
      // incorrect/bookmark signals + lesson completion.
      const quizTopic = new Map((quizzesRes.data ?? []).map((q) => [q.id, q.topic_id]));
      const practiceQ = new Map<string, { last_correct: boolean; attempts: number }>();
      (practiceRes.data ?? []).forEach((a) => {
        practiceQ.set(a.question_id, { last_correct: a.last_correct, attempts: a.attempts_count });
      });
      const bookmarkedIds = new Set((bookmarkRes.data ?? []).map((b) => b.question_id));

      // Map question_id -> topic_id so practice/bookmark signals can be
      // attributed to a topic.
      const questionTopic = new Map<string, string>();
      (quizzesRes.data ?? []).forEach((q) => {
        const tid = q.topic_id;
        if (tid) questionTopic.set(q.id, tid);
      });

      const attempts = attemptsRes.data ?? [];
      const lessons = lessonsRes.data ?? [];
      const completed = new Set((progressRes.data ?? []).map((p) => p.lesson_id));
      setTopics((topicsRes.data ?? []).map((t) => {
        const topicAttempts = attempts.filter((a) => quizTopic.get(a.quiz_id) === t.id);
        const totalPct = topicAttempts.reduce((s: number, a: any) => s + ((a.score ?? 0) / (a.total_questions || 1)) * 100, 0);
        const topicLessons = lessons.filter((l) => l.topic_id === t.id);

        // Practice + bookmark weak signals attributed to this topic.
        let practiceIncorrect = 0;
        let practiceTotal = 0;
        let bookmarked = 0;
        for (const q of quizzesRes.data ?? []) {
          if ((q as any).topic_id !== t.id) continue;
          const pq = practiceQ.get((q as any).id);
          if (pq) {
            practiceTotal += pq.attempts;
            if (!pq.last_correct) practiceIncorrect += 1;
          }
          if (bookmarkedIds.has((q as any).id)) bookmarked += 1;
        }

        return {
          id: t.id,
          name: t.name,
          attempts: topicAttempts.length,
          avgPercent: topicAttempts.length > 0 ? Math.round(totalPct / topicAttempts.length) : 0,
          mastered: topicAttempts.length > 0 && topicAttempts.every((a) => (a.score ?? 0) / (a.total_questions || 1) >= 0.8),
          totalQuizzes: (quizzesRes.data ?? []).filter((q) => q.topic_id === t.id).length,
          completedLessons: topicLessons.filter((l) => completed.has(l.id)).length,
          totalLessons: topicLessons.length,
          practiceIncorrect,
          practiceTotal,
          bookmarked,
        };
      }));
      setLoading(false);
    })();
  }, [user]);

  const subjects = useMemo(() => {
    const seen = new Map<string, string>();
    rows.forEach((r) => {
      if (isAdmin || !prefsLoaded || pickedIds.has(r.subject_level_id)) {
        seen.set(r.subject_id, r.subject_name);
      }
    });
    return [...seen.entries()];
  }, [rows, isAdmin, prefsLoaded, pickedIds]);

  // Only show subject-level rows that belong to a subject-level the student
  // picked (or all for admins). This keeps the subject-summary cards scoped
  // to the student's chosen subjects.
  const visible = useMemo(
    () => rows.filter((r) =>
      (isAdmin || !prefsLoaded || pickedIds.has(r.subject_level_id)) &&
      (levelFilter === "all" || r.level === levelFilter) &&
      (subjectFilter === "all" || r.subject_id === subjectFilter)),
    [rows, levelFilter, subjectFilter, isAdmin, prefsLoaded, pickedIds],
  );

  const totals = useMemo(() => {
    const t = visible.reduce(
      (acc, r) => ({
        lessons: acc.lessons + Number(r.lessons_total),
        done: acc.done + Number(r.lessons_completed),
        attempts: acc.attempts + Number(r.quiz_attempts),
        scoreSum: acc.scoreSum + Number(r.quiz_avg_score) * Number(r.quiz_attempts),
        ai: acc.ai + Number(r.ai_questions_answered),
        aiCorrect: acc.aiCorrect + Number(r.ai_questions_correct),
        saved: acc.saved + Number(r.bookmarked_questions),
        wrong: acc.wrong + Number(r.incorrect_questions),
      }),
      { lessons: 0, done: 0, attempts: 0, scoreSum: 0, ai: 0, aiCorrect: 0, saved: 0, wrong: 0 },
    );
    const mastered = topics.filter((tp) => tp.mastered).length;
    return { ...t, avg: t.attempts ? Math.round(t.scoreSum / t.attempts) : 0, mastered };
  }, [visible]);

  // Topic heatmap scoped to the subjects the student picked. A student who
  // picks "Math AS" never sees Physics/CS topics here.
  const pickedTopicIds = useMemo(() => {
    if (isAdmin || !prefsLoaded) return new Set<string>();
    return new Set([...topicSL.entries()].filter(([, sl]) => pickedIds.has(sl)).map(([tid]) => tid));
  }, [topicSL, pickedIds, isAdmin, prefsLoaded]);

  const weakest = useMemo(
    () => [...topics]
      .filter((s) => pickedTopicIds.has(s.id) && s.attempts > 0)
      .sort((a, b) => {
        // Weakness = low quiz avg, weighted by practice incorrect + bookmarked.
        const wa = a.avgPercent - (a.practiceIncorrect * 5) - (a.bookmarked * 2);
        const wb = b.avgPercent - (b.practiceIncorrect * 5) - (b.bookmarked * 2);
        return wa - wb;
      })
      .slice(0, 3),
    [topics, pickedTopicIds],
  );

  const topicVisible = useMemo(
    () => topics.filter((s) => pickedTopicIds.has(s.id)),
    [topics, pickedTopicIds],
  );

  if (!isAdmin && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Skeleton className="h-8 w-8 rounded-full" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/progress" />
        <SubjectGate />
      </div>
    );
  }

  if (loading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-24 rounded-2xl" />
        {[0, 1, 2].map((i) => <Skeleton key={i} className="h-44 rounded-2xl" />)}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SEOHead path="/progress" />

      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
            <BarChart3 className="h-6 w-6 text-primary" /> Progress
          </h1>
          <p className="text-muted-foreground">Subject summaries, topic mastery, and where to focus next.</p>
        </div>
        <div className="flex gap-2">
          <Select value={subjectFilter} onValueChange={setSubjectFilter}>
            <SelectTrigger className="w-[170px]"><SelectValue placeholder="Subject" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All subjects</SelectItem>
              {subjects.map(([id, name]) => <SelectItem key={id} value={id}>{name}</SelectItem>)}
            </SelectContent>
          </Select>
          <Select value={levelFilter} onValueChange={setLevelFilter}>
            <SelectTrigger className="w-[150px]"><SelectValue placeholder="Level" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All levels</SelectItem>
              {LEVELS.map((l) => <SelectItem key={l} value={l}>{LEVEL_LABELS[l]}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
      </div>

      {error && (
        <Card className="border-destructive/40">
          <CardContent className="flex items-center justify-between gap-3 p-4">
            <p className="text-sm text-destructive flex items-center gap-2"><AlertCircle className="h-4 w-4" /> {error}</p>
            <Button size="sm" variant="outline" onClick={() => window.location.reload()} className="gap-1"><RotateCcw className="h-3.5 w-3.5" /> Try again</Button>
          </CardContent>
        </Card>
      )}

      {/* Summary cards */}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {[
          { label: "Lessons completed", value: `${totals.done}/${totals.lessons}`, icon: BookOpen },
          { label: "Quiz average", value: `${totals.avg}%`, icon: Brain },
          { label: "Topics mastered", value: `${totals.mastered}`, icon: ClipboardList },
          { label: "Saved / to review", value: `${totals.saved} / ${totals.wrong}`, icon: Bookmark },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="flex items-center gap-3 p-4">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary/10 border border-primary/20">
                <s.icon className="h-5 w-5 text-primary" />
              </div>
              <div>
                <p className="text-xl font-bold leading-none">{s.value}</p>
                <p className="text-xs text-muted-foreground mt-1">{s.label}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {visible.length === 0 && !error && (
        <Card><CardContent className="p-10 text-center text-muted-foreground">No active subject levels to track yet.</CardContent></Card>
      )}

      {/* Subject-level cards */}
      <div className="grid gap-4 lg:grid-cols-2">
        {visible.map((r) => {
          const Icon = subjectIcon(r.subject_icon);
          const accent = subjectAccent(r.subject_color);
          const lessonPct = pct(Number(r.lessons_completed), Number(r.lessons_total));
          const aiPct = pct(Number(r.ai_questions_answered), Number(r.ai_questions_total));
          const aiAcc = pct(Number(r.ai_questions_correct), Number(r.ai_questions_answered));
          return (
            <Card key={r.subject_level_id} className={accent.border}>
              <CardHeader className="flex-row items-start gap-3 space-y-0">
                <div className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border ${accent.border} ${accent.bg} ${accent.text}`}>
                  <Icon className="h-5 w-5" />
                </div>
                <div className="min-w-0 flex-1">
                  <CardTitle className="flex items-center gap-2 text-base">
                    {r.subject_name} <Badge variant="secondary">{LEVEL_LABELS[r.level]}</Badge>
                  </CardTitle>
                  <CardDescription>{r.topics_count} topics · {r.materials_total} materials</CardDescription>
                </div>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="text-muted-foreground flex items-center gap-1"><FileText className="h-3.5 w-3.5" /> Lessons completed</span>
                    <span className="font-semibold">{r.lessons_completed}/{r.lessons_total} · {lessonPct}%</span>
                  </div>
                  <Progress value={lessonPct} className="h-2" />
                </div>

                <div>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="text-muted-foreground flex items-center gap-1"><Brain className="h-3.5 w-3.5" /> Quiz average ({r.quiz_attempts} {Number(r.quiz_attempts) === 1 ? "attempt" : "attempts"})</span>
                    <span className="font-semibold">{Math.round(Number(r.quiz_avg_score))}%</span>
                  </div>
                  <Progress value={Number(r.quiz_avg_score)} className="h-2" />
                </div>

                <div>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="text-muted-foreground flex items-center gap-1"><Sparkles className="h-3.5 w-3.5" /> Question bank used</span>
                    {/* Only generated (AI) questions land in this bank; with none
                        published yet, "0/0 · 0% correct" looked like a fault. */}
                    <span className="font-semibold">
                      {Number(r.ai_questions_total) > 0
                        ? `${Number(r.ai_questions_answered)}/${Number(r.ai_questions_total)} · ${aiAcc}% correct`
                        : "—"}
                    </span>
                  </div>
                  <Progress value={aiPct} className="h-2" />
                </div>

                <div className="flex flex-wrap gap-2 pt-1">
                  <Badge variant="outline" className="gap-1"><Bookmark className="h-3 w-3" /> {r.bookmarked_questions} saved</Badge>
                  <Badge variant="outline" className="gap-1"><AlertCircle className="h-3 w-3" /> {r.incorrect_questions} to review</Badge>
                </div>

                <div className="flex flex-wrap gap-2">
                  <Button asChild size="sm" variant="outline" className="gap-1">
                    <Link to={`/study/${r.subject_slug}/${r.level.toLowerCase()}`}>Open hub <ArrowRight className="h-3.5 w-3.5" /></Link>
                  </Button>
                  <Button asChild size="sm" className="gap-1">
                    <Link to={`/practice?level=${r.subject_level_id}&mode=incorrect`}>Practice <ArrowRight className="h-3.5 w-3.5" /></Link>
                  </Button>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Topic heatmap — weak points from quizzes, practice and bookmarks,
          scoped to the subjects the student picked. */}
      <section className="space-y-3">
        <h2 className="text-sm font-semibold text-muted-foreground flex items-center gap-2">
          <Activity className="h-4 w-4 text-primary" /> Topic heatmap
        </h2>
        {weakest.length > 0 && (
          <Card className="neon-border">
            <CardHeader className="pb-3">
              <CardTitle className="text-base">Recommended focus</CardTitle>
              <CardDescription>Topics worth revisiting, gathered from quizzes, practice and your saved questions. A short drill on one of these moves your mark fastest.</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-wrap gap-2">
              {weakest.map((w) => (
                <Button key={w.id} asChild variant="outline" size="sm" className="gap-2">
                  <Link to={`/practice?topic=${w.id}`}>{w.name} · {w.avgPercent}%</Link>
                </Button>
              ))}
            </CardContent>
          </Card>
        )}
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {topicVisible.map((s) => {
            const band = bandLabel(s.avgPercent, s.attempts);
            const Icon = band.icon;
            return (
              <Card key={s.id} className="overflow-hidden">
                <div className={`h-1.5 ${bandColor(s.avgPercent, s.attempts)}`} />
                <CardContent className="p-4 space-y-2">
                  <div className="flex items-start justify-between gap-2">
                    <p className="font-semibold text-sm leading-tight">{s.name}</p>
                    <Badge variant="outline" className="gap-1 text-[10px]">
                      <Icon className="h-3 w-3" /> {band.label}
                    </Badge>
                  </div>
                  <div className="flex items-baseline gap-2">
                    <span className="text-2xl font-bold">{s.attempts > 0 ? `${s.avgPercent}%` : "—"}</span>
                    <span className="text-xs text-muted-foreground">{s.attempts} attempt{s.attempts === 1 ? "" : "s"}</span>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    {s.completedLessons}/{s.totalLessons} lessons · {s.totalQuizzes} quiz{s.totalQuizzes === 1 ? "" : "zes"}
                  </p>
                  {(s.practiceIncorrect > 0 || s.bookmarked > 0) && (
                    <div className="flex flex-wrap gap-1.5 pt-1">
                      {s.practiceIncorrect > 0 && (
                        <Badge variant="outline" className="gap-1 text-muted-foreground text-[10px]">
                          <RotateCcw className="h-3 w-3" /> {s.practiceIncorrect} to revisit
                        </Badge>
                      )}
                      {s.bookmarked > 0 && (
                        <Badge variant="outline" className="gap-1 text-primary border-primary/40 text-[10px]">
                          <Bookmark className="h-3 w-3" /> {s.bookmarked} saved
                        </Badge>
                      )}
                    </div>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </div>
      </section>
    </div>
  );
}

// Quiz hub: published quizzes per topic.
import { useEffect, useMemo, useRef, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { ManuscriptQuestion } from "@/components/StudyManuscript";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { useNavigate } from "react-router-dom";
import {
  Brain,
  Clock,
  CheckCircle2,
  XCircle,
  Download,
  Upload,
  Sparkles,
  Loader2,
  FileDown,
  ListChecks,
} from "lucide-react";
import { useToast } from "@/hooks/useToast";
import { loadFailureMessage } from "@/lib/net";
import { ToastAction } from "@/components/ui/toast";
import { SEOHead } from "@/components/SEOHead";
import { validateUploadFile } from "@/lib/fileValidation";
import { FREE_PREVIEW_LIMIT, PreviewLimit, usePlanAccess, usePreviewSliceWithLimit } from "@/components/PreviewLimit";
import { PreviewBanner } from "@/components/PreviewBanner";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";
import { exportQuizResultToPdf, gradeBand } from "@/lib/pdfExport";

function LocalLabel({ children, className }: { children: React.ReactNode; className?: string }) {
  return <label className={`text-sm font-medium ${className ?? ""}`}>{children}</label>;
}

interface StudentQuestion {
  id: string;
  quiz_id: string;
  question_text: string;
  options: string[];
  sort_order: number;
}

interface GradeResult {
  question_id: string;
  selected: number;
  correct_option: number;
  explanation: string | null;
  options: string[];
}

/** mm:ss for the sitting clock. */
function formatClock(totalSeconds: number) {
  const s = Math.max(0, totalSeconds);
  return `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;
}

type ReviewRow = {
  /** Position in the full paper, so "Q3" stays Q3 even when the list is filtered. */
  ordinal: number;
  question: StudentQuestion;
  result: GradeResult | undefined;
  /** What the student picked, or null when they left it blank. */
  picked: number | null;
  status: "correct" | "incorrect" | "unanswered";
};

export default function Quizzes() {
  const { toast } = useToast();
  const [quizzes, setQuizzes] = useState<any[]>([]);
  const [activeQuiz, setActiveQuiz] = useState<any>(null);
  const [questions, setQuestions] = useState<StudentQuestion[]>([]);
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState<{ correct: number; total: number } | null>(null);
  const [gradeResults, setGradeResults] = useState<GradeResult[]>([]);

  // Exam file submission
  const [submissionFile, setSubmissionFile] = useState<File | null>(null);
  const [uploadingSubmission, setUploadingSubmission] = useState(false);
  const [submissionUrl, setSubmissionUrl] = useState<string | null>(null);

  // AI feedback
  const [aiFeedback, setAiFeedback] = useState<string | null>(null);
  const [loadingFeedback, setLoadingFeedback] = useState(false);

  // Sitting clock. `time_limit_minutes` has always been shown on the hub card
  // but was never enforced, so a "45 minute paper" was just a label.
  const [secondsLeft, setSecondsLeft] = useState(0);
  const [timedOut, setTimedOut] = useState(false);
  const deadlineRef = useRef<number | null>(null);

  // Post-marking review: the whole paper, or just the ones to redo.
  const [reviewOnly, setReviewOnly] = useState(false);
  const [exporting, setExporting] = useState(false);

  const { loading: planLoading, isPreview, hasPaid } = usePlanAccess();

  useEffect(() => {
    supabase.from("quizzes").select("*, topics(*)").eq("is_published", true).order("created_at", { ascending: false })
      .then(({ data, error }) => {
        // PostgREST resolves with { error } instead of throwing, so ignoring it
        // turned a failed query into an empty list — "no quizzes yet" when the
        // truth was "could not load".
        if (error) {
          toast({ title: "Could not load quizzes", description: error.message, variant: "destructive" });
          return;
        }
        setQuizzes(data ?? []);
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Subject & level gate INPUTS. The gate itself renders below, after every
  // hook: returning early from above the hooks would change the hook count
  // between renders and trip React's "fewer hooks than expected" guard.
  const { user } = useAuth();
  const navigate = useNavigate();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  // Quizzes whose topic belongs to one of the student's picked subject-levels.
  //
  // `topics` is a to-one embed (quizzes.topic_id → topics.id), so PostgREST
  // returns an OBJECT. Reading it as an array (`topics?.[0]`) was undefined for
  // every quiz, which left the topic→level map empty and silently turned the
  // subject filter into a no-op — every student saw every subject's quizzes,
  // including the ones they had not picked.
  const visibleQuizzes = useMemo(() => {
    if (isAdminRole) return quizzes;
    if (!prefsLoaded) return [];
    // Anonymous visitors are not enrolled in anything, so they see the whole
    // published list. A signed-in student is scoped to their picks; either way
    // the free-plan slice above them decides how many are actually shown.
    if (!user) return quizzes;
    return quizzes.filter((q) => {
      const sl = (q as any).topics?.subject_level_id as string | undefined;
      return sl ? pickedIds.has(sl) : false;
    });
  }, [quizzes, isAdminRole, prefsLoaded, pickedIds, user]);

  // Free-plan preview: the first two quizzes of the picked subjects, sliced from
  // the same list the cards render. The previous approach rendered rows from
  // `get_free_preview`, whose shape (item_id / item_type / title) is not a quiz
  // row at all — free students got cards labelled "General" whose Start Quiz did
  // nothing, and paid students had their subject filter bypassed entirely.
  const { slice: shownQuizzes, hiddenCount } =
    usePreviewSliceWithLimit(visibleQuizzes, FREE_PREVIEW_LIMIT);

  const timeLimitSeconds = useMemo(() => {
    const minutes = Number(activeQuiz?.time_limit_minutes ?? 0);
    return Number.isFinite(minutes) && minutes > 0 ? Math.round(minutes * 60) : 0;
  }, [activeQuiz]);

  // Countdown from a wall-clock deadline, not a decrementing counter, so a
  // backgrounded tab does not quietly gain the student extra time. Cleared when
  // the quiz closes and when the paper is marked.
  useEffect(() => {
    if (!activeQuiz || !timeLimitSeconds || submitted) {
      deadlineRef.current = null;
      return;
    }
    deadlineRef.current = Date.now() + timeLimitSeconds * 1000;
    setTimedOut(false);
    const tick = () => {
      if (deadlineRef.current == null) return;
      const left = Math.max(0, Math.ceil((deadlineRef.current - Date.now()) / 1000));
      setSecondsLeft(left);
      if (left <= 0) setTimedOut(true);
    };
    tick();
    const id = window.setInterval(tick, 500);
    return () => window.clearInterval(id);
  }, [activeQuiz, timeLimitSeconds, submitted]);

  const timeUsedPct = timeLimitSeconds > 0
    ? Math.min(100, Math.round(((timeLimitSeconds - secondsLeft) / timeLimitSeconds) * 100))
    : 0;

  // One row per question, whatever happened to it, so the review, the counters
  // and the exported PDF all read from the same derivation.
  const reviewRows: ReviewRow[] = useMemo(() => {
    return questions.map((question, ordinal) => {
      const result = gradeResults.find((r) => r.question_id === question.id);
      const raw = answers[question.id];
      const picked = typeof raw === "number" ? raw : null;
      const status: ReviewRow["status"] = picked === null
        ? "unanswered"
        : result && picked === result.correct_option
          ? "correct"
          : "incorrect";
      return { ordinal, question, result, picked, status };
    });
  }, [questions, gradeResults, answers]);

  const counts = useMemo(() => {
    return reviewRows.reduce(
      (acc, row) => {
        acc[row.status] += 1;
        return acc;
      },
      { correct: 0, incorrect: 0, unanswered: 0 },
    );
  }, [reviewRows]);

  // Hooks are declared; now the early returns are safe.
  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead path="/quizzes" />
        <SubjectGate />
      </div>
    );
  }

  const startQuiz = async (quiz) => {
    // Questions are loaded through an approval-gated RPC and marking writes an
    // attempt, so a signed-out visitor is asked to sign in. Without this the
    // card click ended in "permission denied for function get_student_questions".
    if (!user) {
      toast({
        title: "Sign in to take this quiz",
        description: "Attempts are saved to your account so your progress counts.",
        action: <ToastAction altText="Sign in" onClick={() => navigate("/auth")}>Sign in</ToastAction>,
      });
      return;
    }
    const { data, error: questionsError } = await supabase.rpc("get_student_questions", { _quiz_id: quiz.id });
    // Without this a failed fetch opened an empty quiz that looked broken.
    if (questionsError) {
      toast({
        title: "Couldn't open that quiz",
        description: loadFailureMessage("this quiz", questionsError),
        variant: "destructive",
        action: <ToastAction altText="Retry" onClick={() => startQuiz(quiz)}>Retry</ToastAction>,
      });
      return;
    }
    setQuestions((data as StudentQuestion[]) ?? []);
    setActiveQuiz(quiz);
    setAnswers({});
    setSubmitted(false);
    setScore(null);
    setGradeResults([]);
    setSubmissionFile(null);
    setSubmissionUrl(null);
    setAiFeedback(null);
    setReviewOnly(false);
    setTimedOut(false);
    setSecondsLeft(0);
  };

  const uploadSubmission = async () => {
    if (!submissionFile || !user || !activeQuiz) return;
    setUploadingSubmission(true);
    const ext = submissionFile.name.split('.').pop();
    const path = `quiz-submissions/${user.id}/${activeQuiz.id}/${crypto.randomUUID()}.${ext}`;
    const { error } = await supabase.storage.from("homework-uploads").upload(path, submissionFile);
    if (error) {
      toast({ title: "Upload failed", description: error.message, variant: "destructive" });
      setUploadingSubmission(false);
      return;
    }
    setSubmissionUrl(path);
    setUploadingSubmission(false);
    toast({ title: "File uploaded!", description: "Your exam has been submitted." });
  };

  const submitQuiz = async () => {
    if (!user || !activeQuiz) return;

    // Send -1 for anything left blank. That matters when the clock ran out: the
    // student could not answer the rest, and an absent key would otherwise be
    // indistinguishable from "not part of this paper".
    const payload = Object.fromEntries(questions.map((q) => [q.id, answers[q.id] ?? -1]));

    const { data, error } = await supabase.rpc("grade_quiz", {
      _quiz_id: activeQuiz.id,
      _answers: payload,
      _submission_file_url: submissionUrl || null,
    });

    if (error) {
      toast({ title: "Submission failed", description: error.message, variant: "destructive" });
      return;
    }

    const result = data as unknown as { correct: number; total: number; results: GradeResult[] };
    setScore({ correct: result.correct, total: result.total });
    setGradeResults(result.results);
    setSubmitted(true);
    setReviewOnly(false);
    toast({ title: "Quiz submitted!", description: `You scored ${result.correct}/${result.total}` });
  };

  const exportResult = async () => {
    if (!activeQuiz) return;
    setExporting(true);
    try {
      await exportQuizResultToPdf({
        quizTitle: activeQuiz.title ?? "Quiz result",
        topicName: (activeQuiz as any).topics?.name ?? null,
        correct: score?.correct ?? 0,
        total: score?.total ?? questions.length,
        questions: reviewRows.map((row) => ({
          question: row.question.question_text,
          options: Array.isArray(row.question.options) ? row.question.options : [],
          selected: row.picked,
          // After a successful grade every question has a result row; -1 is only
          // a fallback so a missing row cannot be misread as "correct".
          correct_option: row.result?.correct_option ?? -1,
          explanation: row.result?.explanation ?? null,
        })),
        identity: { owner: user?.email ?? null },
      });
    } catch (e) {
      toast({ title: "Couldn't build the PDF", description: e?.message ?? "Please try again.", variant: "destructive" });
    } finally {
      setExporting(false);
    }
  };

  const getAiFeedback = async () => {
    if (!gradeResults.length || !activeQuiz) return;
    setLoadingFeedback(true);
    setAiFeedback(null);

    try {
      const { data, error } = await supabase.functions.invoke("quiz-feedback", {
        body: {
          quizId: activeQuiz.id,
          answers,
        },
      });



      if (error) throw error;
      if (data?.error) {
        toast({ title: "AI Feedback", description: data.error, variant: "destructive" });
      } else {
        setAiFeedback(data.feedback);
      }
    } catch (e) {
      toast({ title: "Failed to get feedback", description: e.message, variant: "destructive" });
    } finally {
      setLoadingFeedback(false);
    }
  };

  if (activeQuiz) {
    const hasExamFile = !!activeQuiz.exam_file_url;
    const percent = (score?.correct ?? 0) / Math.max(1, score?.total ?? 1) * 100;
    const visibleRows = reviewOnly
      ? reviewRows.filter((row) => row.status !== "correct")
      : reviewRows;

    return (
      <div className="space-y-6 max-w-3xl mx-auto">
        <SEOHead path="/quizzes" />
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold">{activeQuiz.title}</h1>
            <p className="text-muted-foreground">{questions.length} questions</p>
          </div>
          <Button variant="ghost" onClick={() => setActiveQuiz(null)}>← Back</Button>
        </div>

        {/* Sitting clock. Only for a timed paper, and only until it is marked. */}
        {timeLimitSeconds > 0 && !submitted && (secondsLeft > 0 || timedOut) && (
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Badge
                variant={timedOut ? "destructive" : "outline"}
                className="gap-1 font-mono text-sm"
                aria-live="polite"
              >
                <Clock className="h-3.5 w-3.5" /> {formatClock(secondsLeft)}
              </Badge>
              <span className="text-xs text-muted-foreground">
                {Number(activeQuiz.time_limit_minutes)}-minute paper · time used
              </span>
            </div>
            <Progress value={timeUsedPct} className="h-1.5" />
          </div>
        )}

        {timedOut && !submitted && (
          <div className="flex items-center gap-2 rounded-md border border-destructive/30 bg-destructive/5 px-3 py-2 text-sm text-destructive">
            <Clock className="h-4 w-4 shrink-0" /> Time's up — submit your paper for marking.
          </div>
        )}

        {hasExamFile && (
          <Card className="neon-border bg-card">
            <CardContent className="p-6 space-y-4">
              <h3 className="font-semibold text-lg">📄 Exam File</h3>
              <p className="text-sm text-muted-foreground">Download the exam, solve it, then upload your answers below.</p>
              <Button variant="outline" className="gap-2 border-primary/30 hover:border-primary/50" onClick={async () => {
                const path = activeQuiz.exam_file_url;
                const { data, error: signError } = await supabase.storage.from("quiz-files").createSignedUrl(path, 3600);
                // A silent failure here meant "Download Exam" simply did nothing.
                if (signError || !data?.signedUrl) {
                  toast({
                    title: "Couldn't open the exam file",
                    description: loadFailureMessage("this exam file", signError),
                    variant: "destructive",
                  });
                  return;
                }
                window.open(data.signedUrl, "_blank", "noopener,noreferrer");
              }}>
                <Download className="h-4 w-4" /> Download Exam
              </Button>
              {!submitted && (
                <div className="space-y-3 pt-2">
                  <LocalLabel className="text-sm font-medium">Upload your solved exam:</LocalLabel>
                  <div className="flex items-center gap-3">
                    <label className="flex-1 flex items-center gap-2 cursor-pointer rounded-lg border border-dashed border-border p-3 hover:border-primary/40 transition-colors bg-secondary/30">
                      <Upload className="h-4 w-4 text-muted-foreground" />
                      <span className="text-sm text-muted-foreground">
                        {submissionFile ? submissionFile.name : "Choose file..."}
                      </span>
                      <input type="file" className="hidden" onChange={(e) => {
                        const f = e.target.files?.[0] ?? null;
                        if (f) {
                          const result = validateUploadFile(f);
                          if (result.ok === false) {
                            toast({ title: "Invalid file", description: result.error, variant: "destructive" });
                            e.target.value = "";
                            return;
                          }
                        }
                        setSubmissionFile(f);
                      }} />
                    </label>
                    {submissionFile && !submissionUrl && (
                      <Button size="sm" onClick={uploadSubmission} disabled={uploadingSubmission}>
                        {uploadingSubmission ? "Uploading…" : "Upload"}
                      </Button>
                    )}
                  </div>
                  {submissionUrl && (
                    <p className="text-sm text-primary flex items-center gap-1">
                      <CheckCircle2 className="h-4 w-4" /> Exam submitted successfully
                    </p>
                  )}
                </div>
              )}
            </CardContent>
          </Card>
        )}

        {submitted && reviewRows.length > 0 && (
          <Card className="neon-border border-primary/30">
            <CardContent className="flex flex-wrap items-center justify-between gap-4 p-6">
              <div className="flex items-center gap-5">
                <div>
                  <p className="font-mono text-3xl font-bold neon-text">{score?.correct ?? 0}/{score?.total ?? 0}</p>
                  <p className="text-sm text-muted-foreground mt-1">
                    {percent.toFixed(0)}% · {gradeBand(percent)}
                  </p>
                </div>
                <div className="flex flex-wrap gap-2">
                  <Badge variant="secondary" className="gap-1">
                    <CheckCircle2 className="h-3 w-3" /> {counts.correct} correct
                  </Badge>
                  <Badge variant="outline" className="gap-1 text-destructive">
                    <XCircle className="h-3 w-3" /> {counts.incorrect} incorrect
                  </Badge>
                  {counts.unanswered > 0 && (
                    <Badge variant="outline" className="gap-1">{counts.unanswered} blank</Badge>
                  )}
                </div>
              </div>
              <div className="flex flex-wrap gap-2">
                <Button
                  variant={reviewOnly ? "default" : "outline"}
                  size="sm"
                  className="gap-2"
                  aria-pressed={reviewOnly}
                  onClick={() => setReviewOnly((v) => !v)}
                >
                  <ListChecks className="h-4 w-4" />
                  {reviewOnly ? "Showing what to review" : "Only what to review"}
                </Button>
                <Button variant="outline" size="sm" className="gap-2" onClick={exportResult} disabled={exporting}>
                  {exporting ? <Loader2 className="h-4 w-4 animate-spin" /> : <FileDown className="h-4 w-4" />}
                  Download result (PDF)
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  className="gap-2"
                  onClick={() => {
                    setAnswers({});
                    setSubmitted(false);
                    setScore(null);
                    setGradeResults([]);
                    setReviewOnly(false);
                    setAiFeedback(null);
                  }}
                >
                  Try again
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {submitted && reviewOnly && visibleRows.length === 0 && (
          <Card className="neon-border bg-card">
            <CardContent className="py-8 text-center text-sm text-muted-foreground">
              Nothing to review — every question was answered correctly.
            </CardContent>
          </Card>
        )}

        {visibleRows.map((row) => {
          const { question: q, result, ordinal } = row;
          const options = Array.isArray(q.options) ? q.options : [];
          return (
            <ManuscriptQuestion
              key={q.id}
              eyebrow={`Question ${ordinal + 1}`}
              question={q.question_text}
              options={options}
              selected={row.picked ?? null}
              correctOption={submitted && result ? result.correct_option : null}
              disabled={submitted || timedOut}
              onSelect={(i) => setAnswers((a) => ({ ...a, [q.id]: i }))}
              explanation={submitted ? result?.explanation ?? null : null}
            />
          );
        })}

        {!submitted ? (
          <Button
            onClick={submitQuiz}
            size="lg"
            className="w-full bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground glow-shadow"
            // Normally every question must be answered, but a run-out clock must
            // not trap the student: once time is up they can submit what they have.
            disabled={!timedOut && Object.keys(answers).length < questions.length}
          >
            {timedOut ? "Submit for marking (time's up)" : "Submit Quiz"}
          </Button>
        ) : (
          <div className="space-y-4">
            {/* AI Feedback Section */}
            {!aiFeedback && (
              <Button
                onClick={getAiFeedback}
                disabled={loadingFeedback}
                className="w-full gap-2 bg-gradient-to-r from-[hsl(var(--neon-purple))] to-primary text-primary-foreground"
                size="lg"
              >
                {loadingFeedback ? (
                  <><Loader2 className="h-4 w-4 animate-spin" /> Analyzing your answers…</>
                ) : (
                  <><Sparkles className="h-4 w-4" /> Get AI-Powered Feedback</>
                )}
              </Button>
            )}

            {aiFeedback && (
              <Card className="neon-border border-[hsl(var(--neon-purple))]/30 bg-card">
                <CardHeader className="pb-2">
                  <CardTitle className="text-lg flex items-center gap-2">
                    <Sparkles className="h-5 w-5 text-primary" />
                    AI Study Feedback
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="prose prose-sm dark:prose-invert max-w-none whitespace-pre-wrap text-sm leading-relaxed text-foreground/90">
                    {aiFeedback}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PreviewBanner />
      <SEOHead path="/quizzes" />
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Quizzes</h1>
        <p className="text-muted-foreground">Test your knowledge</p>
      </div>
      {shownQuizzes.length === 0 ? (
        <Card className="neon-border bg-card"><CardContent className="flex flex-col items-center py-12">
          <Brain className="h-12 w-12 text-muted-foreground/50 mb-4" />
          <p className="text-muted-foreground">No quizzes available yet.</p>
        </CardContent></Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {shownQuizzes.map((q) => (
            <Card key={q.id} className="cursor-pointer neon-border bg-card hover:border-primary/40 transition-all" onClick={() => startQuiz(q)}>
              <CardHeader className="pb-2">
                <div className="flex items-center justify-between">
                  <Badge variant="secondary">{(q as any).topics?.name ?? "General"}</Badge>
                  <div className="flex items-center gap-2">
                    {q.exam_file_url && <Badge variant="outline" className="border-primary/30 text-primary text-[10px]">📎 Exam</Badge>}
                    {q.time_limit_minutes && <span className="flex items-center gap-1 text-xs text-muted-foreground"><Clock className="h-3 w-3" />{q.time_limit_minutes}m</span>}
                  </div>
                </div>
                <CardTitle className="text-lg mt-2">{q.title}</CardTitle>
                {q.description && <CardDescription>{q.description}</CardDescription>}
              </CardHeader>
              <CardContent>
                <Button size="sm" className="w-full bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground">Start Quiz</Button>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
      <PreviewLimit hiddenCount={hiddenCount} what="quizzes" />
    </div>
  );
}

// AI study-plan generation and saved plans.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { callStudyPlanner } from "@/lib/ai";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/useToast";
import { usePlanAccess } from "@/components/PreviewLimit";
import { Loader2, Sparkles, Save, Trash2, Calendar as CalendarIcon, Lock } from "lucide-react";
import { Link } from "react-router-dom";
import { format } from "date-fns";
import { SEOHead } from "@/components/SEOHead";
import DOMPurify from "dompurify";
import { studyPlanToHtml } from "@/lib/objectiveTeach";

interface StudyPlan {
  id: string;
  title: string;
  content: string;
  start_date: string | null;
  end_date: string | null;
  created_at: string;
  subject_level_id: string | null;
  ai_generated: boolean;
  ai_model: string | null;
}

// Free users see their saved plans but cannot burn AI generation budget: the
// generate card is replaced with an upgrade prompt (same pattern as the AI
// marker's gate). The worker only checks approval, not plan, so this gate is
// what stops unlimited free generation.
function PlannerUpgradeCard() {
  return (
    <Card className="neon-border border-dashed">
      <CardContent className="flex flex-col items-center px-6 py-12 text-center">
        <div className="mb-5 flex h-14 w-14 items-center justify-center rounded-2xl border border-primary/20 bg-primary/10">
          <Lock className="h-7 w-7 text-primary" />
        </div>
        <h2 className="text-xl font-semibold">AI study plans are part of the full plan</h2>
        <p className="mt-2 max-w-md text-sm text-muted-foreground">
          Tell us your hours, exam date and weak topics, and the planner builds a
          personal revision schedule from your quiz results and deadlines.
        </p>
        <Button
          asChild
          size="lg"
          className="mt-7 gap-2 bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground"
        >
          <Link to="/pricing">
            <Sparkles className="h-4 w-4" /> View plans
          </Link>
        </Button>
      </CardContent>
    </Card>
  );
}

export default function StudyPlanner() {
  const { user } = useAuth();
  const { toast } = useToast();
  const { loading: planLoading, isPreview } = usePlanAccess();
  const [hoursPerWeek, setHoursPerWeek] = useState("5");
  const [targetExamDate, setTargetExamDate] = useState("");
  const [weakTopics, setWeakTopics] = useState("");
  const [generating, setGenerating] = useState(false);
  const [generatedPlan, setGeneratedPlan] = useState<string>("");
  const [planModel, setPlanModel] = useState<string>("");
  const [savedPlans, setSavedPlans] = useState<any[]>([]);
  const [planTitle, setPlanTitle] = useState("");

  const loadPlans = () => {
    if (!user) return;
    // supabase queries return a PostgrestBuilder. Use .then to get data.
    const q = supabase
      .from("study_plans")
      .select("*")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false });
    (q as any).then(({ data, error }: any) => {
      // Report instead of silently showing an empty planner.
      if (error) {
        toast({ title: "Could not load your plans", description: error.message, variant: "destructive" });
        return;
      }
      setSavedPlans(data ?? []);
    });
  };

  useEffect(() => { loadPlans(); }, [user]);

  const handleGenerate = async () => {
    if (!user) return;
    setGenerating(true);
    setGeneratedPlan("");
    setPlanModel("");
    try {
      const { quizPerformance, upcomingHomework, weakTopics: wt } = extractContext();
      const out = await callStudyPlanner({
        quizPerformance,
        upcomingHomework,
        weakTopics: wt,
        targetExamDate,
        hoursPerWeek: Number(hoursPerWeek) || 5,
        subjectLevelId: null,
      });
      setGeneratedPlan(out.plan);
      setPlanModel(out.model);
      setPlanTitle(`Study Plan – ${format(new Date(), "MMM d, yyyy")}`);
      toast({ title: "Plan generated", description: "Your personalized schedule is ready." });
    } catch (e) {
      toast({ title: "Generation failed", description: e?.message ?? "Please try again", variant: "destructive" });
    } finally {
      setGenerating(false);
    }
  };

  const handleSave = async () => {
    if (!user || !generatedPlan || !planTitle.trim()) return;
    const { error } = await supabase.from("study_plans").insert({
      user_id: user.id,
      title: planTitle.trim(),
      content: generatedPlan,
      start_date: new Date().toISOString().slice(0, 10),
      end_date: targetExamDate || null,
      subject_level_id: null,
      ai_generated: true,
      ai_model: planModel,
    });
    if (error) {
      toast({ title: "Save failed", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Plan saved", description: "Your AI-generated study plan is in your library." });
      setGeneratedPlan("");
      loadPlans();
    }
  };

  const handleDelete = async (id: string) => {
    const { error } = await supabase.from("study_plans").delete().eq("id", id);
    if (error) {
      toast({ title: "Delete failed", description: error.message, variant: "destructive" });
    } else {
      loadPlans();
    }
  };

  const extractContext = () => {
    let quizPerformance = "No completed quizzes yet";
    let upcomingHomework = "No upcoming deadlines";
    let weakTopics = "";

    if (user) {
      const { data: attempts } = (supabase
        .from("quiz_attempts")
        .select("score, total_questions, quizzes(title)")
        .eq("user_id", user.id)
        .not("completed_at", "is", null)
        .order("completed_at", { ascending: false })
        .limit(5)) as any;

      const { data: homework } = (supabase
        .from("homework")
        .select("title, due_date")
        .gte("due_date", new Date().toISOString())
        .order("due_date")
        .limit(5)) as any;

      const perf = (attempts ?? []).map((a) =>
        `${a.quizzes?.title ?? "Quiz"}: ${a.score ?? 0}/${a.total_questions ?? 0}`
      ).join("; ") || "No completed quizzes yet";
      quizPerformance = perf;
      upcomingHomework = (homework ?? []).map((h) =>
        `${h.title} (due ${h.due_date ? format(new Date(h.due_date), "MMM d") : "TBD"})`
      ).join("; ") || "No upcoming deadlines";

      weakTopics = "";
    }
    return { quizPerformance, upcomingHomework, weakTopics };
  };

  return (
    <div className="space-y-8">
      <SEOHead path="/study-planner" />
      <div>
        <h1 className="text-3xl font-bold flex items-center gap-2">
          <Sparkles className="h-7 w-7 text-primary" /> AI Study Planner
        </h1>
        <p className="text-muted-foreground mt-1">
          Get a personalized revision schedule built from your quiz results, deadlines, and weak topics.
        </p>
      </div>

      {planLoading ? (
        <Card>
          <CardContent className="flex items-center justify-center py-16">
            <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
          </CardContent>
        </Card>
      ) : isPreview ? (
        <PlannerUpgradeCard />
      ) : (
      <Card>
        <CardHeader>
          <CardTitle>Generate a new plan</CardTitle>
          <CardDescription>
            The AI uses your recent quiz scores, upcoming homework, and weak topics automatically.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="hours">Hours available per week</Label>
              <Input
                id="hours"
                type="number"
                min="1"
                max="40"
                value={hoursPerWeek}
                onChange={(e) => setHoursPerWeek(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="exam-date">Target exam date (optional)</Label>
              <Input
                id="exam-date"
                type="date"
                value={targetExamDate}
                onChange={(e) => setTargetExamDate(e.target.value)}
              />
            </div>
          </div>
          <div className="space-y-2">
            <Label htmlFor="weak">Topics you want to focus on (optional)</Label>
            <Textarea
              id="weak"
              placeholder="e.g., Quadratic equations, Kinematics, Algorithms..."
              value={weakTopics}
              onChange={(e) => setWeakTopics(e.target.value)}
              rows={3}
            />
          </div>
          <div className="flex gap-2">
            <Button onClick={handleGenerate} disabled={generating} className="flex-1">
              {generating ? (
                <><Loader2 className="mr-2 h-4 w-4 animate-spin" /> Generating…</>
              ) : (
                <><Sparkles className="mr-2 h-4 w-4" /> Generate Plan</>
              )}
            </Button>
          </div>
        </CardContent>
      </Card>
      )}

      {generatedPlan && (
        <Card className="neon-border">
          <CardHeader>
            <CardTitle>Your generated plan</CardTitle>
            <CardDescription>
              Review it below, then save it to your library.
            </CardDescription>
          </CardHeader>
          <CardContent>
            {/* The worker answers in markdown; render it as designed HTML
                rather than printing the raw markers (the old code showed
                literal `**`, `##` and `===`). The model id stays in the
                database row (ai_model) but is never shown to students —
                keep it that way; studyPlanToHtml also drops any `Model:`
                line the model emits. */}
            <div
              className="prose-elegant"
              dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(studyPlanToHtml(generatedPlan)) }}
            />
            <p className="mt-3 text-xs text-muted-foreground">
              AI-generated — can make mistakes. Check topics and dates against your Cambridge syllabus.
            </p>
            <div className="flex flex-col sm:flex-row gap-2 mt-4">
              <Input
                value={planTitle}
                onChange={(e) => setPlanTitle(e.target.value)}
                placeholder="Plan title"
                className="flex-1"
              />
              <Button onClick={handleSave} disabled={!planTitle.trim()}>
                <Save className="mr-2 h-4 w-4" /> Save plan
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      <div>
        <h2 className="text-xl font-semibold mb-4">Saved plans</h2>
        {savedPlans.length === 0 ? (
          <Card>
            <CardContent className="py-8 text-center text-muted-foreground text-sm">
              No saved plans yet. Generate one above to get started.
            </CardContent>
          </Card>
        ) : (
          <div className="space-y-3">
            {savedPlans.map((p) => (
              <Card key={p.id}>
                <CardHeader className="flex flex-row items-start justify-between gap-2 pb-2">
                  <div>
                    <CardTitle className="text-base">{p.title}</CardTitle>
                    <CardDescription className="flex items-center gap-1 mt-1 text-xs">
                      <CalendarIcon className="h-3 w-3" />
                      {format(new Date(p.created_at), "MMM d, yyyy")}
                      {p.end_date && <> → exam {format(new Date(p.end_date), "MMM d, yyyy")}</>}
                      {p.ai_generated && <span className="ml-2 text-[10px] font-semibold uppercase tracking-wider text-primary/70">AI generated</span>}
                    </CardDescription>
                  </div>
                  <div className="flex shrink-0 gap-1">
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => handleDelete(p.id)}
                      aria-label="Delete plan"
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </CardHeader>
                <CardContent>
                  <div
                    className="prose-elegant"
                    dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(studyPlanToHtml(p.content)) }}
                  />
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// Subject-level hub: materials, questions, exams, question-bank tabs.
import { useEffect, useMemo, useState } from "react";
import { Link, useParams, useLocation } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { SEOHead } from "@/components/SEOHead";
import { BookmarkButton } from "@/components/BookmarkButton";
import { subjectIcon, subjectAccent, LEVEL_LABELS, type SubjectLevelCode } from "@/lib/subjects";
import { levelHead } from "@/lib/levelSeo";
import { topicNotesPath, topicQuizPath, topicSlugOf } from "@/lib/topicUrls";
import { usePreviewSlice, PreviewLimit } from "@/components/PreviewLimit";
import { PreviewBanner } from "@/components/PreviewBanner";
import { useMySubjects } from "@/hooks/useMySubjects";
import { useAuth } from "@/lib/auth";
import { SubjectGate } from "@/components/SubjectGate";
import { BookOpen, FileText, Brain, Database, ArrowLeft, ArrowRight, Search, Sparkles, RotateCcw } from "lucide-react";
import { loadFailureMessage } from "@/lib/net";

interface BankQuestion {
  id: string;
  quiz_title: string;
  question_text: string;
  difficulty: string;
  exam_type: string;
  is_ai_generated: boolean;
  topic_id: string | null;
  topic_name: string | null;
  bookmarked: boolean;
  last_correct: boolean | null;
}

const ALL = "all";

export default function Subject() {
  const { slug = "", level = "" } = useParams();
  const levelCode = level.toUpperCase() as SubjectLevelCode;
  const location = useLocation();

  // If the URL has a hash (e.g. #questions, #bank), scroll to that tab after
  // the page and tabs render.
  useEffect(() => {
    const hash = location.hash.replace("#", "");
    if (!hash) return;

    const el = document.getElementById(hash);
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }, [location.hash]);

  const [loading, setLoading] = useState(true);
  const [subject, setSubject] = useState<any>(null);
  const [subjectLevel, setSubjectLevel] = useState<any>(null);
  const [topics, setTopics] = useState<any[]>([]);
  const [lessons, setLessons] = useState<any[]>([]);
  const [materials, setMaterials] = useState<any[]>([]);
  const [quizzes, setQuizzes] = useState<any[]>([]);
  const [questions, setQuestions] = useState<BankQuestion[]>([]);
  // AI-bank questions get their own query: browse_questions caps pages at 200
  // rows ordered by quiz title, so a client-side filter on the first page can
  // never reach the AI rows on large subjects. _ai_only filters server-side.
  const [aiQuestions, setAiQuestions] = useState<BankQuestion[]>([]);
  // The real reason a load failed. Without it a dropped request fell through to
  // the "isn't available yet" card and the student was told the subject does not
  // exist.
  const [loadError, setLoadError] = useState<string | null>(null);
  const [retryKey, setRetryKey] = useState(0);

  const { user } = useAuth();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  // filters
  const [search, setSearch] = useState("");
  const [topicFilter, setTopicFilter] = useState(ALL);
  const [difficulty, setDifficulty] = useState(ALL);
  const [examType, setExamType] = useState(ALL);

  useEffect(() => {
    let active = true;
    (async () => {
      setLoading(true);
      setLoadError(null);
      setSearch(""); setTopicFilter(ALL); setDifficulty(ALL); setExamType(ALL);
      const { data: subj, error: subjError } = await supabase
        .from("subjects").select("*").eq("slug", slug).maybeSingle();
      if (!active) return;
      if (subjError) { setLoadError(loadFailureMessage("this subject", subjError)); setLoading(false); return; }
      setSubject(subj ?? null);
      if (!subj) { setLoading(false); return; }

      const { data: sl, error: slError } = await supabase
        .from("subject_levels").select("*").eq("subject_id", subj.id).eq("level", levelCode).maybeSingle();
      if (!active) return;
      if (slError) { setLoadError(loadFailureMessage("this subject", slError)); setLoading(false); return; }
      setSubjectLevel(sl ?? null);
      if (!sl) { setLoading(false); return; }

      const { data: tp, error: tpError } = await supabase
        .from("topics").select("*").eq("subject_level_id", sl.id).order("sort_order");
      if (!active) return;
      if (tpError) { setLoadError(loadFailureMessage("this subject", tpError)); setLoading(false); return; }
      const topicList = tp ?? [];
      setTopics(topicList);
      const ids = topicList.map((t) => t.id);

      if (ids.length) {
        const [ls, ms, qz] = await Promise.all([
          supabase.from("lessons").select("id, title, topic_id, sort_order").in("topic_id", ids).order("sort_order"),
          supabase.from("study_materials").select("id, title, topic_id, material_type, file_url").in("topic_id", ids),
          supabase.from("quizzes").select("id, title, topic_id, description, is_published, exam_type, is_ai_generated").in("topic_id", ids),
        ]);
        if (!active) return;
        if (ls.error || ms.error || qz.error) {
          setLoadError(loadFailureMessage("this subject", ls.error ?? ms.error ?? qz.error));
          setLoading(false);
          return;
        }
        setLessons(ls.data ?? []);
        setMaterials(ms.data ?? []);
        setQuizzes((qz.data ?? []).filter((q) => q.is_published));
      } else {
        setLessons([]); setMaterials([]); setQuizzes([]);
      }
      setLoading(false);
    })();
    return () => { active = false; };
  }, [slug, levelCode, retryKey]);

  // questions come through the secure RPC (no answers exposed)
  useEffect(() => {
    if (!subjectLevel) { setQuestions([]); return; }
    let active = true;
    (async () => {
      const { data, error: rpcError } = await supabase.rpc("browse_questions", {
        _topic_id: topicFilter === ALL ? null : topicFilter,
        _subject_level_id: subjectLevel.id,
        _difficulty: difficulty === ALL ? null : difficulty,
        _exam_type: examType === ALL ? null : examType,
        _search: search.trim() || null,
        _limit: 200,
        _offset: 0,
      });
      if (!active) return;
      if (rpcError) { setLoadError(loadFailureMessage("the question bank", rpcError)); return; }
      setQuestions(((data ?? []) as unknown as BankQuestion[]));
      const { data: aiData, error: aiError } = await supabase.rpc("browse_questions", {
        _topic_id: topicFilter === ALL ? null : topicFilter,
        _subject_level_id: subjectLevel.id,
        _difficulty: difficulty === ALL ? null : difficulty,
        _exam_type: examType === ALL ? null : examType,
        _search: search.trim() || null,
        _ai_only: true,
        _limit: 200,
        _offset: 0,
      });
      if (!active) return;
      if (!aiError) setAiQuestions(((aiData ?? []) as unknown as BankQuestion[]));
    })();
    return () => { active = false; };
  }, [subjectLevel, topicFilter, difficulty, examType, search]);

  const topicNameMap = useMemo(() => new Map(topics.map((t) => [t.id, t.name])), [topics]);
  // Prefer the stored slug so links survive a topic rename.
  const topicSlugMap = useMemo(() => new Map(topics.map((t) => [t.id, topicSlugOf(t)])), [topics]);

  const matchesText = (...values: (string | null | undefined)[]) => {
    const q = search.trim().toLowerCase();
    if (!q) return true;
    return values.some((v) => (v ?? "").toLowerCase().includes(q));
  };
  const matchesTopic = (topicId: string | null) => topicFilter === ALL || topicId === topicFilter;

  const visibleLessons = lessons.filter((l) => matchesTopic(l.topic_id) && matchesText(l.title, topicNameMap.get(l.topic_id)));
  const visibleMaterials = materials.filter((m) => matchesTopic(m.topic_id) && matchesText(m.title, m.material_type, topicNameMap.get(m.topic_id)));
  const visibleQuizzes = quizzes.filter((q) =>
    matchesTopic(q.topic_id) && matchesText(q.title, q.description) &&
    (examType === ALL || q.exam_type === examType));
  // Free-plan preview: show only the first few items of every list; the rest
  // collapses into an upgrade prompt. Full-plan users see everything.
  const previewLessons = usePreviewSlice(visibleLessons);
  const previewMaterials = usePreviewSlice(visibleMaterials);
  const previewQuizzes = usePreviewSlice(visibleQuizzes);
  const previewQuestions = usePreviewSlice(questions);
  const visibleAiQuestions = aiQuestions.filter((q) => q.is_ai_generated);
  const previewAiQuestions = usePreviewSlice(visibleAiQuestions);

  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <div className="h-8 w-8 rounded-full border-primary/30 border animate-spin" />
      </div>
    );
  }
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead title={`${subject?.name ?? "Subject"} — Clutch Marks`} description="Lessons, revision materials, exams and a question bank." path={`/study/${slug}/${level}`} />
        <SubjectGate />
      </div>
    );
  }

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-28 rounded-2xl" />
        <Skeleton className="h-64 rounded-2xl" />
      </div>
    );
  }

  // Students only see subject-levels they picked; admins see everything.
  // `subjectLevel` must be non-null: without that, an unknown level (or a
  // failed lookup) also satisfied this test and the student was told they had
  // not selected a subject they never chose.
  if (!isAdminRole && user && prefsLoaded && subjectLevel && !pickedIds.has(subjectLevel.id)) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Subject not found</CardTitle>
          <CardDescription>You haven't selected this subject yet.</CardDescription>
        </CardHeader>
        <CardContent>
          <Button asChild variant="outline" className="gap-2">
            <Link to="/subjects"><ArrowLeft className="h-4 w-4" /> Back to subjects</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  if (loadError || !subject || !subjectLevel) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>{loadError ? "Couldn't load this subject" : "Subject not found"}</CardTitle>
          <CardDescription>{loadError ?? "This subject or level isn't available yet."}</CardDescription>
        </CardHeader>
        <CardContent className="flex flex-wrap gap-2">
          <Button variant="outline" className="gap-2" onClick={() => setRetryKey((k) => k + 1)}>
            <RotateCcw className="h-4 w-4" /> Try again
          </Button>
          <Button asChild variant="outline" className="gap-2">
            <Link to="/subjects"><ArrowLeft className="h-4 w-4" /> Back to subjects</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  const Icon = subjectIcon(subject.icon);
  const accent = subjectAccent(subject.color);

  const empty = (label: string) => (
    <p className="py-10 text-center text-sm text-muted-foreground">No {label} match your filters.</p>
  );

  const setBookmark = (id: string, next: boolean) =>
    setQuestions((prev) => prev.map((q) => (q.id === id ? { ...q, bookmarked: next } : q)));

  const questionCard = (q: BankQuestion) => (
    <Card key={q.id}>
      <CardContent className="flex items-center justify-between gap-3 p-4">
        <div className="min-w-0">
          <p className="text-sm font-medium line-clamp-2">{q.question_text}</p>
          <div className="flex flex-wrap gap-1.5 mt-2">
            <Badge variant="secondary">{q.topic_name ?? "General"}</Badge>
            <Badge variant="outline" className="capitalize">{q.difficulty}</Badge>
            {q.is_ai_generated && <Badge variant="outline" className="gap-1"><Sparkles className="h-3 w-3" /> Gen</Badge>}
            {q.last_correct === false && <Badge variant="outline" className="text-destructive border-destructive/40">Retry</Badge>}
          </div>
        </div>
        <div className="flex items-center gap-1 shrink-0">
          <BookmarkButton questionId={q.id} bookmarked={q.bookmarked} onChange={(next) => setBookmark(q.id, next)} />
          <Button asChild size="sm">
            <Link to={`/practice?tab=topics&topic=${q.topic_id ?? ""}`}>Practise</Link>
          </Button>
        </div>
      </CardContent>
    </Card>
  );

  return (
    <div className="space-y-6">
      {/* Title, description, canonical and JSON-LD come from levelSeo, which is
          also what the build-time prerenderer writes into this URL's static HTML
          — so the crawler's head and the browser's head cannot disagree. */}
      <SEOHead {...levelHead({ subjectSlug: slug, subjectName: subject.name, level })} />

      <div className={`glass-card p-6 flex flex-wrap items-center gap-4 ${accent.border}`}>
        <div className={`flex h-14 w-14 items-center justify-center rounded-2xl border ${accent.border} ${accent.bg} ${accent.text}`}>
          <Icon className="h-7 w-7" />
        </div>
        <div className="flex-1 min-w-[200px]">
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold tracking-tight">{subject.name}</h1>
            <Badge variant="secondary">{LEVEL_LABELS[levelCode]}</Badge>
          </div>
          <p className="text-sm text-muted-foreground">
            {subjectLevel.description || subject.description || "Everything you need for this level."}
          </p>
        </div>
        <div className="flex gap-2">
          <Button asChild variant="outline" size="sm" className="gap-2">
            <Link to={`/practice?level=${subjectLevel.id}&mode=incorrect`}>Practise mistakes</Link>
          </Button>
          <Button asChild variant="outline" size="sm" className="gap-2">
            <Link to="/subjects"><ArrowLeft className="h-4 w-4" /> All subjects</Link>
          </Button>
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-3">
        {[
          { label: "Topics", value: topics.length, icon: BookOpen },
          { label: "Lessons", value: lessons.length, icon: FileText },
          { label: "Exams & Quizzes", value: quizzes.length, icon: Brain },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="flex items-center gap-3 p-4">
              <s.icon className={`h-5 w-5 ${accent.text}`} />
              <div>
                <p className="text-xl font-bold leading-none">{s.value}</p>
                <p className="text-xs text-muted-foreground mt-1">{s.label}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card>
        <CardContent className="flex flex-wrap items-center gap-3 p-4">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input value={search} onChange={(e) => setSearch(e.target.value)} className="pl-9" placeholder="Search this subject…" />
          </div>
          <Select value={topicFilter} onValueChange={setTopicFilter}>
            <SelectTrigger className="w-[190px]"><SelectValue placeholder="Topic" /></SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL}>All topics</SelectItem>
              {topics.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}
            </SelectContent>
          </Select>
          <Select value={difficulty} onValueChange={setDifficulty}>
            <SelectTrigger className="w-[150px]"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL}>Any difficulty</SelectItem>
              <SelectItem value="easy">Easy</SelectItem>
              <SelectItem value="medium">Medium</SelectItem>
              <SelectItem value="hard">Hard</SelectItem>
            </SelectContent>
          </Select>
          <Select value={examType} onValueChange={setExamType}>
            <SelectTrigger className="w-[150px]"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL}>Any exam type</SelectItem>
              <SelectItem value="quiz">Quiz</SelectItem>
              <SelectItem value="exam">Exam</SelectItem>
              <SelectItem value="mock">Mock</SelectItem>
              <SelectItem value="ai_bank">Question bank</SelectItem>
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      <PreviewBanner />
      <Tabs defaultValue="materials">
        <TabsList className="flex-wrap h-auto" id="tabs">
          <TabsTrigger value="materials">Material ({visibleLessons.length + visibleMaterials.length})</TabsTrigger>
          <TabsTrigger value="questions">Questions ({questions.length})</TabsTrigger>
          <TabsTrigger value="exams">Exams &amp; Quizzes ({visibleQuizzes.length})</TabsTrigger>
          <TabsTrigger value="bank">Question Bank ({visibleAiQuestions.length})</TabsTrigger>
        </TabsList>

        <TabsContent value="materials" id="materials" className="space-y-3 pt-4">
          {visibleLessons.length === 0 && visibleMaterials.length === 0 ? empty("material") : (
            <>
              {previewLessons.map((l) => {
                const ts = topicSlugMap.get(l.topic_id);
                return (
                  <Card key={l.id}>
                    <CardContent className="flex items-center justify-between gap-3 p-4">
                      <div className="min-w-0">
                        <p className="font-medium truncate">{l.title}</p>
                        <p className="text-xs text-muted-foreground">Lesson · {topicNameMap.get(l.topic_id) ?? "General"}</p>
                      </div>
                      <Button asChild size="sm" variant="ghost" className="gap-1">
                        {ts ? (
                          <Link to={topicNotesPath(subject!.slug!, subjectLevel!.level.toLowerCase(), ts)}>Open <ArrowRight className="h-3.5 w-3.5" /></Link>
                        ) : (
                          <Link to="/lessons">Open <ArrowRight className="h-3.5 w-3.5" /></Link>
                        )}
                      </Button>
                    </CardContent>
                  </Card>
                );
              })}
              {previewMaterials.map((m) => {
                const ts = topicSlugMap.get(m.topic_id);
                return (
                  <Card key={m.id}>
                    <CardContent className="flex items-center justify-between gap-3 p-4">
                      <div className="min-w-0">
                        <p className="font-medium truncate">{m.title}</p>
                        <p className="text-xs text-muted-foreground capitalize">{m.material_type} · {topicNameMap.get(m.topic_id) ?? "General"}</p>
                      </div>
                      <Button asChild size="sm" variant="ghost" className="gap-1">
                        {ts ? (
                          <Link to={topicNotesPath(subject!.slug!, subjectLevel!.level.toLowerCase(), ts)}>Open <ArrowRight className="h-3.5 w-3.5" /></Link>
                        ) : (
                          <Link to="/notes">Open <ArrowRight className="h-3.5 w-3.5" /></Link>
                        )}
                      </Button>
                    </CardContent>
                  </Card>
                );
              })}
              <PreviewLimit
                hiddenCount={visibleLessons.length + visibleMaterials.length - previewLessons.length - previewMaterials.length}
                what="materials"
              />
            </>
          )}
        </TabsContent>

        <TabsContent value="questions" id="questions" className="space-y-3 pt-4">
          {previewQuestions.length === 0 ? empty("questions") : (
            <>
              {previewQuestions.map(questionCard)}
              <PreviewLimit hiddenCount={questions.length - previewQuestions.length} what="questions" />
            </>
          )}
        </TabsContent>

        <TabsContent value="exams" id="exams" className="space-y-3 pt-4">
          {visibleQuizzes.length === 0 ? empty("exams") : (
            <>
              {previewQuizzes.map((q) => {
                const ts = topicSlugMap.get(q.topic_id);
                return (
                  <Card key={q.id}>
                    <CardContent className="flex items-center justify-between gap-3 p-4">
                      <div className="min-w-0">
                        <p className="font-medium truncate">{q.title}</p>
                        <p className="text-xs text-muted-foreground truncate">{q.description || topicNameMap.get(q.topic_id) || "Exam"}</p>
                        <Badge variant="outline" className="mt-1.5 capitalize">{String(q.exam_type).replace("_", " ")}</Badge>
                      </div>
                      <Button asChild size="sm" variant="ghost" className="gap-1">
                        {ts ? (
                          <Link to={topicQuizPath(subject!.slug!, subjectLevel!.level.toLowerCase(), ts)}>Start <ArrowRight className="h-3.5 w-3.5" /></Link>
                        ) : (
                          <Link to="/quizzes">Start <ArrowRight className="h-3.5 w-3.5" /></Link>
                        )}
                      </Button>
                    </CardContent>
                  </Card>
                );
              })}
              <PreviewLimit
                hiddenCount={visibleQuizzes.length - previewQuizzes.length}
                what="exams & quizzes"
              />
            </>
          )}
        </TabsContent>

        <TabsContent value="bank" id="bank" className="space-y-3 pt-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2"><Database className="h-5 w-5 text-primary" /> Question Bank</CardTitle>
              <CardDescription>
                AI-written exam questions for {subject.name} {LEVEL_LABELS[levelCode]} with instant marking and explanations.
              </CardDescription>
            </CardHeader>
            <CardContent className="flex flex-wrap gap-3">
              <Button asChild className="gap-2"><Link to="/practice?tab=topics">Open topic questions <ArrowRight className="h-4 w-4" /></Link></Button>
            </CardContent>
          </Card>
          {previewAiQuestions.length === 0 ? empty("AI questions") : (
            <>
              {previewAiQuestions.map(questionCard)}
              <PreviewLimit hiddenCount={visibleAiQuestions.length - previewAiQuestions.length} what="AI questions" />
            </>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

// Per-topic notes page (SEO-friendly URL).
import { useEffect, useMemo, useState } from "react";
import { useParams, Link } from "react-router-dom";
import DOMPurify from "dompurify";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { SEOHead } from "@/components/SEOHead";
import { TopicBreadcrumb } from "@/components/TopicBreadcrumb";
import { subjectAccent, LEVELS, LEVEL_LABELS, type SubjectLevelCode } from "@/lib/subjects";
import { ManuscriptHead } from "@/components/StudyManuscript";
import { topicHead } from "@/lib/topicSeo";
import {
  topicNotesPath,
  topicQuizPath,
  slugifyTopicName,
  topicSlugOf,
} from "@/lib/topicUrls";
import { FileText, BookOpen, Play, ArrowRight, ArrowLeft, Pencil, ExternalLink, Download, RotateCcw } from "lucide-react";
import { ContentEditor } from "@/components/admin/ContentEditor";
import { MaterialPreview } from "@/components/MaterialPreview";
import { openProtectedFile } from "@/lib/contentFiles";
import { topicMasterySummary } from "@/lib/topicMastery";
import { TopicMasteryRing } from "@/components/TopicMasteryRing";
import { materialContentToHtml } from "@/lib/objectiveTeach";
import { toast } from "sonner";
import { useAuth } from "@/lib/auth";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";

export default function TopicNotes() {
  const { slug: subject, level, topic } = useParams<{ slug: string; level: string; topic: string }>();
  const { role } = useAuth();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [subjectMeta, setSubjectMeta] = useState<any>(null);
  const [subjectLevel, setSubjectLevel] = useState<any>(null);
  const [topicTitle, setTopicTitle] = useState<string | null>(null);
  const [topicId, setTopicId] = useState<string | null>(null);
  const topicSlug = slugifyTopicName(topic ?? "");
  const [lessons, setLessons] = useState<any[]>([]);
  const [materials, setMaterials] = useState<any[]>([]);
  const [quizzes, setQuizzes] = useState<any[]>([]);
  const [masteryRows, setMasteryRows] = useState<{ state: string }[] | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const bumpRevision = () => setReloadKey((k) => k + 1);

  const { user } = useAuth();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  // This student's objective states for the ring. Objectives exist only for
  // authored topics and the RPC is authenticated-only, so anything else
  // leaves the ring hidden rather than guessing.
  useEffect(() => {
    if (!topicId || !user) {
      setMasteryRows(null);
      return;
    }
    let live = true;
    supabase.rpc("topic_objective_mastery", { _topic_id: topicId }).then(({ data, error }) => {
      if (live && !error) setMasteryRows((data ?? []) as { state: string }[]);
    });
    return () => {
      live = false;
    };
  }, [topicId, user]);

  const mastery = masteryRows && masteryRows.length > 0 ? topicMasterySummary(masteryRows) : null;

  useEffect(() => {
    let active = true;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        const { data: sub, error: subError } = await supabase
          .from("subjects")
          .select("*")
          .ilike("slug", subject ?? "")
          .limit(1);
        if (subError) throw subError;
        const subjectRow = sub?.[0] ?? null;
        if (!subjectRow) {
          setError("Subject not found");
          setLoading(false);
          return;
        }
        setSubjectMeta(subjectRow);

        const { data: sl, error: slError } = await supabase
          .from("subject_levels")
          .select("*")
          .eq("subject_id", subjectRow.id)
          .eq("level", (level ?? "").toUpperCase() as SubjectLevelCode)
          .limit(1);
        if (slError) throw slError;
        const levelRow = sl?.[0] ?? null;
        if (!levelRow) {
          setError("Level not found");
          setLoading(false);
          return;
        }
        setSubjectLevel(levelRow);

        const { data: tps, error: tpsError } = await supabase
          .from("topics")
          .select("*")
          .eq("subject_level_id", levelRow.id)
          .order("sort_order");
        if (tpsError) throw tpsError;
        const topicList = tps ?? [];

        const normalizedTopic = topic?.replace(/-/g, " ") ?? "";
        const topicId = topicList.find(
          (t) =>
            t.name.toLowerCase() === normalizedTopic.toLowerCase() ||
            topicSlugOf(t) === topicSlug ||
            // Last-resort match for URLs minted before slugs were persisted.
            slugifyTopicName(t.name) === topicSlug,
        )?.id;
        if (!topicId) {
          setError("Topic not found on this level");
          setLoading(false);
          return;
        }
        const topicRow = topicList.find((t) => t.id === topicId) ?? null;
        setTopicTitle(topicRow?.name ?? normalizedTopic);
        setTopicId(topicId);

        const [ls, ms, qz] = await Promise.all([
          topicId && supabase.from("lessons").select("*, topics(name)").eq("topic_id", topicId).order("sort_order"),
          supabase.from("study_materials").select("*, topics(name)").eq("topic_id", topicId).order("created_at", { ascending: false }),
          supabase.from("quizzes").select("*, topics(name)").eq("topic_id", topicId).order("created_at", { ascending: false }),
        ]);

        setLessons((ls.data ?? []).filter(Boolean));
        setMaterials((ms.data ?? []).filter(Boolean));
        setQuizzes((qz.data ?? []).filter((q) => q.is_published));
      } catch (e) {
        setError(e.message ?? "Failed to load topic content");
      } finally {
        setLoading(false);
      }
    })();
    return () => { active = false; };
  }, [subject, level, topic, topicSlug, reloadKey]);

  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <div className="h-8 w-8 rounded-full border-primary/30 border animate-spin" />
      </div>
    );
  }
  // "Does this reader still have to pick subjects?" is asked in one place.
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead title={`${topicTitle ?? "Revision Notes"} — Clutch Marks`} description="Revision notes and topic questions." path={topicNotesPath(subjectMeta?.slug ?? "", subjectLevel?.level.toLowerCase() ?? "", topicSlug)} />
        <SubjectGate />
      </div>
    );
  }

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-28 rounded-2xl" />
        <Skeleton className="h-64 rounded-2xl" />
      </div>
    );
  }

  // Students only see topics belonging to a subject-level they picked.
  // Anonymous visitors are not enrolled in any subject yet, so they see the
  // topic regardless; signing in and picking it afterwards personalises the
  // view.
  if (!isAdminRole && user && prefsLoaded && topicId && !pickedIds.has(subjectLevel?.id ?? "")) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Topic not found</CardTitle>
          <CardDescription>You haven't selected this subject yet.</CardDescription>
        </CardHeader>
        <CardContent>
          <Button asChild variant="outline" className="gap-2">
            <Link to="/subjects"><ArrowLeft className="h-4 w-4" /> Back to subjects</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  if (error || !subjectMeta || !subjectLevel || !topicTitle) {
    return (
      <Card>
        <CardHeader>
          {/* A failed request is not the same as a missing topic. Saying
              "not found" for a dropped connection sent students looking for a
              problem in their notes instead of retrying. */}
          <CardTitle>
            {error && !/not found/i.test(error) ? "Couldn't load this topic" : "Topic not found"}
          </CardTitle>
          <CardDescription>{error ?? "The topic you are looking for is not yet available."}</CardDescription>
        </CardHeader>
        <CardContent className="flex flex-wrap gap-2">
          <Button variant="outline" className="gap-2" onClick={bumpRevision}>
            <RotateCcw className="h-4 w-4" /> Try again
          </Button>
          <Button asChild variant="outline" className="gap-2">
            <Link to="/subjects"><ArrowLeft className="h-4 w-4" /> Back to subjects</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  const accent = subjectAccent(subjectMeta.color);
  const levelCode = subjectLevel.level as SubjectLevelCode;
  const levelLabel = LEVEL_LABELS[levelCode];
  const topicSeo = topicHead(
    {
      subjectSlug: subjectMeta.slug,
      subjectName: subjectMeta.name,
      level: subjectLevel.level,
      topicSlug,
      topicName: topicTitle,
    },
    "notes",
  );

  const topicLessons = lessons.length;
  const topicNotesCount = materials.length;

  return (
    <div className="cm-study space-y-6">
      {/* Title, description, canonical and JSON-LD all come from topicSeo, which
          is also what the build-time prerenderer writes into this URL's static
          HTML — the head a crawler reads without running JavaScript and the head
          it reads after booting React are the same by construction. */}
      <SEOHead {...topicSeo} />

      <TopicBreadcrumb
        subjectName={subjectMeta.name}
        levelLabel={levelLabel}
        topicName={topicTitle}
        currentLabel="Revision Notes"
        subjectSlug={subjectMeta.slug}
        level={subjectLevel.level.toLowerCase()}
        topicSlug={topicSlug}
      />

      <ManuscriptHead
        eyebrow={`${subjectMeta.name} · ${levelLabel}`}
        title={topicTitle ?? topicSlug}
        lede={`Revision notes and topic questions for ${topicTitle} in ${subjectMeta.name} ${levelLabel}.`}
        actions={
          <Button asChild variant="outline" size="sm" className="gap-2">
            <Link to={`/practice?level=${subjectLevel.id}&topic=${topicId}`}>Practise mistakes <ArrowRight className="h-3.5 w-3.5" /></Link>
          </Button>
        }
      />

      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><FileText className="h-5 w-5 text-primary" /> Revision Notes & Study Materials</CardTitle>
          <CardDescription>Downloadable notes and materials for {topicTitle}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-2">
          {materials.length === 0 ? (
            <p className="text-sm text-muted-foreground py-4 text-center">No revision notes have been uploaded for this topic yet.</p>
          ) : (
            materials.map((m) => (
              // A plain row, not a Link: wrapping the whole card in a link to
              // /notes made every material behave as "go to the library", which
              // threw away the topic the student was reading and hid the fact
              // that a downloadable file exists at all.
              <div
                key={m.id}
                className="rounded-lg border transition-colors hover:bg-muted/50"
              >
                <div className="flex items-center justify-between gap-2 p-3">
                <MaterialPreview
                  fileUrl={m.file_url}
                  previewUrl={m.preview_url}
                  pageCount={m.page_count}
                  sourceRange={m.source_range}
                />
                <div className="min-w-0 flex-1 px-3">
                  <p className="font-medium truncate">{m.title}</p>
                  <p className="text-xs text-muted-foreground mt-0.5 capitalize">
                    {m.material_type} · {topicTitle}
                  </p>
                </div>
                <div className="flex items-center gap-2 shrink-0 ml-4">
                  {role === "admin" && (
                    <ContentEditor
                      entityType="material"
                      entityId={m.id}
                      initialTitle={m.title}
                      initialContent={m.content ?? null}
                      onSaved={bumpRevision}
                      trigger={
                        <Button size="sm" variant="ghost" className="gap-1 h-8" onClick={(e) => e.preventDefault()}>
                          <Pencil className="h-3.5 w-3.5" /> Edit
                        </Button>
                      }
                    />
                  )}
                  <Badge
                    variant={m.material_type === "notes" ? "secondary" : "outline"}
                    className="text-[10px] capitalize"
                  >
                    {m.material_type}
                  </Badge>
                  {m.file_url ? (
                    <>
                      <Button size="sm" variant="ghost" className="gap-1 h-8"
                        onClick={async () => {
                          try {
                            await openProtectedFile("study-materials", m.file_url);
                          } catch (e) {
                            toast.error(e?.message ?? "Could not open this file");
                          }
                        }}>
                        <ExternalLink className="h-3.5 w-3.5" /> Open
                      </Button>
                      <Button size="sm" variant="ghost" className="gap-1 h-8"
                        onClick={async () => {
                          try {
                            await openProtectedFile("study-materials", m.file_url, m.title);
                          } catch (e) {
                            toast.error(e?.message ?? "Could not download this file");
                          }
                        }}>
                        <Download className="h-3.5 w-3.5" />
                      </Button>
                    </>
                  ) : m.content ? null : (
                    <Button asChild size="sm" variant="ghost" className="gap-1 h-8">
                      <Link to="/notes">
                        Read <ArrowRight className="h-3.5 w-3.5" />
                      </Link>
                    </Button>
                  )}
                </div>
                </div>
                {/* A material with no file is a note whose text lives in the
                    row. The exam-technique "extras" are exactly that, and
                    before this they were a row whose only action was a "Read"
                    link to the notes library — which does not list their type,
                    so the link led to a page that did not contain them. The
                    text is rendered where the student already is. */}
                {!m.file_url && m.content && (
                  <div
                    className="cm-notes cm-m-inline"
                    dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(materialContentToHtml(String(m.content))) }}
                  />
                )}
              </div>
            ))
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><BookOpen className="h-5 w-5 text-primary" /> Lessons</CardTitle>
          <CardDescription>Structured lessons for {topicTitle}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-2">
          {lessons.length === 0 ? (
            <p className="text-sm text-muted-foreground py-4 text-center">No lessons have been created for this topic yet.</p>
          ) : (
            lessons.map((l) => (
              <Link
                key={l.id}
                to={`/lessons/${l.id}/notes`}
                className="flex items-center justify-between rounded-lg border p-3 hover:bg-muted/50 transition-colors"
              >
                <div className="min-w-0 flex-1">
                  <p className="font-medium truncate">{l.title}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">Lesson · {topicTitle}</p>
                </div>
                <div className="flex items-center gap-2 shrink-0 ml-4">
                  {role === "admin" && (
                    <ContentEditor
                      entityType="lesson"
                      entityId={l.id}
                      initialTitle={l.title}
                      initialContent={l.content ?? null}
                      onSaved={bumpRevision}
                      trigger={
                        <Button size="sm" variant="ghost" className="gap-1 h-8" onClick={(e) => e.preventDefault()}>
                          <Pencil className="h-3.5 w-3.5" /> Edit
                        </Button>
                      }
                    />
                  )}
                  <Badge variant="outline" className="text-[10px]">Notes</Badge>
                  <ArrowRight className="h-4 w-4 text-muted-foreground" />
                </div>
              </Link>
            ))
          )}
        </CardContent>
      </Card>

      {mastery && (
        <Card className={mastery.examReady ? "border-emerald-500/40" : ""}>
          <CardContent className="flex flex-wrap items-center gap-4 p-4">
            <TopicMasteryRing percent={mastery.percent} band={mastery.band} label={`${topicTitle} mastery ${mastery.percent}%`} />
            <div className="min-w-0 flex-1">
              <p className="font-semibold">
                {mastery.examReady ? "Exam-ready" : `${mastery.mastered} of ${mastery.total} objectives mastered`}
              </p>
              <p className="text-xs text-muted-foreground">
                {mastery.examReady
                  ? "Every objective in this topic is mastered. Keep it green with refresh checks."
                  : "Master every objective to turn this topic green — wrong answers come back as Strengthen checks."}
              </p>
            </div>
            <Button asChild variant={mastery.examReady ? "outline" : "default"} size="sm" className="gap-1.5">
              <Link to="/mastery">
                {mastery.examReady ? "Refresh checks" : "Strengthen"} <ArrowRight className="h-3.5 w-3.5" />
              </Link>
            </Button>
          </CardContent>
        </Card>
      )}

      <div className="grid gap-3 sm:grid-cols-3">
        {[
          { label: "Lessons", value: topicLessons, icon: BookOpen, color: accent.text },
          { label: "Notes", value: topicNotesCount, icon: FileText, color: accent.text },
          { label: "Topic Questions", value: quizzes.length, icon: Play, color: accent.text },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="flex items-center gap-3 p-4">
              <s.icon className={`h-5 w-5 ${s.color}`} />
              <div>
                <p className="text-xl font-bold leading-none">{s.value}</p>
                <p className="text-xs text-muted-foreground mt-1">{s.label}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card className="min-w-0">
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><Play className="h-5 w-5 text-primary" /> Topic Questions</CardTitle>
          <CardDescription>Exam-style questions for {topicTitle}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-2">
          {quizzes.length === 0 ? (
            <p className="text-sm text-muted-foreground py-4 text-center">No topic questions have been created for this topic yet.</p>
          ) : (
            quizzes.map((q) => (
              <Link
                key={q.id}
                to={topicQuizPath(subjectMeta.slug, subjectLevel.level.toLowerCase(), topicSlug)}
                className="flex items-center justify-between rounded-lg border p-3 hover:bg-muted/50 transition-colors"
              >
                <div className="min-w-0 flex-1">
                  <p className="font-medium truncate">{q.title}</p>
                  <p className="text-xs text-muted-foreground mt-0.5 capitalize">
                    {(q.exam_type === "ai_bank" ? "AI Bank" : "Quiz")} · {topicTitle}
                  </p>
                </div>
                <div className="flex items-center gap-2 shrink-0 ml-4">
                  <Badge variant="outline" className="text-[10px]">{q.questions?.length ?? "Questions"}</Badge>
                  <ArrowRight className="h-4 w-4 text-muted-foreground" />
                </div>
              </Link>
            ))
          )}
          <Button asChild variant="outline" className="gap-2 mt-3 w-full justify-center">
            <Link to={topicQuizPath(subjectMeta.slug, subjectLevel.level.toLowerCase(), topicSlug)}>
              Browse all topic questions <ArrowRight className="h-4 w-4" />
            </Link>
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

// Per-topic past-paper list.
import { useEffect, useMemo, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { SEOHead } from "@/components/SEOHead";
import { TopicBreadcrumb } from "@/components/TopicBreadcrumb";
import { LEVELS, LEVEL_LABELS, subjectIcon, subjectAccent, type SubjectLevelCode } from "@/lib/subjects";
import {
  topicNotesPath,
  topicQuizPath,
  topicPapersPath,
  slugifyTopicName,
  topicSlugOf,
} from "@/lib/topicUrls";
import { topicHead } from "@/lib/topicSeo";
import { Archive, BookOpen, Play, Clock, ArrowRight, ArrowLeft, FileText, FileCheck, ExternalLink, Sparkles, RotateCcw, Download, Wand2 } from "lucide-react";
import { MarkPaperDialog } from "@/components/MarkPaperDialog";
import { useToast } from "@/hooks/useToast";
import { openProtectedFile, openExternalPaper, ExternalPaperGated } from "@/lib/contentFiles";
import { paperFileName, archivePaperGroup } from "@/lib/pastPaperFiles";
import { relatedTopicPapers } from "@/lib/topicPapers";
import { usePlanAccess, FREE_PREVIEW_LIMIT } from "@/components/PreviewLimit";
import { PreviewBanner } from "@/components/PreviewBanner";
import { useMySubjects } from "@/hooks/useMySubjects";
import { useAuth } from "@/lib/auth";
import { SubjectGate } from "@/components/SubjectGate";

interface TopicPaper {
  id: string;
  title: string;
  year: number;
  session: string | null;
  paper_number: string | null;
  paper_url: string | null;
  mark_scheme_url: string | null;
  source_url: string | null;
  topic_id: string | null;
}

export default function TopicPapers() {
  const { slug: subject, level, topic } = useParams<{
    slug: string;
    level: string;
    topic: string;
  }>();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [subjectMeta, setSubjectMeta] = useState<any>(null);
  const [subjectLevel, setSubjectLevel] = useState<any>(null);
  const [topicTitle, setTopicTitle] = useState<string | null>(null);
  const topicSlug = slugifyTopicName(topic ?? "");
  const [topicId, setTopicId] = useState<string | null>(null);
  const [papers, setPapers] = useState<TopicPaper[]>([]);
  const [levelPapers, setLevelPapers] = useState<TopicPaper[]>([]);
  const [groupFilter, setGroupFilter] = useState("all");
  // Bumped by "Try again" to re-run the load effect.
  const [retryKey, setRetryKey] = useState(0);
  // The row the student tapped “Submit for marking” on — marking is scoped
  // to that paper's own mark scheme.
  const [markPaper, setMarkPaper] = useState<TopicPaper | null>(null);
  const { toast } = useToast();
  const { isPreview, hasPaid } = usePlanAccess();
  const { user } = useAuth();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  // Paper-aware set: the topic's own tagged papers plus every other paper in
  // this subject-level sitting in the same paper group — so a Paper 1 lesson
  // lists Paper 1 papers (with their mark schemes), a mechanics lesson lists
  // mechanics papers, and so on for every paper of every subject and level.
  // Topics with no tagged papers of their own fall back to the whole level.
  const related = useMemo(
    () => relatedTopicPapers(topicId ?? "", papers, levelPapers.length > 0 ? levelPapers : papers),
    [topicId, papers, levelPapers],
  );
  const groupFiltered = groupFilter === "all"
    ? related.papers
    : related.papers.filter((p) => archivePaperGroup(p) === groupFilter);

  // Free-plan limit for this topic's past papers: show the first 2 records
  // (follows the global FREE_PREVIEW_LIMIT policy); paid accounts see all.
  const visiblePapers = hasPaid
    ? groupFiltered
    : isPreview
      ? groupFiltered.slice(0, FREE_PREVIEW_LIMIT)
      : groupFiltered;

  const openPaper = async (url: string) => {
    try {
      await openProtectedFile("past-papers", url);
    } catch (e) {
      toast({ title: "Error", description: e?.message ?? "Unable to open file", variant: "destructive" });
    }
  };

  // Save-to-disk variant of openPaper: same watermarked bytes, but the browser
  // is told to download them (with a sensible filename) instead of previewing.
  const downloadPaper = async (url: string, name: string) => {
    try {
      await openProtectedFile("past-papers", url, name);
    } catch (e) {
      toast({ title: "Error", description: e?.message ?? "Unable to download file", variant: "destructive" });
    }
  };

  // External papers route through serve-external-paper, which enforces the plan
  // and audits the click; a gated rejection becomes an upgrade prompt.
  const openExternal = async (url: string, label?: string) => {
    try {
      await openExternalPaper(url, label);
    } catch (e) {
      if (e instanceof ExternalPaperGated) {
        toast({ title: "Full plan required", description: e.message });
        return;
      }
      toast({ title: "Error", description: e?.message ?? "Unable to open link", variant: "destructive" });
    }
  };

  useEffect(() => {
    let active = true;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        const { data: sub, error: subError } = await supabase.from("subjects").select("*").ilike("slug", subject ?? "").limit(1);
        if (subError) throw subError;
        const subjectRow = sub?.[0] ?? null;
        if (!subjectRow) {
          setError("Subject not found");
          setLoading(false);
          return;
        }
        setSubjectMeta(subjectRow);

        const { data: sl, error: slError } = await supabase.from("subject_levels").select("*").eq("subject_id", subjectRow.id).eq("level", (level ?? "").toUpperCase() as SubjectLevelCode).limit(1);
        if (slError) throw slError;
        const levelRow = sl?.[0] ?? null;
        if (!levelRow) {
          setError("Level not found");
          setLoading(false);
          return;
        }
        setSubjectLevel(levelRow);

        const { data: tps, error: tpsError } = await supabase.from("topics").select("*").eq("subject_level_id", levelRow.id).order("sort_order");
        if (tpsError) throw tpsError;
        const topicList = tps ?? [];
        const topicRow = topicList.find(
          (t) =>
            topicSlugOf(t) === topicSlug ||
            // Last-resort match for URLs minted before slugs were persisted.
            slugifyTopicName(t.name) === topicSlug ||
            t.name.toLowerCase() === (topic ?? "").replace(/-/g, " ").toLowerCase(),
        );
        if (!topicRow) {
          setError("Topic not found on this level");
          setLoading(false);
          return;
        }
        setTopicTitle(topicRow.name);
        setTopicId(topicRow.id);
        setGroupFilter("all");

        if (active && topicRow) {
          const levelTopicIds = topicList.map((t) => t.id);
          const [ownRes, levelRes] = await Promise.all([
            supabase.from("past_papers").select("*").eq("topic_id", topicRow.id).order("year", { ascending: false }),
            supabase.from("past_papers").select("*").in("topic_id", levelTopicIds).order("year", { ascending: false }),
          ]);
          if (ownRes.error) throw ownRes.error;
          if (levelRes.error) throw levelRes.error;
          if (active) {
            setPapers((ownRes.data ?? []) as unknown as TopicPaper[]);
            setLevelPapers((levelRes.data ?? []) as unknown as TopicPaper[]);
          }
        }
      } catch (e) {
        setError(e.message ?? "Failed to load topic past papers");
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => { active = false; };
  }, [subject, level, topic, topicSlug, retryKey]);

  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <div className="h-8 w-8 rounded-full border-primary/30 border animate-spin" />
      </div>
    );
  }
  // "Does this reader still have to pick subjects?" is asked in one place.
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead title={`${topicTitle ?? "Past Papers"} — Clutch Marks`} description="Past papers and mark schemes." path={topicPapersPath(subjectMeta?.slug ?? "", subjectLevel?.level.toLowerCase() ?? "", topicSlug)} />
        <SubjectGate />
      </div>
    );
  }

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-28 rounded-2xl" />
        <Skeleton className="h-64 rounded-2xl" />
      </div>
    );
  }

  // Students only see topics belonging to a subject-level they picked.
  // Anonymous visitors are not enrolled in any subject yet, so they see the
  // topic regardless; signing in and picking it afterwards personalises the
  // view.
  if (!isAdminRole && user && prefsLoaded && topicId && !pickedIds.has(subjectLevel?.id ?? "")) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Past papers not found</CardTitle>
          <CardDescription>You haven't selected this subject yet.</CardDescription>
        </CardHeader>
        <CardContent>
          <Button asChild variant="outline" className="gap-2">
            <Link to={topicNotesPath(subjectMeta?.slug ?? "", subjectLevel?.level.toLowerCase() ?? "", topicSlug)}><ArrowLeft className="h-4 w-4" /> Back to topic</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  if (error || !subjectMeta || !subjectLevel || !topicTitle || !topicId) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>
            {error && !/not found/i.test(error) ? "Couldn't load these past papers" : "Past papers not found"}
          </CardTitle>
          <CardDescription>{error ?? "No past papers have been linked to this topic yet."}</CardDescription>
        </CardHeader>
        <CardContent className="flex flex-wrap gap-2">
          <Button variant="outline" className="gap-2" onClick={() => setRetryKey((k) => k + 1)}>
            <RotateCcw className="h-4 w-4" /> Try again
          </Button>
          <Button asChild variant="outline" className="gap-2">
            <Link to={topicNotesPath(subjectMeta?.slug ?? "", subjectLevel?.level.toLowerCase() ?? "", topicSlug)}><ArrowLeft className="h-4 w-4" /> Back to topic</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  const Icon = subjectIcon(subjectMeta.icon);
  const accent = subjectAccent(subjectMeta.color);
  const levelCode = subjectLevel.level as SubjectLevelCode;
  const topicSeo = topicHead(
    {
      subjectSlug: subjectMeta.slug,
      subjectName: subjectMeta.name,
      level: subjectLevel.level,
      topicSlug,
      topicName: topicTitle,
    },
    "papers",
  );

  return (
    <div className="space-y-6">
      <PreviewBanner />
      {/* Title, description, canonical and JSON-LD come from topicSeo, which is
          also what the build-time prerenderer writes into this URL's static HTML
          — so the crawler's head and the browser's head cannot disagree. */}
      <SEOHead {...topicSeo} />

      <TopicBreadcrumb
        subjectName={subjectMeta.name}
        levelLabel={LEVEL_LABELS[levelCode]}
        topicName={topicTitle}
        currentLabel="Past Papers & Mark Schemes"
        subjectSlug={subjectMeta.slug}
        level={subjectLevel.level.toLowerCase()}
        topicSlug={topicSlug}
      />

      <div className={`glass-card p-6 flex flex-wrap items-center gap-4 ${accent.border}`}>
        <div className={`flex h-14 w-14 items-center justify-center rounded-2xl border ${accent.border} ${accent.bg} ${accent.text}`}>
          <Icon className="h-7 w-7" />
        </div>
        <div className="flex-1 min-w-[200px]">
          <h1 className="text-2xl font-bold tracking-tight">{topicTitle}</h1>
          <div className="mt-1 flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
            <Badge variant="secondary">{subjectMeta.name}</Badge>
            <Badge variant="outline">{LEVEL_LABELS[levelCode]}</Badge>
          </div>
          <p className="mt-2 text-sm text-muted-foreground">
            {groupFiltered.length} past paper{groupFiltered.length === 1 ? "" : "s"} linked to {topicTitle} in {subjectMeta.name} {LEVEL_LABELS[levelCode]}.
            {related.filtered && related.groups.length > 0 && (
              <span> Showing {related.groups.join(", ")} papers for this topic.</span>
            )}
            {isPreview && !hasPaid && (
              <span className="text-xs text-primary"> ({visiblePapers.length} of {groupFiltered.length} shown — full archive on the full plan)</span>
            )}
            Use these to practise under real exam conditions and check your answers against the mark schemes.
          </p>
        </div>
        <div className="flex gap-2">
          <Button asChild variant="outline" size="sm" className="gap-2">
            <Link to={`/practice?level=${subjectLevel.id}&topic=${topicId}`}>Practise mistakes <ArrowRight className="h-3.5 w-3.5" /></Link>
          </Button>
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-3">
        {[
          { label: "Past Papers", value: groupFiltered.length, icon: Archive, color: accent.text },
          { label: "Notes", value: 0, icon: BookOpen, color: accent.text },
          { label: "Topic Questions", value: 0, icon: Play, color: accent.text },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="flex items-center gap-3 p-4">
              <s.icon className={`h-5 w-5 ${s.color}`} />
              <div>
                <p className="text-xl font-bold leading-none">{s.value}</p>
                <p className="text-xs text-muted-foreground mt-1">{s.label}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2"><Archive className="h-5 w-5 text-primary" /> Past Papers & Mark Schemes for {topicTitle}</CardTitle>
          <CardDescription>Organised by year, session and paper number</CardDescription>
          {related.groups.length > 1 && (
            <div className="flex flex-wrap gap-2 px-6">
              <Button
                size="sm"
                variant={groupFilter === "all" ? "default" : "outline"}
                onClick={() => setGroupFilter("all")}
              >
                All ({related.papers.length})
              </Button>
              {related.groups.map((g) => (
                <Button
                  key={g}
                  size="sm"
                  variant={groupFilter === g ? "default" : "outline"}
                  onClick={() => setGroupFilter(groupFilter === g ? "all" : g)}
                >
                  {g} ({related.papers.filter((p) => archivePaperGroup(p) === g).length})
                </Button>
              ))}
            </div>
          )}
        </CardHeader>
        <CardContent className="space-y-2">
          {visiblePapers.length === 0 ? (
            <p className="text-sm text-muted-foreground py-4 text-center">No past papers have been linked to this topic yet.</p>
          ) : (
            visiblePapers.map((p) => (
              <div
                key={p.id}
                className="flex flex-col gap-3 rounded-lg border p-3 transition-colors hover:bg-muted/50 sm:flex-row sm:items-center sm:justify-between"
              >
                <div className="min-w-0 flex-1">
                  <p className="font-medium">{p.title}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {p.year}
                    {p.session ? ` · ${p.session}` : ""}
                    {p.paper_number ? ` · ${p.paper_number}` : ""}
                  </p>
                </div>
                <div className="flex flex-wrap items-center gap-2 sm:shrink-0 sm:justify-end">
                  {p.paper_url && (
                    <>
                      <Button size="sm" variant="outline" className="gap-1.5 text-xs" onClick={() => openPaper(p.paper_url!)}>
                        <FileText className="h-3.5 w-3.5" /> Paper
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        className="gap-1.5 text-xs"
                        aria-label={`Download ${p.title} question paper`}
                        title="Download question paper"
                        onClick={() => downloadPaper(p.paper_url!, paperFileName(p.title, "paper"))}
                      >
                        <Download className="h-3.5 w-3.5" /> Download
                      </Button>
                    </>
                  )}
                  {p.mark_scheme_url && (
                    <>
                      <Button size="sm" variant="outline" className="gap-1.5 text-xs text-green-600 border-green-200 hover:bg-green-50" onClick={() => openPaper(p.mark_scheme_url!)}>
                        <FileCheck className="h-3.5 w-3.5" /> Mark Scheme
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        className="gap-1.5 text-xs text-green-600"
                        aria-label={`Download ${p.title} mark scheme`}
                        title="Download mark scheme"
                        onClick={() => downloadPaper(p.mark_scheme_url!, paperFileName(p.title, "mark-scheme"))}
                      >
                        <Download className="h-3.5 w-3.5" /> Download
                      </Button>
                    </>
                  )}
                  {!p.paper_url && !p.mark_scheme_url && (
                    <Badge variant="secondary" className="gap-1.5 text-[10px] text-muted-foreground">
                      <Clock className="h-3 w-3" /> Files coming soon
                    </Badge>
                  )}
                  <Button
                    size="sm"
                    variant="outline"
                    className="gap-1.5 text-xs"
                    title="Submit your solved script — marked against this paper's mark scheme"
                    onClick={() => setMarkPaper(p)}
                  >
                    <Wand2 className="h-3.5 w-3.5" /> Submit for marking
                  </Button>
                  {p.source_url && (
                    <Button
                      size="sm"
                      variant="outline"
                      className="gap-1.5 text-xs"
                      onClick={() => openExternal(p.source_url!, p.title)}
                    >
                      Official paper <ExternalLink className="h-3.5 w-3.5" />
                    </Button>
                  )}
                </div>
              </div>
            ))
          )}
          {!hasPaid && isPreview && groupFiltered.length > visiblePapers.length && (
            <div className="mt-4 flex justify-between items-center border-t pt-4">
              <p className="text-sm text-muted-foreground">{groupFiltered.length - visiblePapers.length} more paper{groupFiltered.length - visiblePapers.length === 1 ? "" : "s"} available on the full plan.</p>
              <Button asChild variant="outline" size="sm">
                <Link to="/pricing"><Sparkles className="h-3.5 w-3.5 mr-2" /> View plans</Link>
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      <div className="grid gap-3 sm:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2"><BookOpen className="h-5 w-5 text-primary" /> Revision Notes</CardTitle>
            <CardDescription>Notes linked to {topicTitle}</CardDescription>
          </CardHeader>
          <CardContent className="space-y-2">
            <p className="text-sm text-muted-foreground py-4 text-center">No revision notes have been uploaded for this topic yet.</p>
            <Button asChild variant="outline" className="gap-2 w-full justify-center">
              <Link to={topicNotesPath(subjectMeta.slug, subjectLevel.level.toLowerCase(), topicSlug)}>
                Browse notes <ArrowRight className="h-4 w-4" />
              </Link>
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2"><Play className="h-5 w-5 text-primary" /> Topic Questions</CardTitle>
            <CardDescription>Questions linked to {topicTitle}</CardDescription>
          </CardHeader>
          <CardContent className="space-y-2">
            <p className="text-sm text-muted-foreground py-4 text-center">No topic questions have been created for this topic yet.</p>
            <Button asChild variant="outline" className="gap-2 w-full justify-center">
              <Link to={topicQuizPath(subjectMeta.slug, subjectLevel.level.toLowerCase(), topicSlug)}>
                Browse questions <ArrowRight className="h-4 w-4" />
              </Link>
            </Button>
          </CardContent>
        </Card>
      </div>

      {/* Submit-for-marking scoped to the tapped paper's own mark scheme. */}
      <MarkPaperDialog
        paper={markPaper}
        open={markPaper !== null}
        onOpenChange={(o) => { if (!o) setMarkPaper(null); }}
      />
    </div>
  );
}

// Per-topic quiz page with mark-scheme explanations.
import { useEffect, useMemo, useState } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Skeleton } from "@/components/ui/skeleton";
import { SEOHead } from "@/components/SEOHead";
import { TopicBreadcrumb } from "@/components/TopicBreadcrumb";
import { useToast } from "@/hooks/useToast";
import { BookmarkButton } from "@/components/BookmarkButton";
import { ManuscriptHead, ManuscriptQuestion } from "@/components/StudyManuscript";
import { FeedbackNudge } from "@/components/FeedbackNudge";
import { LEVELS, LEVEL_LABELS, subjectIcon, subjectAccent, type SubjectLevelCode } from "@/lib/subjects";
import {
  topicNotesPath,
  topicQuizPath,
  slugifyTopicName,
  topicSlugOf,
} from "@/lib/topicUrls";
import { topicDisplayName, topicHead } from "@/lib/topicSeo";
import {
  ArrowRight,
  ArrowLeft,
  Bookmark,
  Play,
  RotateCcw,
  FileDown,
  ListChecks,
} from "lucide-react";
import { useMySubjects } from "@/hooks/useMySubjects";
import { SubjectGate } from "@/components/SubjectGate";
import { exportQuizResultToPdf, gradeBand } from "@/lib/pdfExport";

interface TopicQuestion {
  id: string;
  question_text: string;
  options: string[];
  difficulty: string;
  quiz_title: string;
  quiz_id: string;
  is_ai_generated: boolean;
  bookmarked: boolean;
  last_correct: boolean | null;
}

interface GradeRow {
  question_id: string;
  selected: number;
  correct_option: number;
  explanation: string | null;
  options: string[];
}

export default function TopicQuiz() {
  const { slug: subject, level, topic } = useParams<{
    slug: string;
    level: string;
    topic: string;
  }>();
  const { toast } = useToast();
  const navigate = useNavigate();

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [subjectMeta, setSubjectMeta] = useState<any>(null);
  const [subjectLevel, setSubjectLevel] = useState<any>(null);
  const [topicTitle, setTopicTitle] = useState<string | null>(null);
  const topicSlug = useMemo(() => slugifyTopicName(topic ?? ""), [topic]);
  const [topicId, setTopicId] = useState<string | null>(null);
  const [questions, setQuestions] = useState<TopicQuestion[]>([]);
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [selected, setSelected] = useState<string | null>(null);
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState<{ correct: number; total: number } | null>(null);
  const [results, setResults] = useState<GradeRow[]>([]);
  const [bookmarkedQuestions, setBookmarkedQuestions] = useState<TopicQuestion[]>([]);
  // After marking: the whole paper, or only the ones to redo.
  const [reviewOnly, setReviewOnly] = useState(false);
  const [exporting, setExporting] = useState(false);
  // Bumped by "Try again" to re-run the load effect.
  const [retryKey, setRetryKey] = useState(0);

  const { user } = useAuth();
  const { pickedIds, loaded: prefsLoaded, isAdmin: isAdminRole, needsSubjectPick } = useMySubjects();

  // The stored name wins verbatim: topicSeo.titleFor writes the static head from
  // the same string, so title-casing it here would give this URL two titles.
  const topicLabel = useMemo(() => topicDisplayName(topicTitle, topic ?? ""), [topicTitle, topic]);

  useEffect(() => {
    let active = true;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        const { data: sub, error: subError } = await supabase.from("subjects").select("*").ilike("slug", subject ?? "").limit(1);
        if (subError) throw subError;
        const subjectRow = sub?.[0] ?? null;
        if (!subjectRow) {
          setError("Subject not found");
          setLoading(false);
          return;
        }
        setSubjectMeta(subjectRow);

        const { data: sl, error: slError } = await supabase.from("subject_levels").select("*").eq("subject_id", subjectRow.id).eq("level", (level ?? "").toUpperCase() as SubjectLevelCode).limit(1);
        if (slError) throw slError;
        const levelRow = sl?.[0] ?? null;
        if (!levelRow) {
          setError("Level not found");
          setLoading(false);
          return;
        }
        setSubjectLevel(levelRow);

        const { data: tps, error: tpsError } = await supabase.from("topics").select("*").eq("subject_level_id", levelRow.id).order("sort_order");
        if (tpsError) throw tpsError;
        const topicList = tps ?? [];
        const topicRow = topicList.find(
          (t) =>
            topicSlugOf(t) === topicSlug ||
            // Last-resort match for URLs minted before slugs were persisted.
            slugifyTopicName(t.name) === topicSlug ||
            t.name.toLowerCase() === (topic ?? "").replace(/-/g, " ").toLowerCase(),
        );
        if (!topicRow) {
          setError("Topic not found on this level");
          setLoading(false);
          return;
        }
        setTopicTitle(topicRow.name);
        setTopicId(topicRow.id);

        if (active) {
          const { data, error: questionsError } = await supabase.rpc("browse_questions", {
            _topic_id: topicRow.id,
            _subject_level_id: levelRow.id,
            _difficulty: null,
            _exam_type: null,
            _search: null,
            _limit: 200,
            _offset: 0,
          });
          if (questionsError) throw questionsError;
          if (active && data) {
            setQuestions((data as unknown as TopicQuestion[]) ?? []);
            setBookmarkedQuestions((data as unknown as TopicQuestion[]).filter((q) => q.bookmarked));
          }
        }
      } catch (e) {
        setError(e.message ?? "Failed to load topic questions");
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => { active = false; };
  }, [subject, level, topic, topicSlug, retryKey]);

  const topicSourceLink = useMemo(() => {
    if (!subjectMeta || !subjectLevel) return "#";
    return topicNotesPath(subjectMeta.slug, subjectLevel.level.toLowerCase(), topicSlug);
  }, [subjectMeta, subjectLevel, topicSlug]);

  // One row per question, whatever happened to it. The review, the counters and
  // the exported PDF all read from this derivation, so they cannot disagree.
  const reviewRows = useMemo(() => {
    return questions.map((question, ordinal) => {
      const result = results.find((r) => r.question_id === question.id);
      const raw = answers[question.id];
      const picked = typeof raw === "number" ? raw : null;
      const status: "correct" | "incorrect" | "unanswered" = picked === null
        ? "unanswered"
        : result && picked === result.correct_option
          ? "correct"
          : "incorrect";
      return { ordinal, question, result, picked, status };
    });
  }, [questions, results, answers]);

  const counts = useMemo(() => {
    return reviewRows.reduce(
      (acc, row) => {
        acc[row.status] += 1;
        return acc;
      },
      { correct: 0, incorrect: 0, unanswered: 0 },
    );
  }, [reviewRows]);

  const toggleBookmark = async (questionId: string, next: boolean) => {
    setQuestions((prev) => prev.map((q) => (q.id === questionId ? { ...q, bookmarked: next } : q)));
    setBookmarkedQuestions((prev) => {
      if (next) {
        const q = questions.find((x) => x.id === questionId);
        return q && !prev.find((x) => x.id === questionId) ? [...prev, q] : prev;
      }
      return prev.filter((q) => q.id !== questionId);
    });
  };

  const selectAnswer = (questionId: string, optionIndex: number) => {
    if (submitted) return;
    setAnswers((prev) => ({ ...prev, [questionId]: optionIndex }));
    setSelected(questionId);
  };

  const submit = async () => {
    if (!user || !topicId || !subjectLevel) return;
    const unanswered = questions.filter((q) => answers[q.id] === undefined).length;
    if (unanswered > 0) {
      toast({ title: "Not ready", description: `Answer ${unanswered} more question${unanswered > 1 ? "s" : ""} before submitting.`, variant: "destructive" });
      return;
    }

    try {
      const { data, error: rpcError } = await supabase.rpc("grade_quiz", {
        _quiz_id: questions.length > 0 ? questions[0].quiz_id : undefined,
        _answers: Object.fromEntries(questions.map((q) => [q.id, answers[q.id] ?? -1])),
      });
      if (rpcError) throw rpcError;

      const resultsData = (data as any)?.results ?? questions.map((q) => ({
        question_id: q.id,
        selected: answers[q.id] ?? -1,
        correct_option: 0,
        explanation: null,
        options: (q.options as string[]) ?? [],
      }));

      setResults((resultsData as GradeRow[]) ?? []);
      const correctCount = resultsData.filter((r) => (r as any).selected === (r as any).correct_option).length;
      setScore({ correct: correctCount, total: questions.length });
      setSubmitted(true);
      setReviewOnly(false);
      toast({ title: "Answers submitted", description: `You got ${correctCount}/${questions.length} correct.`, variant: "default" });
    } catch (e) {
      toast({ title: "Submission failed", description: e.message, variant: "destructive" });
    }
  };

  const reset = () => {
    setAnswers({});
    setSelected(null);
    setSubmitted(false);
    setScore(null);
    setResults([]);
    setReviewOnly(false);
  };

  if (!isAdminRole && !prefsLoaded) {
    return (
      <div className="flex justify-center py-24">
        <div className="h-8 w-8 rounded-full border-primary/30 border animate-spin" />
      </div>
    );
  }
  // "Does this reader still have to pick subjects?" is asked in one place.
  if (needsSubjectPick) {
    return (
      <div className="space-y-6">
        <SEOHead title={`${topicLabel} — Topic Questions | Clutch Marks`} description="Exam-style topic questions with instant marking." path={topicQuizPath(subjectMeta?.slug ?? "", subjectLevel?.level.toLowerCase() ?? "", topicSlug)} />
        <SubjectGate />
      </div>
    );
  }

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-28 rounded-2xl" />
        <Skeleton className="h-64 rounded-2xl" />
      </div>
    );
  }

  // Students only see topics belonging to a subject-level they picked.
  // Anonymous visitors are not enrolled in any subject yet, so they see the
  // topic regardless; signing in and picking it afterwards personalises the
  // view.
  if (!isAdminRole && user && prefsLoaded && topicId && !pickedIds.has(subjectLevel?.id ?? "")) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Topic questions not found</CardTitle>
          <CardDescription>You haven't selected this subject yet.</CardDescription>
        </CardHeader>
        <CardContent>
          <Button asChild variant="outline" className="gap-2">
            <Link to={topicNotesPath(subjectMeta?.slug ?? "", subjectLevel?.level.toLowerCase() ?? "", topicSlug)}><ArrowLeft className="h-4 w-4" /> Back to topic</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  if (error || !subjectMeta || !subjectLevel || !topicTitle || !topicId) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>
            {error && !/not found/i.test(error) ? "Couldn't load these questions" : "Topic questions not found"}
          </CardTitle>
          <CardDescription>{error ?? "No questions have been added for this topic yet."}</CardDescription>
        </CardHeader>
        <CardContent className="flex flex-wrap gap-2">
          <Button variant="outline" className="gap-2" onClick={() => setRetryKey((k) => k + 1)}>
            <RotateCcw className="h-4 w-4" /> Try again
          </Button>
          <Button asChild variant="outline" className="gap-2">
            <Link to={topicNotesPath(subjectMeta?.slug ?? "", subjectLevel?.level.toLowerCase() ?? "", topicSlug)}><ArrowLeft className="h-4 w-4" /> Back to topic</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  const Icon = subjectIcon(subjectMeta.icon);
  const accent = subjectAccent(subjectMeta.color);
  const levelCode = subjectLevel.level as SubjectLevelCode;
  const topicSeo = topicHead(
    {
      subjectSlug: subjectMeta.slug,
      subjectName: subjectMeta.name,
      level: subjectLevel.level,
      topicSlug,
      topicName: topicLabel,
    },
    "quiz",
  );

  const topicQuestions = questions.length;
  const percent = (score?.correct ?? 0) / Math.max(1, score?.total ?? 1) * 100;
  const visibleRows = reviewOnly
    ? reviewRows.filter((row) => row.status !== "correct")
    : reviewRows;

  const downloadResult = async () => {
    setExporting(true);
    try {
      await exportQuizResultToPdf({
        quizTitle: `${topicLabel} — topic questions`,
        topicName: topicLabel,
        subject: subjectMeta.name,
        level: LEVEL_LABELS[levelCode],
        correct: score?.correct ?? 0,
        total: score?.total ?? questions.length,
        questions: reviewRows.map((row) => ({
          question: row.question.question_text,
          options: Array.isArray(row.question.options) ? row.question.options : [],
          selected: row.picked,
          // After a successful grade every question has a result row; -1 is only
          // a fallback so a missing row cannot be misread as "correct".
          correct_option: row.result?.correct_option ?? -1,
          explanation: row.result?.explanation ?? null,
        })),
        identity: { owner: user?.email ?? null },
      });
    } catch (e) {
      toast({ title: "Couldn't build the PDF", description: e?.message ?? "Please try again.", variant: "destructive" });
    } finally {
      setExporting(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Title, description, canonical and JSON-LD come from topicSeo, which is
          also what the build-time prerenderer writes into this URL's static HTML
          — so the crawler's head and the browser's head cannot disagree. */}
      <SEOHead {...topicSeo} />

      <TopicBreadcrumb
        subjectName={subjectMeta.name}
        levelLabel={LEVEL_LABELS[levelCode]}
        topicName={topicLabel}
        currentLabel="Topic Questions"
        subjectSlug={subjectMeta.slug}
        level={subjectLevel.level.toLowerCase()}
        topicSlug={topicSlug}
      />

      <ManuscriptHead
        eyebrow={`${subjectMeta.name} · ${LEVEL_LABELS[levelCode]}`}
        title={topicLabel}
        lede={`${topicQuestions} exam-style question${topicQuestions === 1 ? "" : "s"} for ${topicLabel}. Answer all the questions, submit, and review the marking and explanations.`}
        actions={
          <Button asChild variant="outline" size="sm" className="gap-2">
            <Link to={`/practice?level=${subjectLevel.id}&topic=${topicId}`}>Practise mistakes <ArrowRight className="h-3.5 w-3.5" /></Link>
          </Button>
        }
      />

      <div className="grid gap-3 sm:grid-cols-2">
        {[
          { label: "Questions", value: topicQuestions, icon: Play, color: accent.text },
          { label: "Bookmarked", value: bookmarkedQuestions.length, icon: Bookmark, color: accent.text },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="flex items-center gap-3 p-4">
              <s.icon className={`h-5 w-5 ${s.color}`} />
              <div>
                <p className="text-xl font-bold leading-none">{s.value}</p>
                <p className="text-xs text-muted-foreground mt-1">{s.label}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card>
        <CardContent className="p-4">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <h2 className="text-lg font-semibold">{topicLabel} questions</h2>
              <p className="text-sm text-muted-foreground">
                {submitted
                  ? `${counts.correct} correct · ${counts.incorrect} incorrect${counts.unanswered ? ` · ${counts.unanswered} blank` : ""}`
                  : `${questions.length} question${questions.length === 1 ? "" : "s"} · tap each to answer`}
              </p>
            </div>
            {/* Marking a quiz records an attempt against an account, so a
                signed-out reader gets a sign-in prompt instead of a button that
                silently does nothing (submit() returns early without a user). */}
            {!submitted && user && (
              <Button
                size="lg"
                className="bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground"
                onClick={submit}
                disabled={questions.length === 0}
              >
                {questions.length === 0 ? "No questions yet" : "Submit answers"}
              </Button>
            )}
            {!submitted && !user && questions.length > 0 && (
              <Button
                asChild
                size="lg"
                className="bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground"
              >
                <Link to="/auth">Sign in to be marked</Link>
              </Button>
            )}
            {submitted && questions.length > 0 && (
              <div className="flex flex-wrap items-center gap-3">
                <div className="text-center">
                  <p className="font-mono text-3xl font-bold neon-text">{score?.correct ?? 0}</p>
                  <p className="text-sm text-muted-foreground">{score?.total ?? 0} questions</p>
                </div>
                <Badge variant="secondary">{percent.toFixed(0)}% · {gradeBand(percent)}</Badge>
                <Button
                  variant={reviewOnly ? "default" : "outline"}
                  className="gap-2"
                  aria-pressed={reviewOnly}
                  onClick={() => setReviewOnly((v) => !v)}
                >
                  <ListChecks className="h-4 w-4" />
                  {reviewOnly ? "Showing what to review" : "Only what to review"}
                </Button>
                <Button variant="outline" className="gap-2" onClick={downloadResult} disabled={exporting}>
                  <FileDown className="h-4 w-4" /> {exporting ? "Building PDF…" : "Download result"}
                </Button>
                <Button variant="outline" className="gap-2" onClick={reset}>
                  <ArrowRight className="h-4 w-4" /> Try again
                </Button>
              </div>
            )}
          </div>
          {submitted && questions.length > 0 && (
            <>
              <Progress
                value={percent}
                className="mt-4 h-2"
              />
              <div className="mt-3">
                <FeedbackNudge tool="quiz" toolLabel={`${topicLabel} quiz`} />
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {submitted && reviewOnly && visibleRows.length === 0 && (
        <Card>
          <CardContent className="py-8 text-center text-sm text-muted-foreground">
            Nothing to review — every question was answered correctly.
          </CardContent>
        </Card>
      )}

      <div className="space-y-4">
        {visibleRows.map(({ ordinal, question, result, picked }) => (
          <ManuscriptQuestion
            key={question.id}
            /* The ordinal is the position on the full paper, so filtering
               the list does not renumber the questions. */
            eyebrow={`Question ${ordinal + 1} · ${question.difficulty ?? topicLabel}`}
            question={question.question_text}
            options={question.options as string[]}
            selected={picked ?? null}
            correctOption={result ? result.correct_option : null}
            disabled={submitted}
            onSelect={(i) => selectAnswer(question.id, i)}
            explanation={result?.explanation ?? null}
            actions={
              <BookmarkButton
                questionId={question.id}
                bookmarked={question.bookmarked}
                onChange={(next) => toggleBookmark(question.id, next)}
              />
            }
          />
        ))}
      </div>
    </div>
  );
}

// Publish announcements.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Plus, Trash2 } from "lucide-react";
import { useToast } from "@/hooks/useToast";
import { format } from "date-fns";
import { contentSaveError } from "@/lib/contentGuards";
import type { Tables } from "@/integrations/supabase/types";

export default function AdminAnnouncements() {
  const { toast } = useToast();
  const [announcements, setAnnouncements] = useState<Tables<"announcements">[]>([]);
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  const load = () =>
    supabase
      .from("announcements")
      .select("*")
      .order("published_at", { ascending: false })
      .then(({ data, error }) => {
        if (error) {
          toast({ title: "Could not load announcements", description: error.message, variant: "destructive" });
          return;
        }
        setAnnouncements(data ?? []);
      });

  useEffect(() => { load(); }, []);

  const save = async () => {
    const { error } = await supabase.from("announcements").insert({ title, content });
    // A refused post used to clear the form and toast "Posted" — the
    // announcement was simply never there.
    if (error) {
      toast(contentSaveError("Could not post the announcement", error.message));
      return;
    }
    toast({ title: "Posted" });
    setOpen(false); setTitle(""); setContent(""); load();
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div><h1 className="text-2xl font-bold tracking-tight">Announcements</h1><p className="text-muted-foreground">Post updates</p></div>
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild><Button className="gap-2"><Plus className="h-4 w-4" /> Post</Button></DialogTrigger>
          <DialogContent>
            <DialogHeader><DialogTitle>New Announcement</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} /></div>
              <div><Label>Content</Label><Textarea value={content} onChange={(e) => setContent(e.target.value)} /></div>
              <Button onClick={save} className="w-full">Post</Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
      <div className="space-y-3">
        {announcements.map((a) => (
          <Card key={a.id}>
            <CardContent className="flex items-center justify-between p-4">
              <div>
                <p className="font-medium">{a.title}</p>
                <p className="text-xs text-muted-foreground">{format(new Date(a.published_at), "PPP")}</p>
              </div>
              <Button size="icon" variant="ghost" aria-label={`Delete ${a.title}`} title={`Delete ${a.title}`} onClick={async () => { await supabase.from("announcements").delete().eq("id", a.id); load(); }}><Trash2 className="h-4 w-4 text-destructive" /></Button>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

// Manage flashcard decks.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Plus, Pencil, Trash2, ChevronDown, ChevronUp, Layers } from "lucide-react";
import { useToast } from "@/hooks/useToast";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";
import { contentSaveError } from "@/lib/contentGuards";

type Topic = { id: string; name: string };
type FlashcardSet = {
  id: string;
  title: string;
  description: string | null;
  topic_id: string | null;
  topics?: { name: string } | null;
};
type Flashcard = { id: string; set_id: string; front: string; back: string; sort_order: number };

export default function AdminFlashcards() {
  const { toast } = useToast();
  const [sets, setSets] = useState<FlashcardSet[]>([]);
  const [topics, setTopics] = useState<Topic[]>([]);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<FlashcardSet | null>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [topicId, setTopicId] = useState<string>("");
  const [expandedSet, setExpandedSet] = useState<string | null>(null);
  const [cards, setCards] = useState<Flashcard[]>([]);
  const [cardFront, setCardFront] = useState("");
  const [cardBack, setCardBack] = useState("");
  const [editingCard, setEditingCard] = useState<Flashcard | null>(null);
  const { failure, report, clear } = useLoadFailure("flashcard sets");

  const load = async () => {
    clear();
    const [setsRes, topicsRes] = await Promise.all([
      supabase.from("flashcard_sets").select("*, topics(name)").order("created_at", { ascending: false }),
      supabase.from("topics").select("*").order("sort_order"),
    ]);
    // `?? []` on a failed request rendered "No flashcard sets yet" over a console
    // that actually holds data.
    const error = setsRes.error ?? topicsRes.error;
    if (error) {
      report(error);
      setSets([]);
      setTopics([]);
      return;
    }
    setSets(setsRes.data ?? []);
    setTopics(topicsRes.data ?? []);
  };

  useEffect(() => { load(); }, []);

  const loadCards = async (setId: string) => {
    const { data, error } = await supabase.from("flashcards").select("*").eq("set_id", setId).order("sort_order");
    // A failed read looked like a deck that has no cards.
    if (error) {
      report(error);
      setCards([]);
      return;
    }
    setCards(data ?? []);
  };

  const toggleExpand = (setId: string) => {
    if (expandedSet === setId) {
      setExpandedSet(null);
      setCards([]);
    } else {
      setExpandedSet(setId);
      loadCards(setId);
    }
  };

  const saveSet = async () => {
    const payload = {
      title,
      description: description || null,
      topic_id: topicId || null,
    };
    const { error } = editing
      ? await supabase.from("flashcard_sets").update(payload).eq("id", editing.id)
      : await supabase.from("flashcard_sets").insert(payload);
    // The dialog used to close and toast "Set created" for a refused write,
    // leaving the admin with an empty list and no idea why.
    if (error) {
      toast(contentSaveError("Could not save the set", error.message));
      return;
    }
    resetForm();
    load();
    toast({ title: editing ? "Set updated" : "Set created" });
  };

  const deleteSet = async (id: string) => {
    await supabase.from("flashcard_sets").delete().eq("id", id);
    if (expandedSet === id) setExpandedSet(null);
    load();
    toast({ title: "Set deleted" });
  };

  const editSet = (s: FlashcardSet) => {
    setEditing(s);
    setTitle(s.title);
    setDescription(s.description ?? "");
    setTopicId(s.topic_id ?? "");
    setOpen(true);
  };

  const resetForm = () => {
    setOpen(false);
    setEditing(null);
    setTitle("");
    setDescription("");
    setTopicId("");
  };

  const saveCard = async () => {
    if (!expandedSet) return;
    const payload = { set_id: expandedSet, front: cardFront, back: cardBack, sort_order: cards.length };
    const { error } = editingCard
      ? await supabase.from("flashcards").update({ front: cardFront, back: cardBack }).eq("id", editingCard.id)
      : await supabase.from("flashcards").insert(payload);
    // Clearing the form on a refused write threw away what the admin had typed.
    if (error) {
      toast(contentSaveError("Could not save the card", error.message));
      return;
    }
    setCardFront("");
    setCardBack("");
    setEditingCard(null);
    loadCards(expandedSet);
    toast({ title: editingCard ? "Card updated" : "Card added" });
  };

  const deleteCard = async (id: string) => {
    await supabase.from("flashcards").delete().eq("id", id);
    if (expandedSet) loadCards(expandedSet);
    toast({ title: "Card deleted" });
  };

  const startEditCard = (c: Flashcard) => {
    setEditingCard(c);
    setCardFront(c.front);
    setCardBack(c.back);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Manage Flashcard Sets</h1>
          <p className="text-muted-foreground text-sm">Create and manage flashcard sets for student revision</p>
        </div>
        <Dialog open={open} onOpenChange={(v) => { if (!v) resetForm(); else setOpen(true); }}>
          <DialogTrigger asChild>
            <Button className="gap-2"><Plus className="h-4 w-4" /> New Set</Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader><DialogTitle>{editing ? "Edit" : "Create"} Flashcard Set</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Marketing Mix" /></div>
              <div><Label>Description</Label><Textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Optional description" /></div>
              <div>
                <Label>Topic</Label>
                <Select value={topicId} onValueChange={setTopicId}>
                  <SelectTrigger><SelectValue placeholder="Select topic (optional)" /></SelectTrigger>
                  <SelectContent>
                    {topics.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <Button onClick={saveSet} disabled={!title.trim()} className="w-full">{editing ? "Update" : "Create"} Set</Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      {failure && <QueryError message={failure} onRetry={load} />}

      {sets.length === 0 && (
        <Card className="border-dashed"><CardContent className="py-12 text-center text-muted-foreground"><Layers className="mx-auto h-10 w-10 mb-3 opacity-40" />No flashcard sets yet. Create one to get started.</CardContent></Card>
      )}

      <div className="space-y-3">
        {sets.map((s) => (
          <Card key={s.id} className="overflow-hidden">
            <div className="flex items-center justify-between p-4 cursor-pointer hover:bg-muted/30 transition-colors" onClick={() => toggleExpand(s.id)}>
              <div className="flex flex-wrap items-center gap-x-3 gap-y-1 min-w-0">
                <Layers className="h-5 w-5 text-primary shrink-0" />
                <div className="min-w-0">
                  <p className="font-semibold text-foreground truncate">{s.title}</p>
                  {s.description && <p className="text-xs text-muted-foreground truncate">{s.description}</p>}
                </div>
                {s.topics?.name && <Badge variant="secondary" className="shrink-0 max-w-full">{s.topics.name}</Badge>}
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <Button variant="ghost" size="icon" aria-label={`Edit ${s.title}`} title={`Edit ${s.title}`} onClick={(e) => { e.stopPropagation(); editSet(s); }}><Pencil className="h-4 w-4" /></Button>
                <Button variant="ghost" size="icon" aria-label={`Delete ${s.title}`} title={`Delete ${s.title}`} onClick={(e) => { e.stopPropagation(); deleteSet(s.id); }}><Trash2 className="h-4 w-4 text-destructive" /></Button>
                {expandedSet === s.id ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
              </div>
            </div>

            {expandedSet === s.id && (
              <div className="border-t bg-muted/10 p-4 space-y-4">
                <div className="flex flex-wrap gap-2 items-end">
                  <div className="flex-1 min-w-[9rem]"><Label className="text-xs">Front</Label><Input value={cardFront} onChange={(e) => setCardFront(e.target.value)} placeholder="Question / term" /></div>
                  <div className="flex-1 min-w-[9rem]"><Label className="text-xs">Back</Label><Input value={cardBack} onChange={(e) => setCardBack(e.target.value)} placeholder="Answer / definition" /></div>
                  <div className="ml-auto flex gap-2">
                    <Button onClick={saveCard} disabled={!cardFront.trim() || !cardBack.trim()} size="sm">{editingCard ? "Update" : "Add"}</Button>
                    {editingCard && <Button variant="ghost" size="sm" onClick={() => { setEditingCard(null); setCardFront(""); setCardBack(""); }}>Cancel</Button>}
                  </div>
                </div>

                {cards.length === 0 ? (
                  <p className="text-sm text-muted-foreground text-center py-4">No cards yet. Add your first card above.</p>
                ) : (
                  <div className="space-y-2">
                    {cards.map((c, i) => (
                      <div key={c.id} className="flex items-center gap-3 rounded-lg border bg-background p-3">
                        <span className="text-xs text-muted-foreground w-6">{i + 1}</span>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium truncate">{c.front}</p>
                          <p className="text-xs text-muted-foreground truncate">{c.back}</p>
                        </div>
                        <Button variant="ghost" size="icon" className="h-8 w-8" aria-label={`Edit card “${c.front}”`} title="Edit card" onClick={() => startEditCard(c)}><Pencil className="h-3 w-3" /></Button>
                        <Button variant="ghost" size="icon" className="h-8 w-8" aria-label={`Delete card “${c.front}”`} title="Delete card" onClick={() => deleteCard(c.id)}><Trash2 className="h-3 w-3 text-destructive" /></Button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </Card>
        ))}
      </div>
    </div>
  );
}

// Manage lessons.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Plus, Pencil, Trash2 } from "lucide-react";
import { useToast } from "@/hooks/useToast";
import { Badge } from "@/components/ui/badge";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";
import { contentGuardMessage, contentSaveError } from "@/lib/contentGuards";
import type { Tables } from "@/integrations/supabase/types";

/** A lesson row with its topic embed (`select("*, topics(name)")`). */
type LessonRow = Tables<"lessons"> & { topics: { name: string } | null };

/** PostgREST's "no rows for .single()" code — an expected result here, not a failure. */
const NO_ROWS = "PGRST116";

async function resolveTopicId(name: string): Promise<string | null> {
  if (!name.trim()) return null;
  const trimmed = name.trim();
  const { data: existing, error: lookupError } = await supabase
    .from("topics").select("id").ilike("name", trimmed).limit(1).single();
  // Anything other than "no rows" is a real failure. Swallowing it made a
  // broken lookup look like "topic not found", so the save quietly created a
  // second topic with the same name.
  if (lookupError && lookupError.code !== NO_ROWS) throw lookupError;
  if (existing) return existing.id;
  const { data: created, error: createError } = await supabase
    .from("topics").insert({ name: trimmed }).select("id").single();
  if (createError) throw createError;
  return created?.id ?? null;
}

export default function AdminLessons() {
  const { toast } = useToast();
  const [lessons, setLessons] = useState<LessonRow[]>([]);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<LessonRow | null>(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [topicName, setTopicName] = useState("");
  const [videoUrl, setVideoUrl] = useState("");
  const [sortOrder, setSortOrder] = useState(0);
  const [zoomUrl, setZoomUrl] = useState("");
  const { failure, report, clear } = useLoadFailure("lessons");

  const load = async () => {
    clear();
    const { data, error } = await supabase.from("lessons").select("*, topics(name)").order("sort_order");
    // Ignoring this showed an empty console to an admin whose request failed.
    if (error) {
      report(error);
      setLessons([]);
      return;
    }
    setLessons(data ?? []);
  };

  useEffect(() => { load(); }, []);

  const save = async () => {
    let topicId: string | null = null;
    try {
      topicId = await resolveTopicId(topicName);
    } catch (e) {
      // A topic name is guarded too, so a damaged one can be refused here.
      toast({
        title: "Could not look up that topic",
        description: contentGuardMessage(e?.message) ?? e?.message,
        variant: "destructive",
      });
      return;
    }
    const payload = { title, content, topic_id: topicId!, video_url: videoUrl || null, zoom_url: zoomUrl || null, sort_order: sortOrder };
    if (!topicId) {
      toast({ title: "Error", description: "Please enter a topic name", variant: "destructive" });
      return;
    }
    const { error } = editing
      ? await supabase.from("lessons").update(payload).eq("id", editing.id)
      : await supabase.from("lessons").insert(payload);
    // A refused save used to close the dialog and toast "Updated" anyway.
    if (error) {
      toast(contentSaveError("Could not save the lesson", error.message));
      return;
    }
    toast({ title: editing ? "Updated" : "Created" });
    setOpen(false); setEditing(null); setTitle(""); setContent(""); setTopicName(""); setVideoUrl(""); setZoomUrl(""); setSortOrder(0);
    load();
  };

  const remove = async (id: string) => {
    await supabase.from("lessons").delete().eq("id", id);
    toast({ title: "Deleted" }); load();
  };

  const openEdit = (l: LessonRow) => {
    setEditing(l); setTitle(l.title); setContent(l.content ?? ""); setTopicName(l.topics?.name ?? ""); setVideoUrl(l.video_url ?? ""); setZoomUrl(l.zoom_url ?? ""); setSortOrder(l.sort_order); setOpen(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div><h1 className="text-2xl font-bold tracking-tight">Lessons</h1><p className="text-muted-foreground">Manage lesson content</p></div>
        <Dialog open={open} onOpenChange={(o) => { setOpen(o); if (!o) setEditing(null); }}>
          <DialogTrigger asChild><Button className="gap-2"><Plus className="h-4 w-4" /> Add Lesson</Button></DialogTrigger>
          <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
            <DialogHeader><DialogTitle>{editing ? "Edit" : "New"} Lesson</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Topic</Label>
                <Input value={topicName} onChange={(e) => setTopicName(e.target.value)} placeholder="e.g. Marketing, Finance, HR" />
              </div>
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} /></div>
              <div><Label>Content</Label><Textarea value={content} onChange={(e) => setContent(e.target.value)} className="min-h-[200px]" /></div>
              <div><Label>Video URL (optional)</Label><Input value={videoUrl} onChange={(e) => setVideoUrl(e.target.value)} /></div>
              <div><Label>Zoom Meeting Link (optional)</Label><Input value={zoomUrl} onChange={(e) => setZoomUrl(e.target.value)} placeholder="https://zoom.us/j/..." /></div>
              <div><Label>Sort Order</Label><Input type="number" value={sortOrder} onChange={(e) => setSortOrder(+e.target.value)} /></div>
              <Button onClick={save} className="w-full">{editing ? "Update" : "Create"}</Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
      {failure && <QueryError message={failure} onRetry={load} />}
      <div className="space-y-3">
        {lessons.map((l) => (
          <Card key={l.id} className="border-border/60 shadow-sm">
            <CardContent className="flex items-center justify-between p-4">
              <div>
                <p className="font-medium">{l.title}</p>
                <Badge variant="secondary" className="mt-1">{l.topics?.name ?? "No topic"}</Badge>
              </div>
              <div className="flex gap-2">
                <Button size="icon" variant="ghost" aria-label={`Edit ${l.title}`} title={`Edit ${l.title}`} onClick={() => openEdit(l)}><Pencil className="h-4 w-4" /></Button>
                <Button size="icon" variant="ghost" aria-label={`Delete ${l.title}`} title={`Delete ${l.title}`} onClick={() => remove(l.id)}><Trash2 className="h-4 w-4 text-destructive" /></Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

// Admin Payments: review subscription requests. Approving marks the sub active
// (ends_at = now + plan.months); rejecting marks it cancelled. Table updates go
// through an admin-permitted path (service role not required: admins pass RLS
// via a dedicated policy).
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { useToast } from "@/hooks/useToast";
import type { Tables } from "@/integrations/supabase/types";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";
import { addMonths, format } from "date-fns";
import { Check, X, RefreshCw, Landmark, Wallet, ReceiptText, Download } from "lucide-react";

/** A subscription row with its plan embed. The profile is looked up by user_id
 * separately: subscriptions has no foreign key to profiles, so an embed fails. */
type SubscriptionRow = Tables<"subscriptions"> & {
  plans: { name: string; months: number; price_monthly: number } | null;
};
type ProfileContact = { username: string | null; full_name: string | null; email: string | null };

const PLAN_PRICE: Record<string, string> = { free: "—", monthly: "$40/mo", quarterly: "$72 / 3mo", annual: "$80 / yr" };

const METHOD_LABEL: Record<string, string> = {
  bank_transfer: "Bank Transfer",
  ewallet_urpay: "E-Wallet (Urpay)",
};

function MethodBadge({ method }: { method: string | null }) {
  if (!method) return <span className="text-xs text-muted-foreground">—</span>;
  const isBank = method === "bank_transfer";
  return (
    <Badge variant="outline" className="gap-1 text-[11px]">
      {isBank ? <Landmark className="h-3 w-3" /> : <Wallet className="h-3 w-3" />}
      {METHOD_LABEL[method] ?? method}
    </Badge>
  );
}

export default function AdminPayments() {
  const { toast } = useToast();
  const { role } = useAuth();
  const [rows, setRows] = useState<SubscriptionRow[]>([]);
  const [profiles, setProfiles] = useState<Record<string, ProfileContact>>({});
  const [loading, setLoading] = useState(true);
  const { failure, report, clear } = useLoadFailure("subscription requests");

  const load = async () => {
    setLoading(true);
    clear();
    const { data, error } = await supabase
      .from("subscriptions")
      .select("*, plans(name, months, price_monthly)")
      .order("created_at", { ascending: false })
      .limit(200);
    // A failed read rendered "No subscription requests yet.", so an admin could
    // believe nobody had paid.
    if (error) {
      report(error);
      setRows([]);
      setLoading(false);
      return;
    }
    const list = (data ?? []) as SubscriptionRow[];
    setRows(list);
    const userIds = [...new Set(list.map((r) => r.user_id))];
    if (userIds.length > 0) {
      const { data: profileRows, error: profileError } = await supabase
        .from("profiles")
        .select("user_id, username, full_name, email")
        .in("user_id", userIds);
      if (profileError) report(profileError);
      const map: Record<string, ProfileContact> = {};
      (profileRows ?? []).forEach((p) => { map[p.user_id] = p; });
      setProfiles(map);
    } else {
      setProfiles({});
    }
    setLoading(false);
  };
  useEffect(() => { if (role === "admin") load(); }, [role]);

  const decide = async (id: string, approve: boolean, months: number) => {
    // Calendar months: a 3-month plan runs to the same day three months on
    // (not 90 fixed days), and an annual plan to the same day next year.
    const patch = approve
      ? { status: "active", starts_at: new Date().toISOString(), ends_at: addMonths(new Date(), months).toISOString(), updated_at: new Date().toISOString() }
      : { status: "cancelled", updated_at: new Date().toISOString() };
    const { error } = await supabase.from("subscriptions").update(patch).eq("id", id);
    if (error) {
      toast({ title: "Update failed", description: error.message, variant: "destructive" });
      return;
    }
    toast({ title: approve ? "Subscription activated" : "Request rejected" });
    load();
  };

  if (role !== "admin") return <Card><CardContent className="p-10 text-center text-muted-foreground">Admins only.</CardContent></Card>;

  const pending = rows.filter(r => r.status === "pending_payment");

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Payments</h1>
          <p className="text-muted-foreground">Subscription requests and active plans</p>
        </div>
        <Button variant="outline" size="sm" onClick={load} className="gap-2"><RefreshCw className="h-4 w-4" /> Refresh</Button>
      </div>

      {pending.length > 0 && (
        <Card className="border-amber-500/40 bg-amber-500/5">
          <CardContent className="p-4 text-sm">
            <span className="font-medium">{pending.length} request{pending.length > 1 ? "s" : ""} awaiting confirmation</span> — verify the bank transfer, then activate.
          </CardContent>
        </Card>
      )}

      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>User</TableHead>
                <TableHead>Plan</TableHead>
                <TableHead>Method</TableHead>
                <TableHead>Receipt</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Requested</TableHead>
                <TableHead>Ends</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow><TableCell colSpan={8} className="py-10 text-center text-muted-foreground">Loading…</TableCell></TableRow>
              ) : failure ? (
                <TableRow>
                  <TableCell colSpan={8} className="py-6">
                    <QueryError message={failure} onRetry={load} />
                  </TableCell>
                </TableRow>
              ) : rows.length === 0 ? (
                <TableRow><TableCell colSpan={8} className="py-10 text-center text-muted-foreground">No subscription requests yet.</TableCell></TableRow>
              ) : (
                rows.map(r => (
                  <TableRow key={r.id}>
                    <TableCell>
                      <p className="font-medium text-sm">{profiles[r.user_id]?.email ?? profiles[r.user_id]?.username ?? r.user_id.slice(0, 8)}</p>
                      <p className="text-xs text-muted-foreground">{profiles[r.user_id]?.email}</p>
                      {r.full_name && (
                        <p className="mt-0.5 flex items-center gap-1 text-[11px] text-muted-foreground">
                          <Download className="h-3 w-3" /> {r.full_name}
                        </p>
                      )}
                    </TableCell>
                    <TableCell className="text-sm">{r.plans?.name ?? r.plan_id}<span className="block text-xs text-muted-foreground">{PLAN_PRICE[r.plan_id]}</span></TableCell>
                    <TableCell><MethodBadge method={r.payment_method ?? null} /></TableCell>
                    <TableCell>
                      {r.receipt_path ? (
                        <Button
                          size="sm"
                          variant="outline"
                          className="gap-1 text-xs"
                          onClick={async () => {
                            const { data, error } = await supabase.storage
                              .from("homework-uploads")
                              .createSignedUrl(r.receipt_path, 3600);
                            if (error || !data?.signedUrl) {
                              toast({ title: "Could not open receipt", description: error?.message, variant: "destructive" });
                              return;
                            }
                            window.open(data.signedUrl, "_blank", "noopener,noreferrer");
                          }}
                        >
                          <ReceiptText className="h-3.5 w-3.5" /> View
                        </Button>
                      ) : (
                        <span className="text-xs text-muted-foreground">—</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <Badge variant="secondary" className={
                        r.status === "active" ? "bg-emerald-500/15 text-emerald-600" :
                        r.status === "pending_payment" ? "bg-amber-500/15 text-amber-600" :
                        "bg-muted text-muted-foreground"
                      }>{r.status.replace("_", " ")}</Badge>
                    </TableCell>
                    <TableCell className="text-xs">{format(new Date(r.created_at), "MMM d, HH:mm")}</TableCell>
                    <TableCell className="text-xs">{r.ends_at ? format(new Date(r.ends_at), "MMM d, yyyy") : "—"}</TableCell>
                    <TableCell className="text-right">
                      {r.status === "pending_payment" && (
                        <div className="flex justify-end gap-2">
                          <Button size="sm" variant="outline" className="gap-1 text-emerald-600" onClick={() => decide(r.id, true, r.plans?.months ?? 1)}>
                            <Check className="h-3.5 w-3.5" /> Activate
                          </Button>
                          <Button size="sm" variant="outline" className="gap-1 text-destructive" onClick={() => decide(r.id, false, 0)}>
                            <X className="h-3.5 w-3.5" /> Reject
                          </Button>
                        </div>
                      )}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}

// Manage quizzes and questions.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Switch } from "@/components/ui/switch";
import { Plus, Pencil, Trash2, Brain, Upload } from "lucide-react";
import { useToast } from "@/hooks/useToast";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";
import { Badge } from "@/components/ui/badge";
import { getSafeUploadExtension } from "@/lib/fileValidation";
import { contentGuardMessage, contentSaveError } from "@/lib/contentGuards";
import { resolveQuizOptions } from "@/lib/quizAnswers";
import type { Tables } from "@/integrations/supabase/types";

/** A quiz row with its topic embed (`select("*, topics(name)")`). */
type QuizRow = Tables<"quizzes"> & { topics: { name: string } | null };

export default function AdminQuizzes() {
  const { toast } = useToast();
  const [quizzes, setQuizzes] = useState<QuizRow[]>([]);
  const [topics, setTopics] = useState<Tables<"topics">[]>([]);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<QuizRow | null>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [topicId, setTopicId] = useState("");
  const [timeLimit, setTimeLimit] = useState<number | "">("");
  const [isPublished, setIsPublished] = useState(false);
  const [examFile, setExamFile] = useState<File | null>(null);
  const [uploadingFile, setUploadingFile] = useState(false);

  const [questionsOpen, setQuestionsOpen] = useState<string | null>(null);
  const [questions, setQuestions] = useState<Tables<"questions">[]>([]);
  const [qText, setQText] = useState("");
  const [qOptions, setQOptions] = useState(["", "", "", ""]);
  const [qCorrect, setQCorrect] = useState(0);
  const [qExplanation, setQExplanation] = useState("");
  const { failure, report, clear } = useLoadFailure("quizzes");

  const load = async () => {
    clear();
    const [q, t] = await Promise.all([
      supabase.from("quizzes").select("*, topics(name)").order("created_at", { ascending: false }),
      supabase.from("topics").select("*").order("sort_order"),
    ]);
    // Both reads used to collapse into `?? []`, so a failed request rendered an
    // empty console with no hint anything had gone wrong.
    const error = q.error ?? t.error;
    if (error) {
      report(error);
      setQuizzes([]);
      setTopics([]);
      return;
    }
    setQuizzes(q.data ?? []);
    setTopics(t.data ?? []);
  };

  useEffect(() => { load(); }, []);

  const loadQuestions = async (quizId: string) => {
    const { data, error } = await supabase.from("questions").select("*").eq("quiz_id", quizId).order("sort_order");
    // Otherwise a failed read showed "this quiz has no questions".
    if (error) {
      report(error);
      setQuestions([]);
      setQuestionsOpen(quizId);
      return;
    }
    setQuestions(data ?? []);
    setQuestionsOpen(quizId);
  };

  const saveQuiz = async () => {
    let examFileUrl: string | null = editing?.exam_file_url ?? null;

    if (examFile) {
      setUploadingFile(true);
      const ext = getSafeUploadExtension(examFile);
      if (!ext) {
        toast({ title: "File upload blocked", description: "Unsupported file type. Allowed: PDF, Word, images.", variant: "destructive" });
        setUploadingFile(false);
        return;
      }
      const path = `${crypto.randomUUID()}.${ext}`;
      const { error: uploadErr } = await supabase.storage.from("quiz-files").upload(path, examFile);
      if (uploadErr) {
        toast({ title: "File upload failed", description: uploadErr.message, variant: "destructive" });
        setUploadingFile(false);
        return;
      }
      // Store path only (bucket is private, use signed URLs to access)
      examFileUrl = path;
      setUploadingFile(false);
    }

    const payload = {
      title, description, topic_id: topicId || null,
      time_limit_minutes: timeLimit || null, is_published: isPublished,
      exam_file_url: examFileUrl,
    };

    let quizId = editing?.id;
    if (editing) {
      const { error } = await supabase.from("quizzes").update(payload).eq("id", editing.id);
      // A refused update still toasted "Updated", so a title with a damaged
      // character looked saved while the database kept the old one.
      if (error) {
        toast(contentSaveError("Could not update the quiz", error.message));
        return;
      }
    } else {
      const { data, error } = await supabase.from("quizzes").insert(payload).select("id").single();
      // A failed insert still toasted "Created", leaving the admin with no quiz.
      if (error) {
        toast({ title: "Could not create the quiz", description: error.message, variant: "destructive" });
        return;
      }
      quizId = data?.id;
    }

    // If exam file was uploaded and it's a new quiz, auto-create confirmation question
    let setupWarning: string | null = null;
    if (examFileUrl && !editing && quizId) {
      const { error } = await supabase.from("questions").insert({
        quiz_id: quizId,
        question_text: "Have you completed and submitted the exam?",
        options: ["Yes, I have submitted my exam", "No, I have not submitted yet"],
        correct_option: 0,
        explanation: "Make sure you upload your solved exam file before confirming.",
        sort_order: 0,
      });
      // The quiz itself saved, so still report success — but never swallow it:
      // without this the quiz looked ready with no confirmation step.
      if (error) setupWarning = contentGuardMessage(error.message) ?? error.message;
    }

    toast(
      setupWarning
        ? {
            title: "Quiz created, but its confirmation question was not",
            description: `${setupWarning} Add it under Questions.`,
            variant: "destructive",
          }
        : { title: editing ? "Updated" : "Created" },
    );
    setOpen(false); setEditing(null); resetForm(); load();
  };

  const addQuestion = async () => {
    if (!questionsOpen || !qText.trim()) return;
    // Blank option slots are dropped before saving, which shifts every option
    // after them, so the index the form reports is not the one that belongs in
    // the row. Resolve the picked option by its text (see quizAnswers.ts).
    const resolved = resolveQuizOptions(qOptions, qCorrect);
    if (resolved.error) {
      toast({ title: "Could not add the question", description: resolved.error, variant: "destructive" });
      return;
    }
    const { options, correctOption } = resolved;
    const { error } = await supabase.from("questions").insert({
      quiz_id: questionsOpen, question_text: qText, options,
      correct_option: correctOption, explanation: qExplanation || null, sort_order: questions.length,
    });
    // Ignoring this emptied the form and claimed "Question added" for a question
    // the database had refused.
    if (error) {
      toast(contentSaveError("Could not add the question", error.message));
      return;
    }
    setQText(""); setQOptions(["", "", "", ""]); setQCorrect(0); setQExplanation("");
    loadQuestions(questionsOpen);
    toast({ title: "Question added" });
  };

  const removeQuestion = async (id: string) => {
    await supabase.from("questions").delete().eq("id", id);
    if (questionsOpen) loadQuestions(questionsOpen);
  };

  const resetForm = () => {
    setTitle(""); setDescription(""); setTopicId(""); setTimeLimit(""); setIsPublished(false); setExamFile(null);
  };

  if (questionsOpen) {
    const quiz = quizzes.find((q) => q.id === questionsOpen);
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div><h1 className="text-2xl font-bold">{quiz?.title} - Questions</h1></div>
          <Button variant="ghost" onClick={() => setQuestionsOpen(null)}>← Back</Button>
        </div>
        <Card className="neon-border bg-card">
          <CardHeader><CardTitle className="text-lg">Add Question</CardTitle></CardHeader>
          <CardContent className="space-y-4">
            <div><Label>Question</Label><Textarea value={qText} onChange={(e) => setQText(e.target.value)} className="bg-secondary/50 border-border" /></div>
            {qOptions.map((opt, i) => (
              <div key={i} className="flex items-center gap-2">
                <Label className="w-20">Option {i + 1}</Label>
                <Input value={opt} onChange={(e) => { const n = [...qOptions]; n[i] = e.target.value; setQOptions(n); }} className="bg-secondary/50 border-border" />
                <input type="radio" name="correct" checked={qCorrect === i} onChange={() => setQCorrect(i)} />
                <span className="text-xs text-muted-foreground">Correct</span>
              </div>
            ))}
            <div><Label>Explanation (optional)</Label><Textarea value={qExplanation} onChange={(e) => setQExplanation(e.target.value)} className="bg-secondary/50 border-border" /></div>
            <Button onClick={addQuestion}>Add Question</Button>
          </CardContent>
        </Card>
        {failure && questionsOpen && (
          <QueryError message={failure} onRetry={() => loadQuestions(questionsOpen)} className="mb-3" />
        )}
        <div className="space-y-3">
          {questions.map((q, i) => (
            <Card key={q.id} className="neon-border bg-card">
              <CardContent className="flex items-start justify-between p-4">
                <div>
                  <p className="font-medium">Q{i + 1}. {q.question_text}</p>
                  <div className="mt-1 space-y-0.5">
                    {(Array.isArray(q.options) ? q.options : []).map((opt: string, j: number) => (
                      <p key={j} className={`text-sm ${j === q.correct_option ? "text-primary font-medium" : "text-muted-foreground"}`}>
                        {j === q.correct_option ? "✓" : "○"} {opt}
                      </p>
                    ))}
                  </div>
                </div>
                <Button size="icon" variant="ghost" aria-label="Delete question" title="Delete question" onClick={() => removeQuestion(q.id)}><Trash2 className="h-4 w-4 text-destructive" /></Button>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div><h1 className="text-2xl font-bold tracking-tight">Quizzes</h1><p className="text-muted-foreground">Create and manage quizzes</p></div>
        <Dialog open={open} onOpenChange={(o) => { setOpen(o); if (!o) { setEditing(null); resetForm(); } }}>
          <DialogTrigger asChild><Button className="gap-2 bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground glow-shadow"><Plus className="h-4 w-4" /> Add Quiz</Button></DialogTrigger>
          <DialogContent className="neon-border bg-card">
            <DialogHeader><DialogTitle>{editing ? "Edit" : "New"} Quiz</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div><Label>Title</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} className="bg-secondary/50 border-border" /></div>
              <div><Label>Description</Label><Textarea value={description} onChange={(e) => setDescription(e.target.value)} className="bg-secondary/50 border-border" /></div>
              <div><Label>Topic</Label>
                <Select value={topicId} onValueChange={setTopicId}>
                  <SelectTrigger className="bg-secondary/50 border-border"><SelectValue placeholder="Select topic" /></SelectTrigger>
                  <SelectContent>{topics.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent>
                </Select>
              </div>
              <div><Label>Time Limit (minutes)</Label><Input type="number" value={timeLimit} onChange={(e) => setTimeLimit(+e.target.value || "")} className="bg-secondary/50 border-border" /></div>

              {/* Exam File Upload */}
              <div className="space-y-2">
                <Label>Exam File (optional)</Label>
                <div className="flex items-center gap-3">
                  <label className="flex-1 flex items-center gap-2 cursor-pointer rounded-lg border border-dashed border-border p-3 hover:border-primary/40 transition-colors bg-secondary/30">
                    <Upload className="h-4 w-4 text-muted-foreground" />
                    <span className="text-sm text-muted-foreground">{examFile ? examFile.name : "Upload exam file (PDF, DOC, etc.)"}</span>
                    <input type="file" className="hidden" onChange={(e) => setExamFile(e.target.files?.[0] ?? null)} accept=".pdf,.doc,.docx,.png,.jpg,.jpeg" />
                  </label>
                  {examFile && <Button size="sm" variant="ghost" onClick={() => setExamFile(null)}>Clear</Button>}
                </div>
                {editing?.exam_file_url && !examFile && (
                  <p className="text-xs text-muted-foreground">Current file attached. Upload a new one to replace.</p>
                )}
              </div>

              <div className="flex items-center gap-2"><Switch checked={isPublished} onCheckedChange={setIsPublished} /><Label>Published</Label></div>
              <Button onClick={saveQuiz} className="w-full bg-gradient-to-r from-primary to-[hsl(var(--neon-purple))] text-primary-foreground" disabled={uploadingFile}>
                {uploadingFile ? "Uploading…" : editing ? "Update" : "Create"}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
      {failure && <QueryError message={failure} onRetry={load} />}
      <div className="space-y-3">
        {quizzes.map((q) => (
          <Card key={q.id} className="neon-border bg-card">
            <CardContent className="flex flex-wrap items-center justify-between gap-3 p-4">
              <div className="min-w-0">
                <p className="font-medium">{q.title}</p>
                <div className="flex gap-2 mt-1">
                  <Badge variant="secondary">{q.topics?.name ?? "General"}</Badge>
                  <Badge variant={q.is_published ? "default" : "outline"}>{q.is_published ? "Published" : "Draft"}</Badge>
                  {q.exam_file_url && <Badge variant="outline" className="border-primary/30 text-primary">📎 Exam File</Badge>}
                </div>
              </div>
              <div className="ml-auto flex shrink-0 gap-2">
                <Button size="sm" variant="outline" className="border-border/60 hover:border-primary/30" onClick={() => loadQuestions(q.id)}>Questions</Button>
                <Button size="icon" variant="ghost" aria-label={`Edit ${q.title}`} title={`Edit ${q.title}`} onClick={() => { setEditing(q); setTitle(q.title); setDescription(q.description ?? ""); setTopicId(q.topic_id ?? ""); setTimeLimit(q.time_limit_minutes ?? ""); setIsPublished(q.is_published); setOpen(true); }}><Pencil className="h-4 w-4" /></Button>
                <Button size="icon" variant="ghost" aria-label={`Delete ${q.title}`} title={`Delete ${q.title}`} onClick={async () => { await supabase.from("quizzes").delete().eq("id", q.id); load(); }}><Trash2 className="h-4 w-4 text-destructive" /></Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

// Grade homework submissions.
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/useToast";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import type { Json } from "@/integrations/supabase/types";
import { QueryError } from "@/components/QueryError";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription,
} from "@/components/ui/dialog";
import {
  Download, Upload, FileCheck, Loader2, ClipboardList, Brain, Eye,
} from "lucide-react";
import { getSafeUploadExtension } from "@/lib/fileValidation";

interface HWSubmission {
  id: string;
  homework_id: string;
  user_id: string;
  status: string;
  file_url: string | null;
  content: string | null;
  submitted_at: string;
  grade: string | null;
  feedback: string | null;
  correction_file_url: string | null;
  homework_title: string;
  student_name: string;
  student_username: string | null;
}

interface QuizSubmission {
  id: string;
  quiz_id: string;
  user_id: string;
  score: number | null;
  total_questions: number | null;
  completed_at: string | null;
  submission_file_url: string | null;
  correction_file_url: string | null;
  answers: Json;
  quiz_title: string;
  student_name: string;
  student_username: string | null;
}

export default function AdminSubmissions() {
  const { toast } = useToast();
  const [hwSubmissions, setHwSubmissions] = useState<HWSubmission[]>([]);
  const [quizSubmissions, setQuizSubmissions] = useState<QuizSubmission[]>([]);
  const [loading, setLoading] = useState(true);
  const { failure, report, clear } = useLoadFailure("submissions");

  // Grading dialog
  const [gradeTarget, setGradeTarget] = useState<HWSubmission | null>(null);
  const [gradeValue, setGradeValue] = useState("");
  const [feedbackValue, setFeedbackValue] = useState("");
  const [correctionFile, setCorrectionFile] = useState<File | null>(null);
  const [saving, setSaving] = useState(false);

  // Quiz correction dialog
  const [quizGradeTarget, setQuizGradeTarget] = useState<QuizSubmission | null>(null);
  const [quizCorrectionFile, setQuizCorrectionFile] = useState<File | null>(null);
  const [quizSaving, setQuizSaving] = useState(false);

  const loadData = async () => {
    setLoading(true);
    clear();

    // Load homework submissions with joined data
    const { data: hwData, error: hwError } = await supabase
      .from("homework_submissions")
      .select("id, homework_id, user_id, status, file_url, content, submitted_at, grade, feedback, correction_file_url")
      .order("submitted_at", { ascending: false });

    // Load quiz attempts that have submission files
    const { data: quizData, error: quizError } = await supabase
      .from("quiz_attempts")
      .select("id, quiz_id, user_id, score, total_questions, completed_at, submission_file_url, correction_file_url, answers")
      .order("started_at", { ascending: false });

    // Both tabs used to render "nothing submitted" over a failed request.
    const loadError = hwError ?? quizError;
    if (loadError) {
      report(loadError);
      setHwSubmissions([]);
      setQuizSubmissions([]);
      setLoading(false);
      return;
    }

    // Get unique user IDs and homework/quiz IDs
    const allUserIds = [
      ...(hwData ?? []).map(s => s.user_id),
      ...(quizData ?? []).map(s => s.user_id),
    ];
    const hwIds = (hwData ?? []).map(s => s.homework_id);
    const quizIds = (quizData ?? []).map(s => s.quiz_id);

    const { data: profiles } = allUserIds.length > 0
      ? await supabase.from("profiles").select("user_id, full_name, username").in("user_id", [...new Set(allUserIds)])
      : { data: [] };

    const { data: homeworks } = hwIds.length > 0
      ? await supabase.from("homework").select("id, title").in("id", [...new Set(hwIds)])
      : { data: [] };

    const { data: quizzes } = quizIds.length > 0
      ? await supabase.from("quizzes").select("id, title").in("id", [...new Set(quizIds)])
      : { data: [] };

    const profileMap = Object.fromEntries((profiles ?? []).map(p => [p.user_id, p]));
    const hwMap = Object.fromEntries((homeworks ?? []).map(h => [h.id, h]));
    const quizMap = Object.fromEntries((quizzes ?? []).map(q => [q.id, q]));

    setHwSubmissions((hwData ?? []).map(s => ({
      ...s,
      homework_title: hwMap[s.homework_id]?.title ?? "Unknown",
      student_name: profileMap[s.user_id]?.full_name ?? "Unknown",
      student_username: profileMap[s.user_id]?.username ?? null,
    })));

    setQuizSubmissions((quizData ?? []).filter(s => s.submission_file_url).map(s => ({
      ...s,
      quiz_title: quizMap[s.quiz_id]?.title ?? "Unknown",
      student_name: profileMap[s.user_id]?.full_name ?? "Unknown",
      student_username: profileMap[s.user_id]?.username ?? null,
    })));

    setLoading(false);
  };

  useEffect(() => { loadData(); }, []);

  const downloadSignedFile = async (bucket: string, path: string) => {
    // Strip any full URL prefix — we only need the storage path
    let cleanPath = path;
    const marker = `/object/public/${bucket}/`;
    const idx = path.indexOf(marker);
    if (idx !== -1) cleanPath = path.slice(idx + marker.length);
    if (!cleanPath) {
      toast({ title: "Could not open file", description: `File path is empty after stripping the public URL prefix.`, variant: "destructive" });
      return;
    }

    const { data, error } = await supabase.storage.from(bucket).createSignedUrl(cleanPath, 3600);
    if (error || !data?.signedUrl) {
      toast({ title: "Could not open file", description: error?.message ?? "Unknown error", variant: "destructive" });
      return;
    }
    window.open(data.signedUrl, "_blank", "noopener,noreferrer");
  };

  // ── HOMEWORK GRADING ──
  const openGradeDialog = (sub: HWSubmission) => {
    setGradeTarget(sub);
    setGradeValue(sub.grade ?? "");
    setFeedbackValue(sub.feedback ?? "");
    setCorrectionFile(null);
  };

  const saveHomeworkGrade = async () => {
    if (!gradeTarget) return;
    setSaving(true);

    let correctionUrl = gradeTarget.correction_file_url;

    if (correctionFile) {
      const ext = getSafeUploadExtension(correctionFile);
      if (!ext) {
        toast({ title: "Upload blocked", description: "Unsupported file type.", variant: "destructive" });
        setSaving(false);
        return;
      }
      const path = `corrections/${gradeTarget.user_id}/${gradeTarget.homework_id}/${crypto.randomUUID()}.${ext}`;
      const { error: uploadErr } = await supabase.storage.from("homework-uploads").upload(path, correctionFile);
      if (uploadErr) {
        toast({ title: "Upload failed", description: uploadErr.message, variant: "destructive" });
        setSaving(false);
        return;
      }
      correctionUrl = path;
    }

    const { error } = await supabase
      .from("homework_submissions")
      .update({
        grade: gradeValue || null,
        feedback: feedbackValue || null,
        correction_file_url: correctionUrl,
        status: gradeValue ? "graded" : "reviewed",
        graded_at: new Date().toISOString(),
      })
      .eq("id", gradeTarget.id);

    if (error) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Saved", description: "Submission graded successfully." });
      setGradeTarget(null);
      loadData();
    }
    setSaving(false);
  };

  // ── QUIZ CORRECTION ──
  const openQuizGradeDialog = (sub: QuizSubmission) => {
    setQuizGradeTarget(sub);
    setQuizCorrectionFile(null);
  };

  const saveQuizCorrection = async () => {
    if (!quizGradeTarget) return;
    setQuizSaving(true);

    let correctionUrl = quizGradeTarget.correction_file_url;

    if (quizCorrectionFile) {
      const ext = getSafeUploadExtension(quizCorrectionFile);
      if (!ext) {
        toast({ title: "Upload blocked", description: "Unsupported file type.", variant: "destructive" });
        setQuizSaving(false);
        return;
      }
      const path = `quiz-corrections/${quizGradeTarget.user_id}/${quizGradeTarget.quiz_id}/${crypto.randomUUID()}.${ext}`;
      const { error: uploadErr } = await supabase.storage.from("homework-uploads").upload(path, quizCorrectionFile);
      if (uploadErr) {
        toast({ title: "Upload failed", description: uploadErr.message, variant: "destructive" });
        setQuizSaving(false);
        return;
      }
      correctionUrl = path;
    }

    const { error } = await supabase
      .from("quiz_attempts")
      .update({ correction_file_url: correctionUrl })
      .eq("id", quizGradeTarget.id);

    if (error) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Saved", description: "Correction file uploaded." });
      setQuizGradeTarget(null);
      loadData();
    }
    setQuizSaving(false);
  };

  const statusBadge = (status: string) => {
    const map: Record<string, string> = {
      pending: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
      graded: "bg-green-500/20 text-green-400 border-green-500/30",
      reviewed: "bg-blue-500/20 text-blue-400 border-blue-500/30",
    };
    return map[status] ?? "bg-muted text-muted-foreground";
  };

  if (loading) {
    return (
      <div className="flex justify-center py-20">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  // Say the read failed rather than showing two empty tabs.
  if (failure) {
    return <QueryError message={failure} onRetry={loadData} />;
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Student Submissions</h1>
        <p className="text-muted-foreground">Review, grade, and upload corrections for student work</p>
      </div>

      <Tabs defaultValue="homework">
        <TabsList className="bg-secondary/60">
          <TabsTrigger value="homework" className="gap-2">
            <ClipboardList className="h-4 w-4" /> Homework ({hwSubmissions.length})
          </TabsTrigger>
          <TabsTrigger value="exams" className="gap-2">
            <Brain className="h-4 w-4" /> Exam Files ({quizSubmissions.length})
          </TabsTrigger>
        </TabsList>

        {/* ── HOMEWORK TAB ── */}
        <TabsContent value="homework">
          <Card className="neon-border bg-card/80 backdrop-blur">
            <CardContent className="p-0">
              {hwSubmissions.length === 0 ? (
                <div className="flex flex-col items-center py-16 text-muted-foreground">
                  <ClipboardList className="h-12 w-12 mb-4 opacity-40" />
                  <p>No homework submissions yet</p>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Student</TableHead>
                      <TableHead>Homework</TableHead>
                      <TableHead>Submitted</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead>Grade</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {hwSubmissions.map((sub) => (
                      <TableRow key={sub.id}>
                        <TableCell>
                          <div>
                            <p className="font-medium">{sub.student_name}</p>
                            {sub.student_username && (
                              <p className="text-xs text-muted-foreground">@{sub.student_username}</p>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="font-medium">{sub.homework_title}</TableCell>
                        <TableCell className="text-sm text-muted-foreground">
                          {new Date(sub.submitted_at).toLocaleDateString()}
                        </TableCell>
                        <TableCell>
                          <Badge variant="outline" className={statusBadge(sub.status)}>
                            {sub.status}
                          </Badge>
                        </TableCell>
                        <TableCell>{sub.grade || "—"}</TableCell>
                        <TableCell className="text-right space-x-2">
                          {sub.file_url && (
                            <Button size="sm" variant="outline" className="gap-1"
                              onClick={() => downloadSignedFile("homework-uploads", sub.file_url!)}>
                              <Download className="h-3.5 w-3.5" /> File
                            </Button>
                          )}
                          {sub.correction_file_url && (
                            <Button size="sm" variant="outline" className="gap-1 text-green-400 border-green-500/30"
                              onClick={() => downloadSignedFile("homework-uploads", sub.correction_file_url!)}>
                              <FileCheck className="h-3.5 w-3.5" /> Correction
                            </Button>
                          )}
                          <Button size="sm" className="gap-1" onClick={() => openGradeDialog(sub)}>
                            <Eye className="h-3.5 w-3.5" /> Grade
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* ── EXAMS TAB ── */}
        <TabsContent value="exams">
          <Card className="neon-border bg-card/80 backdrop-blur">
            <CardContent className="p-0">
              {quizSubmissions.length === 0 ? (
                <div className="flex flex-col items-center py-16 text-muted-foreground">
                  <Brain className="h-12 w-12 mb-4 opacity-40" />
                  <p>No exam file submissions yet</p>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Student</TableHead>
                      <TableHead>Quiz / Exam</TableHead>
                      <TableHead>Completed</TableHead>
                      <TableHead>Score</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {quizSubmissions.map((sub) => (
                      <TableRow key={sub.id}>
                        <TableCell>
                          <div>
                            <p className="font-medium">{sub.student_name}</p>
                            {sub.student_username && (
                              <p className="text-xs text-muted-foreground">@{sub.student_username}</p>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="font-medium">{sub.quiz_title}</TableCell>
                        <TableCell className="text-sm text-muted-foreground">
                          {sub.completed_at ? new Date(sub.completed_at).toLocaleDateString() : "—"}
                        </TableCell>
                        <TableCell>
                          {sub.score !== null ? `${sub.score}/${sub.total_questions}` : "—"}
                        </TableCell>
                        <TableCell className="text-right space-x-2">
                          {sub.submission_file_url && (
                            <Button size="sm" variant="outline" className="gap-1"
                              onClick={() => downloadSignedFile("homework-uploads", sub.submission_file_url!)}>
                              <Download className="h-3.5 w-3.5" /> Submission
                            </Button>
                          )}
                          {sub.correction_file_url && (
                            <Button size="sm" variant="outline" className="gap-1 text-green-400 border-green-500/30"
                              onClick={() => downloadSignedFile("homework-uploads", sub.correction_file_url!)}>
                              <FileCheck className="h-3.5 w-3.5" /> Correction
                            </Button>
                          )}
                          <Button size="sm" className="gap-1" onClick={() => openQuizGradeDialog(sub)}>
                            <Upload className="h-3.5 w-3.5" /> Upload Correction
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* ── HOMEWORK GRADE DIALOG ── */}
      <Dialog open={!!gradeTarget} onOpenChange={(o) => { if (!o) setGradeTarget(null); }}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>Grade Submission</DialogTitle>
            <DialogDescription>
              <strong>{gradeTarget?.student_name}</strong> — {gradeTarget?.homework_title}
            </DialogDescription>
          </DialogHeader>

          {gradeTarget?.content && (
            <div className="rounded-lg bg-secondary/50 p-3 text-sm max-h-32 overflow-auto">
              {gradeTarget.content}
            </div>
          )}

          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Grade</Label>
              <Input placeholder="e.g. A, 85%, Pass" value={gradeValue} onChange={e => setGradeValue(e.target.value)} />
            </div>
            <div className="space-y-2">
              <Label>Feedback</Label>
              <Textarea placeholder="Write feedback for the student..." value={feedbackValue} onChange={e => setFeedbackValue(e.target.value)} rows={3} />
            </div>
            <div className="space-y-2">
              <Label>Upload Correction File (optional)</Label>
              <Input type="file" onChange={e => setCorrectionFile(e.target.files?.[0] ?? null)} />
              {gradeTarget?.correction_file_url && (
                <p className="text-xs text-muted-foreground">A correction file already exists. Uploading a new one will replace it.</p>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setGradeTarget(null)}>Cancel</Button>
            <Button onClick={saveHomeworkGrade} disabled={saving} className="gap-2">
              {saving && <Loader2 className="h-4 w-4 animate-spin" />} Save
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── QUIZ CORRECTION DIALOG ── */}
      <Dialog open={!!quizGradeTarget} onOpenChange={(o) => { if (!o) setQuizGradeTarget(null); }}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>Upload Correction</DialogTitle>
            <DialogDescription>
              Upload corrected file for <strong>{quizGradeTarget?.student_name}</strong> — {quizGradeTarget?.quiz_title}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Correction File</Label>
              <Input type="file" onChange={e => setQuizCorrectionFile(e.target.files?.[0] ?? null)} />
              {quizGradeTarget?.correction_file_url && (
                <p className="text-xs text-muted-foreground">A correction file already exists. Uploading a new one will replace it.</p>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setQuizGradeTarget(null)}>Cancel</Button>
            <Button onClick={saveQuizCorrection} disabled={quizSaving || !quizCorrectionFile} className="gap-2">
              {quizSaving && <Loader2 className="h-4 w-4 animate-spin" />} Upload
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Account management: approve/create students+parents+admins, reset passwords,
// upload weekly reports.
import { useEffect, useState, useRef, useMemo } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription,
} from "@/components/ui/dialog";
import { useToast } from "@/hooks/useToast";
import {
  UserCheck, UserX, UserPlus, Trash2, Loader2, Clock, Users, ShieldCheck,
  KeyRound, FileText, Upload, Download, Search, Shield, X, AtSign, CreditCard,
} from "lucide-react";
import { SEOHead } from "@/components/SEOHead";
import { addMonths } from "date-fns";
import { validateUploadFile, getSafeUploadExtension } from "@/lib/fileValidation";
import { useLoadFailure } from "@/hooks/useLoadFailure";
import { QueryError } from "@/components/QueryError";

type RoleName = "student" | "parent" | "admin";

interface UserRow {
  user_id: string;
  role_id: string;
  role: RoleName | string;
  is_approved: boolean;
  full_name: string;
  username: string | null;
  email: string | null;
}

interface WeeklyReport {
  id: string;
  file_url: string;
  file_name: string;
  week_label: string | null;
  uploaded_at: string;
}

type RoleFilter = "all" | "student" | "parent" | "admin";
type StatusFilter = "all" | "approved" | "pending";

export default function AdminUsers() {
  const { user } = useAuth();
  const { toast } = useToast();

  const [rows, setRows] = useState<UserRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const { failure, report, clear } = useLoadFailure("accounts");

  // Filters
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<RoleFilter>("all");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");

  // Create form
  const [newEmail, setNewEmail] = useState("");
  const [newFullName, setNewFullName] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [newRole, setNewRole] = useState("student");
  const [creating, setCreating] = useState(false);

  // Reset password
  const [resetTarget, setResetTarget] = useState<UserRow | null>(null);
  const [resetPassword, setResetPassword] = useState("");
  const [resetting, setResetting] = useState(false);

  // Promote admin
  const [promoteOpen, setPromoteOpen] = useState(false);
  const [promoteEmail, setPromoteEmail] = useState("");
  const [promoting, setPromoting] = useState(false);

  // Assign username
  const [usernameTarget, setUsernameTarget] = useState<UserRow | null>(null);
  const [usernameValue, setUsernameValue] = useState("");
  const [assigningUsername, setAssigningUsername] = useState(false);

  // Active/pending subscriptions per user — drives the Grant/Revoke paid toggle
  // and the "Paid" badge in the role column.
  const [paidSubs, setPaidSubs] = useState<Record<string, { id: string; plan_id: string; status: string }>>({});

  // Weekly reports
  const [reportsStudent, setReportsStudent] = useState<UserRow | null>(null);
  const [reports, setReports] = useState<WeeklyReport[]>([]);
  const [loadingReports, setLoadingReports] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [weekLabel, setWeekLabel] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const invoke = async (action: string, body: Record<string, unknown>) => {
    const { data, error } = await supabase.functions.invoke("manage-accounts", {
      body: { action, ...body },
    });
    if (error || data?.error) {
      throw new Error(data?.error || error?.message || "Unknown error");
    }
    return data;
  };

  const load = async () => {
    setLoading(true);
    clear();
    const { data: roles, error: rolesError } = await supabase
      .from("user_roles")
      .select("id, user_id, role, is_approved");

    // A failed read used to hit the `!roles` bail-out and render an empty
    // console, which reads as "there are no accounts at all".
    if (rolesError) {
      report(rolesError);
      setRows([]);
      setLoading(false);
      return;
    }
    if (!roles) { setLoading(false); return; }

    const userIds = roles.map((r) => r.user_id);
    const { data: profiles, error: profilesError } = await supabase
      .from("profiles")
      .select("user_id, full_name, username, email")
      .in("user_id", userIds);
    // Names are cosmetic, but a silent failure made every account "Unknown".
    if (profilesError) report(profilesError);

    setRows(
      roles.map((r) => {
        const p = (profiles ?? []).find((p) => p.user_id === r.user_id);
        return {
          user_id: r.user_id,
          role_id: r.id,
          role: r.role,
          is_approved: r.is_approved,
          full_name: p?.full_name || "Unknown",
          username: p?.username ?? null,
          email: p?.email ?? null,
        };
      }),
    );

    // Subscription state per user (admins can select all subscriptions).
    const { data: subs, error: subsError } = await supabase
      .from("subscriptions")
      .select("id, user_id, plan_id, status")
      .in("status", ["active", "pending_payment"]);
    // Only cosmetic (the paid badge), but a silent failure made paying students
    // look like free ones.
    if (subsError) report(subsError);
    const subMap: Record<string, { id: string; plan_id: string; status: string }> = {};
    (subs ?? []).forEach((s) => { subMap[s.user_id] = s; });
    setPaidSubs(subMap);

    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return rows.filter((r) => {
      if (q) {
        const hay = `${r.full_name} ${r.email ?? ""} ${r.username ?? ""}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      if (roleFilter !== "all" && r.role !== roleFilter) return false;
      if (statusFilter === "approved" && !r.is_approved) return false;
      if (statusFilter === "pending" && r.is_approved) return false;
      return true;
    });
  }, [rows, search, roleFilter, statusFilter]);

  // Tab groupings (use filtered for search support)
  const pending = filtered.filter((r) => !r.is_approved && r.role !== "admin");
  const students = filtered.filter((r) => r.is_approved && r.role === "student");
  const parents = filtered.filter((r) => r.is_approved && r.role === "parent");
  const admins = filtered.filter((r) => r.role === "admin");
  const allList = filtered;

  const hasActiveFilters = !!search || roleFilter !== "all" || statusFilter !== "all";

  const clearFilters = () => {
    setSearch("");
    setRoleFilter("all");
    setStatusFilter("all");
  };

  const handleApprove = async (userId: string) => {
    setActionLoading(userId);
    try {
      await invoke("approve", { user_id: userId });
      toast({ title: "Approved", description: "User can now access the platform." });
      load();
    } catch (e) {
      toast({ title: "Error", description: e.message, variant: "destructive" });
    }
    setActionLoading(null);
  };

  const handleReject = async (userId: string) => {
    setActionLoading(userId);
    try {
      await invoke("reject", { user_id: userId });
      toast({ title: "Rejected", description: "Account has been removed." });
      load();
    } catch (e) {
      toast({ title: "Error", description: e.message, variant: "destructive" });
    }
    setActionLoading(null);
  };

  const handleDelete = async (userId: string) => {
    if (!confirm("Delete this user permanently?")) return;
    setActionLoading(userId);
    try {
      await invoke("delete", { user_id: userId });
      toast({ title: "Deleted", description: "Account has been removed." });
      load();
    } catch (e) {
      toast({ title: "Error", description: e.message, variant: "destructive" });
    }
    setActionLoading(null);
  };

  const handleDemoteAdmin = async (row: UserRow) => {
    if (!confirm(`Remove admin privileges from ${row.full_name}?`)) return;
    setActionLoading(row.user_id);
    const { error } = await supabase
      .from("user_roles")
      .update({ role: "student" })
      .eq("id", row.role_id);
    if (error) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Admin removed", description: `${row.full_name} is now a student.` });
      load();
    }
    setActionLoading(null);
  };

  // Toggle paid access for a student: grant a 1-month (calendar) active
  // subscription or cancel the existing one. Admins pass subscriptions RLS via dedicated
  // policies.
  const handleTogglePaid = async (row: UserRow) => {
    setActionLoading(row.user_id);
    try {
      const sub = paidSubs[row.user_id];
      if (sub?.status === "active") {
        const { error } = await supabase
          .from("subscriptions")
          .update({ status: "cancelled", updated_at: new Date().toISOString() })
          .eq("id", sub.id);
        if (error) throw error;
        toast({ title: "Paid access revoked", description: `${row.full_name} is back on the free preview.` });
      } else {
        const { error } = await supabase.from("subscriptions").insert({
          user_id: row.user_id,
          plan_id: "monthly",
          status: "active",
          starts_at: new Date().toISOString(),
          ends_at: addMonths(new Date(), 1).toISOString(),
        });
        if (error) throw error;
        toast({ title: "Paid access granted", description: `${row.full_name} now has full access for 1 month.` });
      }
      load();
    } catch (e) {
      toast({ title: "Error", description: e.message, variant: "destructive" });
    }
    setActionLoading(null);
  };

  // Promote an approved student/parent to admin (admins pass user_roles RLS
  // via "Admins can manage all roles").
  const handleMakeAdmin = async (row: UserRow) => {
    if (!confirm(`Promote ${row.full_name} to admin? They will have full console access.`)) return;
    setActionLoading(row.user_id);
    const { error } = await supabase
      .from("user_roles")
      .update({ role: "admin" })
      .eq("id", row.role_id);
    if (error) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Promoted to admin", description: `${row.full_name} now has admin privileges.` });
      load();
    }
    setActionLoading(null);
  };

  const handlePromoteAdmin = async () => {
    if (!promoteEmail.trim()) return;
    setPromoting(true);
    try {
      const { data, error } = await supabase.functions.invoke("promote-admin", {
        body: { email: promoteEmail.trim() },
      });
      if (error || data?.error) {
        throw new Error(data?.error || error?.message || "Failed to promote user");
      }
      toast({ title: "Promoted", description: `${promoteEmail} is now an admin.` });
      setPromoteEmail("");
      setPromoteOpen(false);
      load();
    } catch (e) {
      toast({ title: "Error", description: e.message, variant: "destructive" });
    }
    setPromoting(false);
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEmail.trim() || !newFullName.trim() || !newPassword.trim()) return;
    setCreating(true);
    try {
      await invoke("create", {
        email: newEmail.trim(),
        full_name: newFullName.trim(),
        password: newPassword,
        role: newRole,
      });
      toast({ title: "Account created", description: `${newEmail.trim()} can now log in.` });
      setNewEmail(""); setNewFullName(""); setNewPassword(""); setNewRole("student");
      load();
    } catch (e) {
      toast({ title: "Error", description: e.message, variant: "destructive" });
    }
    setCreating(false);
  };

  const handleResetPassword = async () => {
    if (!resetTarget || resetPassword.length < 6) return;
    setResetting(true);
    try {
      await invoke("update_credentials", { user_id: resetTarget.user_id, password: resetPassword });
      toast({
        title: "Password reset",
        description: `Password updated for ${resetTarget.username || resetTarget.full_name}.`,
      });
      setResetTarget(null); setResetPassword("");
    } catch (e) {
      toast({ title: "Error", description: e.message, variant: "destructive" });
    }
    setResetting(false);
  };

  const handleAssignUsername = async () => {
    if (!usernameTarget) return;
    const trimmed = usernameValue.trim().toLowerCase();
    if (trimmed && !/^[a-zA-Z0-9._-]{3,32}$/.test(trimmed)) {
      toast({
        title: "Invalid username",
        description: "Use 3–32 letters, numbers, dots, dashes or underscores.",
        variant: "destructive",
      });
      return;
    }
    setAssigningUsername(true);
    const { data, error } = await supabase.functions.invoke("manage-accounts", {
      body: { action: "set_identity", user_id: usernameTarget.user_id, username: trimmed },
    });
    const fnError = (data as { error?: string } | null)?.error;
    if (error || fnError) {
      toast({
        title: "Could not assign username",
        description: fnError ?? error?.message ?? "Please try again.",
        variant: "destructive",
      });
    } else {
      toast({
        title: trimmed ? "Username assigned" : "Username cleared",
        description: trimmed
          ? `${usernameTarget.full_name} can now log in with "${trimmed}".`
          : `Username removed for ${usernameTarget.full_name}.`,
      });
      setUsernameTarget(null);
      setUsernameValue("");
      load();
    }
    setAssigningUsername(false);
  };


  const openReports = async (student: UserRow) => {
    setReportsStudent(student);
    setLoadingReports(true);
    const { data, error } = await supabase
      .from("weekly_reports")
      .select("*")
      .eq("student_user_id", student.user_id)
      .order("uploaded_at", { ascending: false });
    // Otherwise the dialog presented an empty report list over a failed read.
    if (error) {
      toast({ title: "Could not load reports", description: error.message, variant: "destructive" });
      setReports([]);
      setLoadingReports(false);
      return;
    }
    setReports((data ?? []) as WeeklyReport[]);
    setLoadingReports(false);
  };

  const uploadReport = async () => {
    if (!file || !reportsStudent || !user) return;
    setUploading(true);
    const check = validateUploadFile(file);
    if (check.ok === false) {
      toast({ title: "Upload blocked", description: check.error, variant: "destructive" });
      setUploading(false);
      return;
    }
    const ext = getSafeUploadExtension(file);
    if (!ext) {
      toast({ title: "Upload blocked", description: "Unsupported file type.", variant: "destructive" });
      setUploading(false);
      return;
    }
    const path = `weekly-reports/${reportsStudent.user_id}/${Date.now()}.${ext}`;
    const { error: uploadErr } = await supabase.storage.from("homework-uploads").upload(path, file);
    if (uploadErr) {
      toast({ title: "Upload failed", description: uploadErr.message, variant: "destructive" });
      setUploading(false);
      return;
    }
    const { error } = await supabase.from("weekly_reports").insert({
      student_user_id: reportsStudent.user_id,
      file_url: path,
      file_name: file.name,
      week_label: weekLabel || null,
      uploaded_by: user.id,
    });
    if (error) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Report uploaded!" });
      setFile(null); setWeekLabel("");
      openReports(reportsStudent);
    }
    setUploading(false);
  };

  const downloadReport = async (report: WeeklyReport) => {
    const { data, error } = await supabase.storage
      .from("homework-uploads")
      .createSignedUrl(report.file_url, 3600);
    if (error || !data?.signedUrl) {
      toast({ title: "Could not open file", description: error?.message, variant: "destructive" });
      return;
    }
    window.open(data.signedUrl, "_blank", "noopener,noreferrer");
  };

  const deleteReport = async (report: WeeklyReport) => {
    await supabase.from("weekly_reports").delete().eq("id", report.id);
    await supabase.storage.from("homework-uploads").remove([report.file_url]);
    if (reportsStudent) openReports(reportsStudent);
    toast({ title: "Report deleted" });
  };

  const renderActions = (r: UserRow) => {
    if (!r.is_approved && r.role !== "admin") {
      return (
        <>
          <Button
            size="sm"
            className="gap-1"
            disabled={actionLoading === r.user_id}
            onClick={() => handleApprove(r.user_id)}
          >
            {actionLoading === r.user_id
              ? <Loader2 className="h-4 w-4 animate-spin" />
              : <UserCheck className="h-4 w-4" />}
            Approve
          </Button>
          <Button
            size="sm"
            variant="destructive"
            className="gap-1"
            disabled={actionLoading === r.user_id}
            onClick={() => handleReject(r.user_id)}
          >
            <UserX className="h-4 w-4" /> Reject
          </Button>
        </>
      );
    }
    if (r.role === "admin") {
      return (
        <Button
          size="sm"
          variant="destructive"
          className="gap-1"
          disabled={actionLoading === r.user_id || r.user_id === user?.id}
          onClick={() => handleDemoteAdmin(r)}
        >
          <Trash2 className="h-4 w-4" />
          {r.user_id === user?.id ? "You" : "Remove Admin"}
        </Button>
      );
    }
    return (
      <>
        {r.role === "student" && (
          <Button
            size="sm"
            variant="outline"
            className="gap-1"
            onClick={() => openReports(r)}
          >
            <FileText className="h-3.5 w-3.5" /> Reports
          </Button>
        )}
        {r.role === "student" && (
          paidSubs[r.user_id]?.status === "active" ? (
            <Button
              size="sm"
              variant="outline"
              className="gap-1 text-amber-600"
              disabled={actionLoading === r.user_id}
              onClick={() => handleTogglePaid(r)}
            >
              <CreditCard className="h-3.5 w-3.5" /> Revoke Paid
            </Button>
          ) : (
            <Button
              size="sm"
              variant="outline"
              className="gap-1 text-emerald-600"
              disabled={actionLoading === r.user_id}
              onClick={() => handleTogglePaid(r)}
            >
              <CreditCard className="h-3.5 w-3.5" /> Grant Paid
            </Button>
          )
        )}
        <Button
          size="sm"
          variant="outline"
          className="gap-1"
          disabled={actionLoading === r.user_id}
          onClick={() => handleMakeAdmin(r)}
        >
          <ShieldCheck className="h-4 w-4" /> Make Admin
        </Button>
        <Button
          size="sm"
          variant="outline"
          className="gap-1"
          onClick={() => { setUsernameTarget(r); setUsernameValue(r.username ?? ""); }}
        >
          <AtSign className="h-4 w-4" /> {r.username ? "Username" : "Assign"}
        </Button>
        <Button
          size="sm"
          variant="outline"
          className="gap-1"
          onClick={() => { setResetTarget(r); setResetPassword(""); }}
        >
          <KeyRound className="h-4 w-4" /> Reset
        </Button>
        <Button
          size="sm"
          variant="destructive"
          className="gap-1"
          disabled={actionLoading === r.user_id}
          onClick={() => handleDelete(r.user_id)}
        >
          {actionLoading === r.user_id
            ? <Loader2 className="h-4 w-4 animate-spin" />
            : <Trash2 className="h-4 w-4" />}
          Delete
        </Button>
      </>
    );
  };

  const UserTable = ({
    list,
    emptyText,
    emptyIcon: EmptyIcon,
    showStatus = false,
  }: {
    list: UserRow[];
    emptyText: string;
    emptyIcon: React.ElementType;
    showStatus?: boolean;
  }) =>
    loading ? (
      <div className="flex justify-center py-12">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    ) : list.length === 0 ? (
      <div className="flex flex-col items-center py-12">
        <EmptyIcon className="h-12 w-12 text-muted-foreground/50 mb-4" />
        <p className="text-muted-foreground">{emptyText}</p>
      </div>
    ) : (
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Username</TableHead>
            <TableHead>Full Name</TableHead>
            <TableHead>Role</TableHead>
            {showStatus && <TableHead>Status</TableHead>}
            <TableHead className="text-right">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {list.map((r) => (
            <TableRow key={r.role_id}>
              <TableCell className="font-medium">{r.email ?? r.username ?? "—"}</TableCell>
              <TableCell>{r.full_name}</TableCell>
              <TableCell>
                <span className="flex items-center gap-1.5">
                  <Badge
                    variant="secondary"
                    className={`capitalize ${r.role === "admin" ? "bg-primary/10 text-primary" : ""}`}
                  >
                    {r.role}
                  </Badge>
                  {paidSubs[r.user_id]?.status === "active" && (
                    <Badge variant="outline" className="text-emerald-600 border-emerald-600/30">Paid</Badge>
                  )}
                </span>
              </TableCell>
              {showStatus && (
                <TableCell>
                  {r.role === "admin" ? (
                    <Badge variant="outline">Admin</Badge>
                  ) : r.is_approved ? (
                    <Badge variant="outline" className="text-green-600 border-green-600/30">
                      Approved
                    </Badge>
                  ) : (
                    <Badge variant="outline" className="text-amber-600 border-amber-600/30">
                      Pending
                    </Badge>
                  )}
                </TableCell>
              )}
              <TableCell className="text-right space-x-2 whitespace-nowrap">
                {renderActions(r)}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    );

  return (
    <div className="space-y-6">
      <SEOHead
        title="Accounts — Admin Console"
        description="Approve signups, manage students, parents and admins, reset passwords, and upload weekly reports."
        path="/admin/accounts"
      />
      <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Accounts</h1>
          <p className="text-muted-foreground">
            Approve signups, manage students, parents &amp; admins, grant paid access, promote to admin, reset passwords, and upload weekly reports.
          </p>
        </div>
      </div>

      {/* Search + Filters */}
      <Card>
        <CardContent className="pt-4 pb-4 space-y-3">
          <div className="flex flex-col gap-3 lg:flex-row lg:items-center">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Search by name or email…"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-9"
              />
            </div>
            <div className="flex flex-wrap gap-2">
              <Select value={roleFilter} onValueChange={(v) => setRoleFilter(v as RoleFilter)}>
                <SelectTrigger className="w-[150px]">
                  <SelectValue placeholder="Role" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All roles</SelectItem>
                  <SelectItem value="student">Students</SelectItem>
                  <SelectItem value="parent">Parents</SelectItem>
                  <SelectItem value="admin">Admins</SelectItem>
                </SelectContent>
              </Select>
              <Select value={statusFilter} onValueChange={(v) => setStatusFilter(v as StatusFilter)}>
                <SelectTrigger className="w-[150px]">
                  <SelectValue placeholder="Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All statuses</SelectItem>
                  <SelectItem value="approved">Approved</SelectItem>
                  <SelectItem value="pending">Pending</SelectItem>
                </SelectContent>
              </Select>
              {hasActiveFilters && (
                <Button variant="ghost" size="sm" onClick={clearFilters} className="gap-1">
                  <X className="h-4 w-4" /> Clear
                </Button>
              )}
            </div>
          </div>
          <p className="text-xs text-muted-foreground">
            Showing {allList.length} of {rows.length} accounts
          </p>
        </CardContent>
      </Card>

      {failure && <QueryError message={failure} onRetry={load} />}

      <Tabs defaultValue={pending.length > 0 ? "pending" : "all"}>
        <TabsList className="flex-wrap h-auto">
          <TabsTrigger value="all" className="gap-2">
            <Users className="h-4 w-4" /> All {allList.length > 0 && `(${allList.length})`}
          </TabsTrigger>
          <TabsTrigger value="pending" className="gap-2">
            <Clock className="h-4 w-4" /> Pending {pending.length > 0 && `(${pending.length})`}
          </TabsTrigger>
          <TabsTrigger value="students" className="gap-2">
            <Users className="h-4 w-4" /> Students {students.length > 0 && `(${students.length})`}
          </TabsTrigger>
          <TabsTrigger value="parents" className="gap-2">
            <ShieldCheck className="h-4 w-4" /> Parents {parents.length > 0 && `(${parents.length})`}
          </TabsTrigger>
          <TabsTrigger value="admins" className="gap-2">
            <Shield className="h-4 w-4" /> Admins {admins.length > 0 && `(${admins.length})`}
          </TabsTrigger>
          <TabsTrigger value="create" className="gap-2">
            <UserPlus className="h-4 w-4" /> Create
          </TabsTrigger>
        </TabsList>

        <TabsContent value="all">
          <Card>
            <CardContent className="p-0">
              <UserTable
                list={allList}
                emptyIcon={Users}
                emptyText="No accounts match your filters"
                showStatus
              />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="pending">
          <Card>
            <CardContent className="p-0">
              <UserTable
                list={pending}
                emptyIcon={ShieldCheck}
                emptyText="No pending accounts"
              />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="students">
          <Card>
            <CardContent className="p-0">
              <UserTable
                list={students}
                emptyIcon={Users}
                emptyText="No students yet"
              />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="parents">
          <Card>
            <CardContent className="p-0">
              <UserTable
                list={parents}
                emptyIcon={Users}
                emptyText="No parents yet"
              />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="admins">
          <Card>
            <CardContent className="p-4 space-y-4">
              <div className="flex items-center justify-between">
                <p className="text-sm text-muted-foreground">
                  {admins.length} admin{admins.length === 1 ? "" : "s"}
                </p>
                <Button size="sm" className="gap-2" onClick={() => setPromoteOpen(true)}>
                  <UserPlus className="h-4 w-4" /> Promote Admin
                </Button>
              </div>
              <div className="border rounded-md">
                <UserTable
                  list={admins}
                  emptyIcon={Shield}
                  emptyText="No admins found"
                />
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="create">
          <Card>
            <CardContent className="pt-6">
              <form onSubmit={handleCreate} className="space-y-4 max-w-md">
                <div className="space-y-2">
                  <Label>Email</Label>
                  <Input
                    type="email"
                    placeholder="user@example.com"
                    value={newEmail}
                    onChange={(e) => setNewEmail(e.target.value)}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label>Full Name</Label>
                  <Input
                    placeholder="John Doe"
                    value={newFullName}
                    onChange={(e) => setNewFullName(e.target.value)}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label>Password</Label>
                  <Input
                    type="password"
                    placeholder="Min. 6 characters"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    required
                    minLength={6}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Role</Label>
                  <Select value={newRole} onValueChange={setNewRole}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="student">Student</SelectItem>
                      <SelectItem value="parent">Parent</SelectItem>
                    </SelectContent>
                  </Select>
                  <p className="text-xs text-muted-foreground">
                    To create an admin, create a student/parent account first, then promote it from the Admins tab.
                  </p>
                </div>
                <Button type="submit" disabled={creating} className="gap-2">
                  {creating && <Loader2 className="h-4 w-4 animate-spin" />}
                  Create Account
                </Button>
              </form>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Promote Admin Dialog */}
      <Dialog open={promoteOpen} onOpenChange={setPromoteOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Promote User to Admin</DialogTitle>
            <DialogDescription>
              Enter the email of an existing user to grant them admin privileges.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-2">
            <Label>User Email</Label>
            <Input
              placeholder="user@example.com"
              value={promoteEmail}
              onChange={(e) => setPromoteEmail(e.target.value)}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setPromoteOpen(false)}>Cancel</Button>
            <Button
              onClick={handlePromoteAdmin}
              disabled={promoting || !promoteEmail.trim()}
              className="gap-2"
            >
              {promoting && <Loader2 className="h-4 w-4 animate-spin" />}
              Promote to Admin
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Assign Username Dialog */}
      <Dialog open={!!usernameTarget} onOpenChange={(open) => { if (!open) setUsernameTarget(null); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Assign Username</DialogTitle>
            <DialogDescription>
              Choose a username for <strong>{usernameTarget?.full_name}</strong>. They'll be able to log in with this username or their email.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-2">
            <Label>Username</Label>
            <Input
              placeholder="e.g. john.doe"
              value={usernameValue}
              onChange={(e) => setUsernameValue(e.target.value)}
              autoFocus
            />
            <p className="text-xs text-muted-foreground">
              Lowercase letters, numbers, dots, dashes and underscores. Leave blank to remove.
            </p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setUsernameTarget(null)}>Cancel</Button>
            <Button onClick={handleAssignUsername} disabled={assigningUsername} className="gap-2">
              {assigningUsername && <Loader2 className="h-4 w-4 animate-spin" />}
              Save
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Reset Password Dialog */}
      <Dialog open={!!resetTarget} onOpenChange={(open) => { if (!open) setResetTarget(null); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Reset Password</DialogTitle>
            <DialogDescription>
              Set a new password for <strong>{resetTarget?.username || resetTarget?.full_name}</strong>.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-2">
            <Label>New Password</Label>
            <Input
              type="password"
              placeholder="Min. 6 characters"
              value={resetPassword}
              onChange={(e) => setResetPassword(e.target.value)}
              minLength={6}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setResetTarget(null)}>Cancel</Button>
            <Button
              onClick={handleResetPassword}
              disabled={resetting || resetPassword.length < 6}
              className="gap-2"
            >
              {resetting && <Loader2 className="h-4 w-4 animate-spin" />}
              Reset Password
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Weekly Reports Dialog */}
      <Dialog
        open={!!reportsStudent}
        onOpenChange={(open) => {
          if (!open) { setReportsStudent(null); setFile(null); setWeekLabel(""); }
        }}
      >
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Weekly Reports — {reportsStudent?.full_name}</DialogTitle>
            <DialogDescription>
              Upload and manage weekly progress reports for this student.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 border rounded-lg p-4 bg-muted/30">
            <Label className="font-medium">Upload New Report</Label>
            <div className="flex flex-col sm:flex-row gap-3">
              <Input
                placeholder="Week label (e.g. Week 12)"
                value={weekLabel}
                onChange={(e) => setWeekLabel(e.target.value)}
                className="sm:w-44"
              />
              <input
                ref={fileRef}
                type="file"
                className="hidden"
                onChange={(e) => setFile(e.target.files?.[0] ?? null)}
              />
              <Button
                size="sm"
                variant="outline"
                onClick={() => fileRef.current?.click()}
                className="gap-2"
              >
                <Upload className="h-3.5 w-3.5" /> {file ? file.name : "Choose File"}
              </Button>
              <Button size="sm" onClick={uploadReport} disabled={!file || uploading} className="gap-2">
                {uploading ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Upload className="h-3.5 w-3.5" />}
                Upload
              </Button>
            </div>
          </div>

          {loadingReports ? (
            <div className="flex justify-center py-8">
              <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
            </div>
          ) : reports.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-6">
              No reports uploaded yet.
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Week</TableHead>
                  <TableHead>File</TableHead>
                  <TableHead>Uploaded</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {reports.map((r) => (
                  <TableRow key={r.id}>
                    <TableCell className="font-medium">{r.week_label || "—"}</TableCell>
                    <TableCell className="text-sm truncate max-w-[200px]">{r.file_name}</TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {new Date(r.uploaded_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right space-x-2">
                      <Button size="sm" variant="outline" className="gap-1" aria-label={`Download report ${r.week_label || r.file_name}`} title="Download report" onClick={() => downloadReport(r)}>
                        <Download className="h-3 w-3" />
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        className="gap-1 text-destructive"
                        aria-label={`Delete report ${r.week_label || r.file_name}`}
                        title="Delete report"
                        onClick={() => deleteReport(r)}
                      >
                        <Trash2 className="h-3 w-3" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

// AI paper auto-correction worker — the paid "upload your solved paper and have
// it marked" service.
//
// Accepts either typed answers, uploaded photographs/PDF scans of a handwritten
// script, or both, and returns a mark-scheme breakdown per question.
//
// Access, in order:
//   1. 401 — no bearer token / invalid session.
//   2. 403 "Account not yet approved" — the approval gate every student
//      function shares.
//   3. 403 "plan_required" — no active subscription (admins exempt). This is
//      the paid gate; `has_active_plan()` is the single source of truth and it
//      is checked *here*, not in the browser, because the browser is not a
//      security boundary.
//
// Then: read the answer scripts out of the private `homework-uploads` bucket
// (service role, restricted to the caller's own folder), mark them with a
// Gemini model (Workers AI when AI_PROVIDER=cloudflare), audit-log the correction, and persist the result.
//
// Two audit facts worth knowing: `ai_audit_log.action` for this work is
// 'paper_correction' (the CHECK constraint that omitted it is fixed by
// 20261008140000), and a failed audit write must never lose a student's marks.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.4";
import { normaliseMarks, questionList } from "./marks.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-cm-timeout-ms",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

// Marking provider. Gemini is the default; AI_PROVIDER=cloudflare restores
// Workers AI (and its vision chain) without a code change.
const PROVIDER = Deno.env.get("AI_PROVIDER") || "gemini";

// Workers AI retires models; a stale or bare name is rejected outright
// ("No such model"). `llama-3.1-8b-instruct` was deprecated on 2026-05-30 and
// older clients still send its short name, so map known names and default.
const MODEL_ALIASES: Record<string, string> = {
  "llama-3.1-8b-instruct": "@cf/meta/llama-3.1-8b-instruct-fp8",
  "@cf/meta/llama-3.1-8b-instruct": "@cf/meta/llama-3.1-8b-instruct-fp8",
  "llama-3.1-8b-instruct-fp8": "@cf/meta/llama-3.1-8b-instruct-fp8",
  "llama-3.3-70b-instruct-fp8-fast": "@cf/meta/llama-3.3-70b-instruct-fp8-fast",
};
const DEFAULT_CF_MODEL = Deno.env.get("CLOUDFLARE_MODEL") ||
  "@cf/meta/llama-3.3-70b-instruct-fp8-fast";

/**
 * Multimodal models to try, in order, when the script is a photograph.
 *
 * There is no way to ask the API which vision models this account has, and
 * Workers AI both retires and adds them, so this is a candidate list with
 * fallback rather than one pinned id: the first that answers is remembered for
 * the rest of the isolate's life. `CLOUDFLARE_VISION_MODEL` overrides it.
 */
const VISION_MODEL_CANDIDATES: string[] = [
  Deno.env.get("CLOUDFLARE_VISION_MODEL") ?? "",
  "@cf/meta/llama-4-scout-17b-16e-instruct",
  "@cf/meta/llama-3.2-11b-vision-instruct",
  "@cf/google/gemma-3-12b-it",
  "@cf/mistralai/mistral-small-3.1-24b-instruct",
  "@cf/llava-hf/llava-1.5-7b-hf",
].filter((m) => m.trim().length > 0);

/** Answer scripts live in the same private bucket as homework uploads. */
const ANSWER_BUCKET = "homework-uploads";
const MAX_ANSWER_FILES = 6;
const MAX_ANSWER_TOTAL_BYTES = 20 * 1024 * 1024;
/** Cap on extracted PDF text handed to the model, so a huge paper still fits. */
const MAX_EXTRACTED_CHARS = 24_000;
/**
 * The published mark schemes live in the same private bucket as the papers.
 * They are text-layer PDFs; the question papers are scans, so only the mark
 * scheme can be read (see `loadMarkScheme`).
 */
const PAPER_BUCKET = "past-papers";
const MAX_MARK_SCHEME_CHARS = 30_000;
/** Under this a "mark scheme" is a scan or a stray file, not text worth sending. */
const MIN_MARK_SCHEME_CHARS = 200;

const IMAGE_EXTENSIONS = new Set(["png", "jpg", "jpeg", "webp", "gif", "heic"]);
const MIME_BY_EXTENSION: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  gif: "image/gif",
  heic: "image/heic",
};

interface AnswerFile {
  bucket: string;
  path: string;
  name?: string | null;
  mimeType?: string | null;
}

interface CorrectedPaper {
  question: string;
  original_answer: string;
  correct_answer: string;
  marks_earned: number;
  total_marks: number;
  feedback: string;
  grade: number;
  comment: string;
  watermark: string;
  audit_ref: string;
}

/** Accept a full `@cf/...` id, map a legacy/short name, else fall back. */
function resolveModel(raw: unknown): string {
  if (typeof raw === "string" && raw.trim()) {
    const name = raw.trim();
    if (MODEL_ALIASES[name]) return MODEL_ALIASES[name];
    if (name.startsWith("@cf/")) return name;
  }
  return DEFAULT_CF_MODEL;
}

type ChatMessage = { role: string; content: string | unknown[] };

/**
 * Cloudflare Workers AI.
 *
 * Uses `/ai/run/<model>` (the standard envelope) rather than the
 * OpenAI-compatible route, and returns the raw `response`: some models answer
 * with a JSON string while others hand back an already-parsed object, so both
 * shapes must be tolerated downstream. `messages` may carry multimodal content
 * arrays (a text part plus `image_url` parts) for the vision models.
 */
async function callCloudflareAI(
  model: string,
  messages: ChatMessage[],
  maxTokens = 6144,
): Promise<unknown> {
  const apiKey = Deno.env.get("CLOUDFLARE_API_KEY");
  const accountId = Deno.env.get("CLOUDFLARE_ACCOUNT_ID");
  if (!apiKey) throw new Error("CLOUDFLARE_API_KEY not set");
  if (!accountId) throw new Error("CLOUDFLARE_ACCOUNT_ID not set");
  const res = await fetch(
    `https://api.cloudflare.com/client/v4/accounts/${accountId}/ai/run/${model}`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      // Low temperature: marking must be deterministic — the same script
      // marked twice should get the same marks. Creativity here is a bug.
      body: JSON.stringify({ messages, max_tokens: maxTokens, temperature: 0.2 }),
    },
  );
  if (!res.ok) {
    const detail = await res.text().catch(() => "");
    throw new Error(`Cloudflare AI error: ${res.status} ${detail.slice(0, 300)}`);
  }
  const data = await res.json();
  if (data.success === false) {
    throw new Error(
      `Cloudflare AI error: ${JSON.stringify(data.errors ?? data).slice(0, 300)}`,
    );
  }
  return data.result?.response ?? "";
}

/**
 * Google Gemini, through the generativelanguage REST API.
 *
 * The key travels in the x-goog-api-key header, never in the URL, so it cannot
 * land in an access log. One multimodal model reads typed text and page photos
 * alike, so this path has no vision fallback chain. `messages` keeps the shape
 * the Cloudflare path uses; geminiParts converts it.
 */
const GEMINI_MODEL = Deno.env.get("GEMINI_MODEL") || "gemini-3.8-flash";

function geminiParts(content: string | unknown[]): unknown[] {
  if (typeof content === "string") return [{ text: content }];
  return content.map((part: any) => {
    if (part?.type === "image_url") {
      const match = /^data:([^;]+);base64,([A-Za-z0-9+/=]+)$/.exec(
        String(part.image_url?.url ?? ""),
      );
      if (!match) throw new Error("Uploaded page image was not a base64 data URL");
      return { inline_data: { mime_type: match[1], data: match[2] } };
    }
    return { text: String(part?.text ?? "") };
  });
}

async function callGemini(
  messages: ChatMessage[],
): Promise<{ text: string; model: string }> {
  const apiKey = Deno.env.get("GEMINI_API_KEY");
  if (!apiKey) throw new Error("GEMINI_API_KEY not set");
  const system = messages
    .filter((m) => m.role === "system")
    .map((m) => String(m.content))
    .join("\n\n");
  const contents = messages
    .filter((m) => m.role !== "system")
    .map((m) => ({
      role: m.role === "assistant" ? "model" : "user",
      parts: geminiParts(m.content),
    }));
  const res = await fetch(
    "https://generativelanguage.googleapis.com/v1beta/models/" +
      GEMINI_MODEL + ":generateContent",
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-goog-api-key": apiKey,
      },
      // Low temperature for the same reason as Workers AI: marks must repeat.
      body: JSON.stringify({
        systemInstruction: { parts: [{ text: system }] },
        contents,
        generationConfig: {
          temperature: 0.2,
          maxOutputTokens: 8192,
          responseMimeType: "application/json",
        },
      }),
    },
  );
  if (!res.ok) {
    const detail = await res.text().catch(() => "");
    throw new Error("Gemini API error: " + res.status + " " + detail.slice(0, 300));
  }
  const data = await res.json();
  const candidate = data?.candidates?.[0];
  const parts: any[] = Array.isArray(candidate?.content?.parts)
    ? candidate.content.parts
    : [];
  const text = parts.map((p) => String(p?.text ?? "")).join("");
  if (!text.trim()) {
    const reason = candidate?.finishReason ??
      data?.promptFeedback?.blockReason ?? "no text returned";
    throw new Error("Gemini returned no marking text (" + reason + ")");
  }
  return { text, model: GEMINI_MODEL };
}

// Lovable / OpenAI-compatible fallback
async function callOpenAiCompat(
  model: string,
  messages: ChatMessage[],
): Promise<string> {
  const apiKey = Deno.env.get("OPENAI_API_KEY");
  if (!apiKey) throw new Error("OPENAI_API_KEY not set");
  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({ model, messages, max_tokens: 2048 }),
  });
  if (!res.ok) throw new Error(`OpenAI error: ${res.status}`);
  const data = await res.json();
  return data.choices?.[0]?.message?.content ?? "";
}

/** What the marker was given, so the prompt can say so. */
type SubmissionSource = "paste" | "upload" | "mixed";

const SYSTEM_PROMPT = `You are an expert examiner for Edexcel IAL and Cambridge IGCSE / AS / A-Level Mathematics (0580/9709), Physics (0625/9702) and Computer Science (0478/9618). Mark strictly, like a real examiner: every mark is evidence-based, never impression-based.

Read the student's answer, compare it against the mark scheme, and return a structured JSON array with one object per question.

Each object MUST have exactly these keys:
- question: the question text
- original_answer: what the student actually wrote (transcribe faithfully, do not tidy it up)
- correct_answer: the examiner's model answer from the mark scheme
- marks_earned: integer marks awarded
- total_marks: the question's total from its bracket (e.g. "(3)") or the mark scheme — never invent or rescale a total
- feedback: 1-2 sentences on what was right / what to fix, in a tutor's voice, kind but precise
- grade: percentage for this question (0-100)
- comment: 1-2 sentences on the grade

How marks work (Edexcel M/A/B; Cambridge method/accuracy equivalents):
- M (method): the correct method applied to the question — award it even when an arithmetic slip ruins the final answer.
- A (accuracy): the correct final answer from correct working, to the stated accuracy (significant figures, nearest integer, exact form). A wrong final answer loses the A mark, never the M marks already earned.
- B (independent): accuracy marks independent of method — award whenever the required result appears.
- Follow-through: an early error is penalised ONCE. Working that correctly follows through from the student's own (wrong) value still earns its method marks.
- A correct answer with no working earns full marks only if the scheme allows it; otherwise award the answer marks, withhold the method marks, and say so.

Anti-hallucination rules (hard requirements):
- QUOTE TO DEDUCT: every mark you withhold must be tied to a specific defect you QUOTE from the student's answer in feedback (their numbers, symbols or words), or to a blank/unattempted question you name as such. If you cannot point at the defect, award the mark.
- Do not invent requirements the question and scheme never set (working format, layout, extra steps, restating the question). Mark what is written.
- Do not downgrade correct mathematics: an equivalent form (unsimplified fraction, exact surd, a correct alternative method) earns full credit unless the question forbids it.
- Fill in correct_answer from the mark scheme even if the student got nothing.
- Never output anything except the JSON array.`;

const VISION_INSTRUCTIONS = `
The student's answers arrive as photographs or scans of their handwritten script.
- Transcribe each answer you can read before judging it, and use your transcription as original_answer.
- Handwriting is often ambiguous: if a value is genuinely illegible, say so in feedback and award no marks for it rather than guessing.
- The page images are the student's whole script, so find the question numbers on the page yourself.
- Answer every question you can identify, in question order.`;

/** Tolerate markdown fences, a JSON string, or an already-parsed value. */
function parseModelJson(text: unknown): unknown {
  if (typeof text === "object" && text !== null) return text;
  const cleaned = String(text ?? "")
    .trim()
    .replace(/^```(?:json)?/i, "")
    .replace(/```$/i, "")
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    const start = cleaned.indexOf("[");
    const end = cleaned.lastIndexOf("]");
    if (start !== -1 && end > start) {
      return JSON.parse(cleaned.slice(start, end + 1));
    }
    throw new Error("The marking model did not return valid JSON.");
  }
}

/** Stable hash of the submitted paper, for the audit log. */
async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

function extensionOf(pathOrName: string): string {
  const clean = pathOrName.split("?")[0].split("#")[0];
  const dot = clean.lastIndexOf(".");
  return dot === -1 ? "" : clean.slice(dot + 1).toLowerCase();
}

/* ─────────────────────── PDF text extraction (best effort) ─────────────── */

/**
 * Inflate a zlib stream. `DecompressionStream("deflate")` is RFC1950 (zlib),
 * which is what PDF FlateDecode streams use; returns null on any failure so a
 * single corrupt stream never sinks the whole extraction.
 */
async function inflate(bytes: Uint8Array): Promise<string | null> {
  try {
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("deflate"));
    const buf = new Uint8Array(await new Response(stream).arrayBuffer());
    return new TextDecoder("latin1").decode(buf);
  } catch {
    return null;
  }
}

/** Resolve PDF string escapes: \\( \\) \\\\ \n and octal \123. */
function unescapePdfString(raw: string): string {
  return raw.replace(/\\([nrtbf()\\]|[0-7]{1,3})/g, (_m, esc: string) => {
    switch (esc) {
      case "n": return "\n";
      case "r": return "\r";
      case "t": return "\t";
      case "b": return "\b";
      case "f": return "\f";
      case "(": return "(";
      case ")": return ")";
      case "\\": return "\\";
      default: return String.fromCharCode(parseInt(esc, 8));
    }
  });
}

/**
 * Best-effort plain text out of a text-layer PDF.
 *
 * Scanned scripts have no text layer and legitimately return "" — the caller
 * then tells the student to upload photographs instead. This is deliberately
 * small: no font metrics, no positioning, just "what words are on this page",
 * which is all the marker needs.
 */
/**
 * Text out of one `BT … ET` block, read from the text *operators*.
 *
 * Cambridge mark schemes are written as TJ arrays of glyph runs —
 * `[(C)-1(a)-1(m)-1(b)-1(ri)-1(dge)]TJ` — so treating every parenthesised
 * string as a word produced "C a m b r i d g e": 91-94% of the tokens were
 * single characters and the model's context went on spaces. The runs inside one
 * TJ array carry their own spacing, so they are concatenated; a text-positioning
 * operator (`Td`/`TD`/`T*`) is the only thing that opens a new line.
 */
function textFromTextBlock(block: string): string[] {
  const out: string[] = [];
  const operator = /\[([\s\S]*?)\]\s*TJ|\(((?:\\.|[^\\()])*)\)\s*Tj|\bT[dD*]\b/g;
  let match: RegExpExecArray | null;
  while ((match = operator.exec(block)) !== null) {
    const [whole, tjBody, tjString] = match;
    if (tjBody !== undefined) {
      const runs = tjBody.match(/\((?:\\.|[^\\()])*\)/g) ?? [];
      out.push(runs.map((literal) => unescapePdfString(literal.slice(1, -1))).join(""));
    } else if (tjString !== undefined) {
      out.push(unescapePdfString(tjString));
    } else if (whole === "Td" || whole === "TD" || whole === "T*") {
      out.push("\n");
    }
  }
  return out;
}

/** Walk every FlateDecode stream that carries a text block.
 *
 * Byte-level throughout, deliberately: `TextDecoder("latin1")` is NOT
 * byte-exact — WHATWG maps the label to windows-1252, so every byte in
 * 0x80–0x9F decodes to a C1 control's lookalike (0x93 becomes U+201C) and
 * `charCodeAt` can never rebuild the original bytes. Slicing the string and
 * inflating the rebuild corrupted every compressed stream that happened to
 * contain such a byte — i.e. essentially every real mark scheme — so scheme
 * grounding silently never loaded and the marker fell back to its own memory.
 * Only the inflated (or raw) *text* is ever decoded as a string.
 */
async function eachTextStream(
  bytes: Uint8Array,
  visit: (decoded: string) => void,
): Promise<void> {
  const STREAM = [0x73, 0x74, 0x72, 0x65, 0x61, 0x6d]; // "stream"
  const ENDSTREAM = [0x65, 0x6e, 0x64, 0x73, 0x74, 0x72, 0x65, 0x61, 0x6d]; // "endstream"
  const indexOf = (from: number, needle: number[]): number => {
    for (let i = from; i + needle.length <= bytes.length; i += 1) {
      let hit = true;
      for (let j = 0; j < needle.length; j += 1) {
        if (bytes[i + j] !== needle[j]) {
          hit = false;
          break;
        }
      }
      if (hit) return i;
    }
    return -1;
  };

  let searchFrom = 0;

  for (;;) {
    let start = indexOf(searchFrom, STREAM);
    // The spec requires an EOL right after `stream`: without it this is the
    // tail of an `endstream` (or binary data), not a stream boundary.
    while (
      start !== -1 &&
      bytes[start + STREAM.length] !== 0x0d &&
      bytes[start + STREAM.length] !== 0x0a
    ) {
      start = indexOf(start + 1, STREAM);
    }
    if (start === -1) break;
    const end = indexOf(start, ENDSTREAM);
    if (end === -1) break;
    searchFrom = end + ENDSTREAM.length;

    // Skip the EOL that must follow the `stream` keyword.
    let dataStart = start + STREAM.length;
    if (bytes[dataStart] === 0x0d) dataStart += 1;
    if (bytes[dataStart] === 0x0a) dataStart += 1;
    let dataEnd = end;
    if (bytes[dataEnd - 1] === 0x0a) dataEnd -= 1;
    if (bytes[dataEnd - 1] === 0x0d) dataEnd -= 1;
    if (dataEnd <= dataStart) continue;

    const chunk = bytes.subarray(dataStart, dataEnd);

    // Streams are usually Flate-compressed, but some are stored raw.
    const decoded = (await inflate(chunk)) ?? new TextDecoder("latin1").decode(chunk);
    if (!decoded.includes("BT")) continue;
    visit(decoded);
  }
}

async function extractPdfText(bytes: Uint8Array): Promise<string> {
  const pieces: string[] = [];
  await eachTextStream(bytes, (decoded) => {
    // Text lives inside BT … ET blocks.
    for (const block of decoded.match(/BT[\s\S]*?ET/g) ?? []) {
      pieces.push(...textFromTextBlock(block));
    }
  });

  // Pieces join with no separator. Removing every NUL is what the old
  // NUL-delimiter pass did, and a regex over control characters trips no-control-regex.
  return pieces
    .join("")
    .split("\n")
    .map((line) => line.replace(/[ \t]{2,}/g, " ").trim())
    .filter((line) => line.length > 0)
    .join("\n")
    .trim();
}

/* ───────────────────────── mark scheme grounding ──────────────────────── */

/**
 * The published mark scheme for the paper the student sat, read out of the
 * private `past-papers` bucket.
 *
 * Before this the worker marked from the model's own memory: `paperRef` named
 * the paper in the prompt, but nothing ever loaded its mark scheme, so "marked
 * against the mark scheme" was a promise the function could not keep — and a
 * student's method mark turned on whether the model happened to recall the
 * scheme. Best effort throughout: no paper named, no scheme on file, or a
 * scanned (text-less) PDF all fall back to the previous behaviour rather than
 * failing the marking.
 */
async function loadMarkScheme(
  admin: ReturnType<typeof createClient>,
  paperRef: { id?: string; markSchemeUrl?: string | null } | null,
): Promise<{ path: string; text: string } | null> {
  if (!paperRef) return null;

  let path = typeof paperRef.markSchemeUrl === "string" ? paperRef.markSchemeUrl.trim() : "";
  if (!path && paperRef.id) {
    const { data, error } = await admin
      .from("past_papers")
      .select("mark_scheme_url")
      .eq("id", paperRef.id)
      .maybeSingle();
    if (error) console.error("ai-correction: mark scheme lookup failed:", error.message);
    path = String(data?.mark_scheme_url ?? "").trim();
  }
  if (!path || !path.toLowerCase().endsWith(".pdf")) return null;
  // Accept a bare object path or a bucket-qualified one.
  path = path.replace(/^past-papers\//, "").replace(/^\/+/, "");

  const { data: blob, error: downloadError } = await admin.storage
    .from(PAPER_BUCKET)
    .download(path);
  if (downloadError || !blob) {
    console.error("ai-correction: mark scheme download failed:", path, downloadError?.message);
    return null;
  }

  const text = await extractPdfText(new Uint8Array(await blob.arrayBuffer()));
  if (text.length < MIN_MARK_SCHEME_CHARS) return null;
  console.log("ai-correction: mark scheme loaded:", path, text.length, "chars");
  return { path, text: text.slice(0, MAX_MARK_SCHEME_CHARS) };
}

/* ───────────────────────────── main handler ───────────────────────────── */

export async function handler(req: Request): Promise<Response> {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const json = (body: unknown, status = 200) =>
    new Response(JSON.stringify(body), {
      status,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) return json({ error: "Unauthorized" }, 401);

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } } },
    );
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return json({ error: "Unauthorized" }, 401);

    const admin = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    // ── gate 1: approval ────────────────────────────────────────────────
    const { data: roleRow } = await admin
      .from("user_roles")
      .select("is_approved, role")
      .eq("user_id", user.id)
      .maybeSingle();
    const isAdmin = roleRow?.role === "admin" && roleRow?.is_approved === true;
    if (!roleRow?.is_approved && roleRow?.role !== "admin") {
      return json({ error: "Account not yet approved" }, 403);
    }

    // ── gate 2: plan ────────────────────────────────────────────────────
    // Fail closed. If the helper is missing (migration not applied) this is a
    // 503 rather than a 403 so the failure is not misreported to a paying
    // student as "you need to upgrade".
    const { data: hasPlan, error: planError } = await admin.rpc("has_active_plan", {
      _user_id: user.id,
    });
    if (planError) {
      console.error("ai-correction: plan check failed:", planError.message);
      return json({ error: "AI marking is temporarily unavailable. Please try again shortly." }, 503);
    }
    if (!hasPlan) {
      return json({
        error: "AI marking is part of the full plan",
        message:
          "Upload a solved past paper and our AI examiner marks it, question by question, against the mark scheme. Upgrade to use it.",
        code: "plan_required",
        upgrade: true,
      }, 403);
    }

    // ── input ───────────────────────────────────────────────────────────
    const body = await req.json().catch(() => ({}));
    const { paper: rawPaper, model } = body;
    const subjectLevelId = body.subjectLevelId ?? null;

    const paperRef = (body.paperRef ?? null) as
      | {
        id?: string;
        title?: string;
        session?: string | null;
        year?: number | null;
        paperNumber?: string | null;
        markSchemeUrl?: string | null;
      }
      | null;

    const answerFiles: AnswerFile[] = (Array.isArray(body.answerFiles) ? body.answerFiles : [])
      .slice(0, MAX_ANSWER_FILES)
      .filter((f: any) => f && typeof f === "object")
      .map((f: any) => ({
        bucket: String(f.bucket ?? ""),
        path: String(f.path ?? ""),
        name: f.name ?? null,
        mimeType: f.mimeType ?? null,
      }));

    const hasTyped = typeof rawPaper === "string"
      ? rawPaper.trim().length > 0
      : Array.isArray(rawPaper) && rawPaper.length > 0;

    if (!hasTyped && answerFiles.length === 0) {
      return json({ error: "Nothing to mark — write or upload your answers first." }, 400);
    }

    // ── read the uploaded scripts ───────────────────────────────────────
    // Two checks, both server-side: the bucket is ours, and the object is
    // inside the caller's own folder. Without the second one a student could
    // ask us to download and mark another account's upload.
    const images: { dataUrl: string; name: string }[] = [];
    const pdfTexts: string[] = [];
    const acceptedFiles: AnswerFile[] = [];
    let totalBytes = 0;

    for (const file of answerFiles) {
      if (file.bucket !== ANSWER_BUCKET) {
        return json({ error: "Unsupported answer file location." }, 400);
      }
      const prefix = `${user.id}/`;
      if (!file.path.startsWith(prefix) || file.path.includes("..")) {
        return json({ error: "Unsupported answer file location." }, 403);
      }

      const { data: blob, error: downloadError } = await admin.storage
        .from(ANSWER_BUCKET)
        .download(file.path);
      if (downloadError || !blob) {
        console.error("ai-correction: download failed:", file.path, downloadError?.message);
        return json({ error: `Could not read one of your uploads (${file.name ?? file.path}).` }, 400);
      }
      totalBytes += blob.size;
      if (totalBytes > MAX_ANSWER_TOTAL_BYTES) {
        return json({
          error: "Those uploads are too large to mark together — try fewer or smaller pages.",
        }, 413);
      }

      const ext = extensionOf(file.name ?? file.path);
      const isPdf = ext === "pdf" || file.mimeType === "application/pdf";
      const isImage = IMAGE_EXTENSIONS.has(ext) || String(file.mimeType ?? "").startsWith("image/");

      if (isImage) {
        const mime = file.mimeType?.startsWith("image/")
          ? file.mimeType
          : MIME_BY_EXTENSION[ext] ?? "image/jpeg";
        const bytes = new Uint8Array(await blob.arrayBuffer());
        let binary = "";
        for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i]);
        images.push({
          dataUrl: `data:${mime};base64,${btoa(binary)}`,
          name: file.name ?? file.path,
        });
      } else if (isPdf) {
        const extracted = await extractPdfText(new Uint8Array(await blob.arrayBuffer()));
        if (extracted) pdfTexts.push(extracted);
      } else {
        return json({
          error: `We can mark PDFs and photos of your script, not ${ext || "that file type"}.`,
        }, 415);
      }
      acceptedFiles.push(file);
    }

    const source: SubmissionSource = images.length + pdfTexts.length > 0
      ? (hasTyped ? "mixed" : "upload")
      : "paste";

    if (source !== "paste" && images.length === 0 && pdfTexts.length === 0) {
      return json({
        error:
          "We couldn't read any text from that PDF — it looks like a scan. Upload photographs of your pages instead, or type your answers.",
      }, 422);
    }

    // ── marking context ─────────────────────────────────────────────────
    let rubric = "";
    if (subjectLevelId) {
      const { data: levelRow } = await supabase
        .from("subject_levels")
        .select("subject_id, level")
        .eq("id", subjectLevelId)
        .single();
      const { data: subjectRows } = await supabase
        .from("subjects")
        .select("id, name, slug")
        .in("id", levelRow ? [levelRow.subject_id] : []);
      const subject = subjectRows?.[0];
      rubric = `
## Subject context
- Subject: ${subject?.name ?? "IGCSE / AS / A-Level"}
- Level: ${levelRow?.level ?? ""}

Mark scheme style:
- Award marks only for correct methods and final answers.
- Partial credit for correct steps even if the final answer is wrong.
- Deduct marks with a one-line explanation.`;
    }

    if (paperRef && (paperRef.title || paperRef.paperNumber)) {
      const descriptor = [
        paperRef.title,
        paperRef.session ?? undefined,
        paperRef.year ? String(paperRef.year) : undefined,
        paperRef.paperNumber ?? undefined,
      ].filter(Boolean).join(" · ");
      rubric += `
## Paper being sat
- ${descriptor}
- Mark the student's answers against this paper's mark scheme for the questions they attempted.`;
    }

    const typedText = hasTyped
      ? (Array.isArray(rawPaper)
        ? rawPaper.map((p: any) =>
          `Q: ${p.question || "Question " + (p.idx ?? "")}\nStudent answer: ${p.answer || p.text || ""}`
        ).join("\n\n---\n\n")
        : String(rawPaper))
      : "";

    const textSections: string[] = [rubric];

    // The mark scheme is the authority the marks are awarded against, so it
    // goes in ahead of the student's answers.
    const markScheme = await loadMarkScheme(admin, paperRef);
    if (markScheme) {
      textSections.push(
        `## Official mark scheme for this paper (authoritative)\n` +
          `Award marks exactly as it specifies: the per-question totals, method (M) marks, ` +
          `accuracy (A) marks and follow-through. If the student's working matches an ` +
          `acceptable answer listed here, award the marks even when the wording differs. ` +
          `If a question they answered is not covered by this extract, mark it from your own ` +
          `knowledge of the syllabus and say so in the feedback.\n\n${markScheme.text}`,
      );
    }

    if (typedText.trim()) {
      textSections.push(`## The paper to correct (typed by the student)\n${typedText}`);
    }
    for (const [index, text] of pdfTexts.entries()) {
      textSections.push(
        `## Uploaded script ${index + 1} (text extracted from PDF, may be in page order with layout artefacts)\n${
          text.slice(0, MAX_EXTRACTED_CHARS)
        }`,
      );
    }
    if (images.length > 0) {
      textSections.push(
        `## Uploaded script (${images.length} page image${images.length === 1 ? "" : "s"} attached, in order)`,
      );
    }
    textSections.push("## Instructions\nReturn ONLY a JSON array. No markdown fences, no explanations outside the JSON.");

    const fullPrompt = textSections.filter(Boolean).join("\n\n");
    const systemPrompt = images.length > 0 ? SYSTEM_PROMPT + VISION_INSTRUCTIONS : SYSTEM_PROMPT;

    // ── call the model ──────────────────────────────────────────────────
    const requestedModel = typeof model === "string" && model.trim() ? model.trim() : "";
    const textModel = PROVIDER === "gemini"
      ? GEMINI_MODEL
      : PROVIDER === "cloudflare"
      ? resolveModel(requestedModel)
      : (requestedModel || "gpt-4o-mini");

    // Text-only prompts stay plain strings; a photographed script adds one
    // image_url part per page, in order. Both providers read this shape.
    const multimodalMessages: ChatMessage[] = [
      { role: "system", content: systemPrompt },
      {
        role: "user",
        content: images.length > 0
          ? [
              { type: "text", text: fullPrompt },
              ...images.map((img) => ({
                type: "image_url",
                image_url: { url: img.dataUrl },
              })),
            ]
          : fullPrompt,
      },
    ];

    let llmOutput: unknown;
    let modelName = textModel;

    if (PROVIDER === "gemini") {
      const gemini = await callGemini(multimodalMessages);
      llmOutput = gemini.text;
      modelName = gemini.model;
    } else if (images.length > 0 && PROVIDER === "cloudflare") {
      // Keep every candidate's failure, not just the last one: the chain ends
      // with older models whose payload shape differs, so the final error used
      // to be the least informative one. The detail stays server-side (the
      // handler below answers a generic 502), which is what makes it safe to
      // name the models here.
      const visionFailures: string[] = [];
      for (const candidate of visionModelCandidates()) {
        try {
          llmOutput = await callCloudflareAI(candidate, multimodalMessages);
          modelName = candidate;
          cachedVisionModel = candidate;
          break;
        } catch (error) {
          const detail = error instanceof Error ? error.message : String(error);
          visionFailures.push(`${candidate}: ${detail}`);
          console.error("ai-correction: vision model failed:", candidate, detail);
        }
      }
      if (llmOutput === undefined) {
        throw new Error(
          `No vision model was available to read the upload (${visionFailures
            .join(" | ")
            .slice(0, 600)}).`,
        );
      }
    } else if (PROVIDER === "cloudflare") {
      llmOutput = await callCloudflareAI(textModel, [
        { role: "system", content: systemPrompt },
        { role: "user", content: fullPrompt },
      ]);
      modelName = textModel;
    } else {
      llmOutput = await callOpenAiCompat(textModel, [
        { role: "system", content: systemPrompt },
        { role: "user", content: fullPrompt },
      ]);
      modelName = textModel;
    }

    const parsed = questionList(parseModelJson(llmOutput));
    if (!parsed || parsed.length === 0) {
      throw new Error("The marking model returned no usable results. Please try again.");
    }

    const auditRef = crypto.randomUUID();

    const corrected: CorrectedPaper[] = parsed.map((raw: any, idx: number) => {
      // Bounded to 0..total_marks: a stray model value must never give a
      // negative mark or a grade above 100% (see marks.ts).
      const marks = normaliseMarks(raw);
      return {
        question: String(raw?.question ?? `Question ${idx + 1}`),
        original_answer: String(raw?.original_answer ?? ""),
        correct_answer: String(raw?.correct_answer ?? ""),
        marks_earned: marks.marks_earned,
        total_marks: marks.total_marks,
        feedback: String(raw?.feedback ?? ""),
        grade: marks.grade,
        comment: String(raw?.comment ?? ""),
        watermark: `Clutch Marks · AI-marked · ${auditRef.slice(0, 8)}`,
        audit_ref: auditRef,
      };
    });

    const totalPossible = corrected.reduce((s, q) => s + q.total_marks, 0);
    const totalEarned = corrected.reduce((s, q) => s + q.marks_earned, 0);
    const overallGrade = totalPossible > 0
      ? Math.round((totalEarned / totalPossible) * 100)
      : 0;

    // Audit log is written with the service role: students never write here.
    const inputHash = await sha256Hex(
      `${fullPrompt}\n\n[files] ${acceptedFiles.map((f) => f.path).join(",")}`,
    );
    const { error: auditError } = await admin.from("ai_audit_log").insert({
      user_id: user.id,
      action: "paper_correction",
      input_hash: inputHash,
      model: modelName,
      provider: PROVIDER,
      output_preview: JSON.stringify(corrected).slice(0, 2000),
      grade: overallGrade,
      corrected_paper: corrected,
      cost_cents: 0,
    });
    // A failed audit write must not lose the student's marking.
    if (auditError) console.error("ai-correction audit log failed:", auditError.message);

    // Persist the marked script so the student can revisit it. Also non-fatal.
    const { error: persistError } = await admin.from("ai_correction").insert({
      user_id: user.id,
      subject_level_id: subjectLevelId ?? null,
      paper_text: typedText.slice(0, 20_000) || null,
      corrected_papers: corrected,
      overall_grade: overallGrade,
      total_possible: totalPossible,
      total_earned: totalEarned,
      audit_ref: auditRef,
      model: modelName,
      source,
      answer_files: acceptedFiles.length
        ? acceptedFiles.map((f) => ({ bucket: f.bucket, path: f.path, name: f.name ?? null }))
        : null,
      paper_ref: paperRef ?? null,
    });
    if (persistError) console.error("ai-correction persist failed:", persistError.message);

    return json({
      corrected_papers: corrected,
      overall_grade: overallGrade,
      total_possible: totalPossible,
      total_earned: totalEarned,
      audit_ref: auditRef,
      source,
      model: modelName,
      watermark: `Clutch Marks · AI-marked · ${auditRef.slice(0, 8)}`,
      // Whether this marking had the paper's published mark scheme to work
      // from — a wrong key here is the difference between a method mark and a
      // lost one, and the probe asserts it.
      mark_scheme: markScheme
        ? { loaded: true, chars: markScheme.text.length }
        : { loaded: false, chars: 0 },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unexpected error";
    // The detail goes to the function log, never to the student: an upstream
    // body like "Cloudflare AI error: 429 …10,000 neurons" is useless to them.
    console.error("ai-correction failed:", message);
    // A 429 is capacity, not a broken script: Workers AI's free daily neuron
    // allocation running out, or a Gemini rate limit. Say so; marking can be retried.
    if (/\b429\b|daily free allocation|neurons/i.test(message)) {
      return json({
        error: "The AI marker is at capacity right now. Nothing was lost — please try again in a little while.",
        code: "ai_busy",
      }, 503);
    }
    return json({
      error:
        "The AI marker could not finish marking that script. Nothing was lost — please try again, and report it on the feedback page if it keeps happening.",
      code: "ai_failed",
    }, 502);
  }
}

/** The first vision model that worked in this isolate, tried first thereafter. */
let cachedVisionModel: string | null = null;

function visionModelCandidates(): string[] {
  const rest = VISION_MODEL_CANDIDATES.filter((m) => m !== cachedVisionModel);
  return cachedVisionModel ? [cachedVisionModel, ...rest] : [...VISION_MODEL_CANDIDATES];
}

// Without this the function deploys ACTIVE but is never dispatched: only
// `handler` is exported, so invocations hang until the platform kills them.
Deno.serve(handler);

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.4";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) return json({ error: "Unauthorized" }, 401);

    const url = Deno.env.get("SUPABASE_URL")!;
    const userClient = createClient(url, Deno.env.get("SUPABASE_ANON_KEY")!, {
      global: { headers: { Authorization: authHeader } },
    });
    const admin = createClient(url, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);

    const { data: { user } } = await userClient.auth.getUser();
    if (!user) return json({ error: "Unauthorized" }, 401);

    const { data: roleRow } = await admin
      .from("user_roles")
      .select("role, is_approved")
      .eq("user_id", user.id)
      .maybeSingle();
    if (roleRow?.role !== "admin" || !roleRow?.is_approved) {
      return json({ error: "Admins only" }, 403);
    }

    const body = await req.json().catch(() => ({}));
    const topicId: string | undefined = body?.topicId;
    const count = Math.min(25, Math.max(1, Number(body?.count) || 10));
    const difficulty = ["easy", "medium", "hard"].includes(body?.difficulty) ? body.difficulty : "medium";
    if (!topicId || typeof topicId !== "string") return json({ error: "topicId is required" }, 400);

    const { data: topic } = await admin
      .from("topics")
      .select("id, name, description, subject_level_id")
      .eq("id", topicId)
      .maybeSingle();
    if (!topic) return json({ error: "Topic not found" }, 404);

    // Study notes live in study_materials (material_type='notes') — ground the
    // questions in the topic's actual notes rather than inventing content.
    const { data: notesRow } = await admin
      .from("study_materials")
      .select("content")
      .eq("topic_id", topicId)
      .eq("material_type", "notes")
      .limit(1)
      .maybeSingle();
    const notes = typeof notesRow?.content === "string" ? notesRow.content : "";

    let subjectName = "General Studies";
    let level = "OL";
    if (topic.subject_level_id) {
      const { data: sl } = await admin
        .from("subject_levels")
        .select("level, subjects(name)")
        .eq("id", topic.subject_level_id)
        .maybeSingle();
      if (sl) {
        level = sl.level;
        subjectName = (sl as any).subjects?.name ?? subjectName;
      }
    }
    const levelLabel = level === "OL" ? "IGCSE" : level === "AS" ? "AS Level" : "A2 Level";

    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) return json({ error: "AI is not configured" }, 500);

    // Notes can be very long — keep the prompt inside a sane window.
    const notesExcerpt = notes.length > 12000
      ? `${notes.slice(0, 12000)}\n[Notes truncated]`
      : notes;

    const prompt = `Create ${count} ${difficulty}-difficulty multiple-choice exam questions for ${levelLabel} ${subjectName}.
Topic: "${topic.name}".${topic.description ? ` Topic summary: ${topic.description}` : ""}
${notesExcerpt ? `
Study notes for this topic (ground EVERY question strictly in this material; do not invent content beyond it):
---
${notesExcerpt}
---
` : ""}
Rules:
- Exactly 4 answer options per question, only one correct.
- Exam-board style wording, unambiguous, syllabus appropriate for ${levelLabel}.
- Test understanding of the notes: definitions, facts, worked-example techniques and common-errors traps they highlight.
- Include a concise explanation (1-3 sentences) for the correct answer.
- correct_option is the zero-based index of the correct option.`;

    const response = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: { Authorization: `Bearer ${LOVABLE_API_KEY}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "google/gemini-3-flash-preview",
        messages: [
          { role: "system", content: "You are an expert examiner who writes high-quality multiple-choice questions. Always reply with the requested tool call." },
          { role: "user", content: prompt },
        ],
        tools: [{
          type: "function",
          function: {
            name: "submit_questions",
            description: "Submit the generated multiple-choice questions",
            parameters: {
              type: "object",
              properties: {
                questions: {
                  type: "array",
                  items: {
                    type: "object",
                    properties: {
                      question_text: { type: "string" },
                      options: { type: "array", items: { type: "string" }, minItems: 4, maxItems: 4 },
                      correct_option: { type: "integer", minimum: 0, maximum: 3 },
                      explanation: { type: "string" },
                    },
                    required: ["question_text", "options", "correct_option", "explanation"],
                    additionalProperties: false,
                  },
                },
              },
              required: ["questions"],
              additionalProperties: false,
            },
          },
        }],
        tool_choice: { type: "function", function: { name: "submit_questions" } },
      }),
    });

    if (!response.ok) {
      if (response.status === 429) return json({ error: "Rate limit reached, please try again shortly." }, 429);
      if (response.status === 402) return json({ error: "AI credits exhausted. Please add credits to your workspace." }, 402);
      console.error("AI gateway error", response.status, await response.text());
      return json({ error: "AI gateway error" }, 500);
    }

    const data = await response.json();
    const args = data?.choices?.[0]?.message?.tool_calls?.[0]?.function?.arguments;
    let parsed: any;
    try {
      parsed = typeof args === "string" ? JSON.parse(args) : args;
    } catch {
      return json({ error: "AI returned an unreadable response" }, 502);
    }

    const generated = (parsed?.questions ?? []).filter((q: any) =>
      q && typeof q.question_text === "string" &&
      Array.isArray(q.options) && q.options.length === 4 &&
      Number.isInteger(q.correct_option) && q.correct_option >= 0 && q.correct_option <= 3
    ).slice(0, count);

    if (generated.length === 0) return json({ error: "The AI did not return any usable questions" }, 502);

    const title = typeof body?.quizTitle === "string" && body.quizTitle.trim()
      ? body.quizTitle.trim().slice(0, 120)
      : `AI Practice — ${topic.name} (${level})`;

    const { data: quiz, error: quizError } = await admin
      .from("quizzes")
      .insert({
        title,
        description: `AI-generated ${difficulty} question set for ${subjectName} ${level}.`,
        topic_id: topic.id,
        is_published: body?.publish === false ? false : true,
      })
      .select("id, title")
      .single();
    if (quizError) throw quizError;

    const rows = generated.map((q: any, i: number) => ({
      quiz_id: quiz.id,
      question_text: String(q.question_text).slice(0, 2000),
      options: q.options.map((o: unknown) => String(o).slice(0, 500)),
      correct_option: q.correct_option,
      explanation: typeof q.explanation === "string" ? q.explanation.slice(0, 1000) : null,
      sort_order: i,
    }));

    const { error: qError } = await admin.from("questions").insert(rows);
    if (qError) throw qError;

    return json({ quizId: quiz.id, title: quiz.title, count: rows.length });
  } catch (e) {
    console.error("generate-questions failed", e);
    return json({ error: "Failed to generate questions" }, 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.4";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("Missing authorization header");

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseAnonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const userClient = createClient(supabaseUrl, supabaseAnonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const admin = createClient(supabaseUrl, serviceKey);

    const { data: { user }, error: authError } = await userClient.auth.getUser();
    if (authError || !user) throw new Error("Not authenticated");

    // Approval gate
    const { data: roleRow } = await admin
      .from("user_roles")
      .select("is_approved, role")
      .eq("user_id", user.id)
      .maybeSingle();
    if (!roleRow?.is_approved && roleRow?.role !== "admin") {
      return new Response(
        JSON.stringify({ error: "Account not yet approved" }),
        { status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const body = await req.json().catch(() => ({}));
    const quizId: string | undefined = body?.quizId;
    const answers: Record<string, number> | undefined = body?.answers;

    if (!quizId || typeof quizId !== "string" || !answers || typeof answers !== "object") {
      return new Response(
        JSON.stringify({ error: "quizId and answers are required" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Verify the user has actually attempted this quiz (anti-abuse)
    const { data: attempt } = await admin
      .from("quiz_attempts")
      .select("id")
      .eq("user_id", user.id)
      .eq("quiz_id", quizId)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (!attempt) {
      return new Response(
        JSON.stringify({ error: "No attempt found for this quiz" }),
        { status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Fetch quiz + questions from DB (NEVER trust client-supplied text)
    const { data: quiz } = await admin
      .from("quizzes")
      .select("id, title, topics(name)")
      .eq("id", quizId)
      .maybeSingle();
    if (!quiz) throw new Error("Quiz not found");

    const { data: questions } = await admin
      .from("questions")
      .select("id, question_text, options, correct_option, explanation")
      .eq("quiz_id", quizId)
      .order("sort_order");

    if (!questions || questions.length === 0) throw new Error("No questions found");

    const wrong = questions.filter((q: any) => {
      const sel = answers[q.id];
      return typeof sel !== "number" || sel !== q.correct_option;
    });
    const totalQuestions = questions.length;
    const correctCount = totalQuestions - wrong.length;

    if (wrong.length === 0) {
      return new Response(
        JSON.stringify({
          feedback:
            "🎉 Perfect score! You answered every question correctly. Keep up the excellent work!",
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

